INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u6-C1','math',2,1,'u6',2,'여러 가지 방법으로 세기 — 물건의 수를 하나씩·뛰어·묶어 세어 보고, 수가 많을 때 같은 수씩 묶어 뛰어 세면 빠르고 덜 헷갈림을 알기',ARRAY['2수01-09']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u6-C2','math',2,1,'u6',3,'묶어 세기 — 물건을 같은 수씩 묶어 「몇씩 몇 묶음」으로 나타내고, 뛰어 세어 모두 몇 개인지 구하며, 같은 물건도 여러 가지로 묶을 수 있음을 알기',ARRAY['2수01-09']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u6-C3','math',2,1,'u6',4,'몇의 몇 배 — 몇씩 몇 묶음을 「몇의 몇 배」로 나타내고(한 묶음 = 1배), 같은 수도 묶는 수가 달라지면 몇 배가 달라짐을 알기',ARRAY['2수01-09']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u6-C4','math',2,1,'u6',5,'두 양을 몇의 몇 배로 나타내기 — 기준이 되는 양을 정해 개수와 색 막대의 길이를 몇의 몇 배로 견주고, 기준을 겹치지 않게 이어 붙인 횟수가 몇 배임을 알기',ARRAY['2수01-09']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u6-C5','math',2,1,'u6',6,'곱셈 알기 — 몇의 몇 배를 곱셈 기호 ×로 나타내고(3 × 6), 같은 수를 여러 번 더한 것을 곱셈식으로 쓰며, 「곱하기」·「곱」으로 읽기',ARRAY['2수01-09']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u6-C6','math',2,1,'u6',7,'곱셈식으로 나타내기 — 생활 속 상황과 물건의 수를 곱셈식으로 나타내고, 묶는 방법에 따라 여러 곱셈식이 나오며 4 × 6과 6 × 4의 곱이 같음을 알기',ARRAY['2수01-09']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u6-C7','math',2,1,'u6',9,'한 상황을 여러 가지로 나타내기 — 같은 그림을 덧셈식·몇씩 몇 묶음·몇의 몇 배·곱셈식으로 서로 이어 나타내고 곱셈 카드로 만들기',ARRAY['2수01-09']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u6-X01','math',2,'u6',ARRAY['M2-1-u6-C1']::text[],'하나씩 세기가 늘 가장 빠르다고 여기거나, 묶어 세기·뛰어 세기가 왜 편리한지 모른다','셀 것이 많을 때 같은 수씩 묶어 뛰어 세면 빠르고 덜 헷갈려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u6-X02','math',2,'u6',ARRAY['M2-1-u6-C1','M2-1-u6-C2','M2-1-u6-C5']::text[],'뛰어 세기에서 같은 수씩 뛰지 않거나 한 번 더·덜 뛰어 곱을 틀린다','뛸 때마다 손가락을 하나씩 접어 몇 번 뛰었는지 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u6-X03','math',2,'u6',ARRAY['M2-1-u6-C2','M2-1-u6-C3']::text[],'같은 수씩 묶지 않거나 남는 것이 있게 묶고, 묶음의 수를 하나 더·덜 센다','묶음마다 개수가 똑같은지, 남은 것은 없는지 확인하고 묶음에 번호 붙이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u6-X04','math',2,'u6',ARRAY['M2-1-u6-C2']::text[],'「몇씩」(한 묶음 안의 수)과 「몇 묶음」(묶음의 수)을 뒤바꾼다','「몇씩」은 한 묶음 안을, 「몇 묶음」은 동그라미의 수를 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u6-X05','math',2,'u6',ARRAY['M2-1-u6-C2','M2-1-u6-C3','M2-1-u6-C4']::text[],'묶음의 수나 한 묶음의 수를 전체 수로 답하거나, 전체 수를 묶음 수·몇 배로 쓴다','전체(모두 몇 개)·한 묶음·묶음 수를 각각 손가락으로 짚어 가리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u6-X06','math',2,'u6',ARRAY['M2-1-u6-C2','M2-1-u6-C3','M2-1-u6-C6']::text[],'「몇씩 몇 묶음」·「몇의 몇 배」를 두 수를 더해서 구한다(5씩 4묶음 = 9)','두 수를 더하지 말고 한 묶음의 수만큼 묶음 수번 뛰어 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u6-X07','math',2,'u6',ARRAY['M2-1-u6-C3']::text[],'「몇의 몇 배」에서 한 묶음의 수와 묶음의 수를 뒤바꾼다(4씩 3묶음 → 3의 4배)','「몇의」에는 한 묶음의 수, 「몇 배」에는 묶음의 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u6-X08','math',2,'u6',ARRAY['M2-1-u6-C3']::text[],'같은 수를 다르게 묶어도 몇 배는 그대로라고 여기거나, 묶는 수가 커지면 몇 배도 커진다고 여긴다','같은 물건을 묶는 수를 바꾸어 다시 묶고 묶음 수를 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u6-X09','math',2,'u6',ARRAY['M2-1-u6-C4']::text[],'두 양을 견줄 때 기준을 거꾸로 잡거나, 두 양의 차이·전체 수·칸 수를 그대로 몇 배라고 말한다','「무엇의」 몇 배인지 기준을 먼저 찾고, 기준만큼씩 묶어 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u6-X10','math',2,'u6',ARRAY['M2-1-u6-C4']::text[],'기준 막대를 겹쳐 놓거나 이어 붙인 횟수를 하나 더·덜 세고, 몇 배를 두 막대를 더한 길이로 여긴다','기준 막대를 겹치지 않게 이어 붙이며 한 번 놓을 때마다 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u6-X11','math',2,'u6',ARRAY['M2-1-u6-C5','M2-1-u6-C6']::text[],'× 를 + 로 여기거나 곱셈식을 잘못 읽는다(3 × 6 = 9, 「3 더하기 6」)','× 는 「곱하기」 — 앞의 수를 뒤의 수만큼 여러 번 더한 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u6-X12','math',2,'u6',ARRAY['M2-1-u6-C5']::text[],'같은 수의 덧셈을 곱셈식으로 바꿀 때 더한 횟수를 잘못 센다(더하기 기호의 수를 곱하는 수로 씀)','더하기 기호가 아니라 더한 수가 몇 번 나오는지 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u6-X13','math',2,'u6',ARRAY['M2-1-u6-C2','M2-1-u6-C6']::text[],'곱하는 두 수의 순서를 바꾸면 곱도 달라진다고 여기거나, 한 물건은 한 가지로만 묶거나 곱셈식으로 나타낼 수 있다고 여긴다','같은 그림을 가로로 한 번, 세로로 한 번 묶어 두 곱셈식을 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u6-X14','math',2,'u6',ARRAY['M2-1-u6-C6']::text[],'생활 속 상황에서 한 묶음의 수와 묶음의 수를 잘못 잡는다(다리 수와 마리 수를 헷갈림)','「한 ○에 몇 개씩」이 한 묶음, 「○가 몇」이 묶음 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u6-X15','math',2,'u6',ARRAY['M2-1-u6-C1','M2-1-u6-C2','M2-1-u6-C3','M2-1-u6-C4','M2-1-u6-C5','M2-1-u6-C6','M2-1-u6-C7']::text[],'묻는 말을 거꾸로 읽는다 — 아닌 것↔맞는 것, 잘못된↔바른','물음의 「아닌·잘못된」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L02_basic#1','math',2,1,'u6','L02','g2_1_math_u6_L02_basic','lesson_basic','M2-1-u6-C1',1,'mc','auto','물건이 아주 많을 때 빠르고 정확하게 세는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M2-1-u6-X01']::text[],true,'{"seq":1,"concept":"M2-1-u6-C1","difficulty":1,"kind":"mc","stem":"물건이 아주 많을 때 빠르고 정확하게 세는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"같은 수씩 묶어서 세요","correct":true},{"t":"손에 잡히는 대로 아무거나 세요","mis":"M2-1-u6-X01"},{"t":"세지 않고 어림해서 말해요","mis":"M2-1-u6-X01"}],"explanation":["물건이 많으면 하나씩 세다가 놓치기 쉬워요.","같은 수씩 묶으면 5, 10, 15처럼 뛰어 셀 수 있어요.","그래서 빠르고 덜 헷갈려요."],"variant_rule":{"alt":[{"stem":"체육관에 공이 아주 많아요. 공의 수를 빠르게 세는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"5개씩 묶어 5, 10, 15, …로 세요","correct":true},{"t":"보이는 공만 대충 세요","mis":"M2-1-u6-X01"},{"t":"하나씩 세다가 헷갈리면 처음부터 다시 세요","mis":"M2-1-u6-X01"}],"explanation":["공이 많으면 하나씩 세기가 어려워요.","5개씩 묶으면 5씩 뛰어 셀 수 있어요.","묶어 세면 빠르고 정확해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L02_basic#2','math',2,1,'u6','L02','g2_1_math_u6_L02_basic','lesson_basic','M2-1-u6-C1',1,'mc','auto','그림을 보세요. 사탕은 모두 몇 개인가요?',ARRAY['M2-1-u6-X06','M2-1-u6-X05']::text[],true,'{"seq":2,"concept":"M2-1-u6-C1","difficulty":1,"kind":"mc","stem":"그림을 보세요. 사탕은 모두 몇 개인가요?","explanation":["3개씩 4묶음이에요.","3씩 뛰어 세면 3, 6, 9, 12.","사탕은 모두 12개예요."],"variant_rule":{"mul":{"ask":"total"}},"options":[{"t":"12개","correct":true},{"t":"7개","mis":"M2-1-u6-X06"},{"t":"4개","mis":"M2-1-u6-X05"}],"asset":{"type":"mul_groups","item":"🍬","k":3,"n":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L02_basic#3','math',2,1,'u6','L02','g2_1_math_u6_L02_basic','lesson_basic','M2-1-u6-C1',1,'sa','auto','3씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-1-u6-C1","difficulty":1,"kind":"sa","stem":"3씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["3씩 커지는 수예요.","9에서 3만큼 더 뛰면 12예요.","3씩 4번 뛰어 센 수 — 3씩 4묶음과 같아요."],"variant_rule":{"mul":{"ask":"skip"}},"answer":["12"],"asset":{"type":"jump_row","cells":[3,6,9,null],"step":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L02_basic#4','math',2,1,'u6','L02','g2_1_math_u6_L02_basic','lesson_basic','M2-1-u6-C1',1,'ox','auto','하나씩 세면 셀 것이 많을 때 시간이 오래 걸리고 헷갈리기 쉬워요.',ARRAY['M2-1-u6-X01']::text[],true,'{"seq":4,"concept":"M2-1-u6-C1","difficulty":1,"kind":"ox","stem":"하나씩 세면 셀 것이 많을 때 시간이 오래 걸리고 헷갈리기 쉬워요.","answer":"O","reason_options":[{"t":"셀 것이 많으면 어디까지 셌는지 놓치기 쉬우니까","correct":true},{"t":"하나씩 세는 것이 언제나 가장 빠르니까","mis":"M2-1-u6-X01"}],"mis":"M2-1-u6-X01","explanation":["하나씩 세기는 정확하지만 느려요.","수가 많으면 어디까지 셌는지 헷갈리기 쉬워요.","그래서 뛰어 세기나 묶어 세기를 써요."],"variant_rule":{"alt":[{"stem":"3, 6, 9, 12처럼 뛰어 세면 하나씩 세는 것보다 빨라요.","answer":"O","reason_options":[{"t":"한 번에 3개씩 건너뛰며 세니까","correct":true},{"t":"뛰어 세면 세는 수가 더 많아지니까","mis":"M2-1-u6-X01"}],"explanation":["3씩 뛰어 세면 한 번에 3개씩 세는 셈이에요.","하나씩 열두 번 셀 것을 네 번 만에 세요.","그래서 더 빨라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L02_basic#5','math',2,1,'u6','L02','g2_1_math_u6_L02_basic','lesson_basic','M2-1-u6-C1',2,'mc','auto','그림의 사탕을 5개씩 묶으면 몇 묶음인가요?',ARRAY['M2-1-u6-X04','M2-1-u6-X05']::text[],true,'{"seq":5,"concept":"M2-1-u6-C1","difficulty":2,"kind":"mc","stem":"그림의 사탕을 5개씩 묶으면 몇 묶음인가요?","explanation":["사탕은 모두 15개예요.","5개씩 묶으면 5, 10, 15 — 3번 묶여요.","그래서 5씩 3묶음이에요."],"variant_rule":{"mul":{"ask":"groups"}},"options":[{"t":"3묶음","correct":true},{"t":"5묶음","mis":"M2-1-u6-X04"},{"t":"15묶음","mis":"M2-1-u6-X05"}],"asset":{"type":"mul_groups","item":"🍬","look":"loose","total":15,"cols":7}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L02_basic#6','math',2,1,'u6','L02','g2_1_math_u6_L02_basic','lesson_basic','M2-1-u6-C1',2,'mc','auto','알맞게 뛰어 센 것은 어느 것인가요?',ARRAY['M2-1-u6-X02']::text[],true,'{"seq":6,"concept":"M2-1-u6-C1","difficulty":2,"kind":"mc","stem":"알맞게 뛰어 센 것은 어느 것인가요?","options":[{"t":"3, 6, 9, 12","correct":true},{"t":"3, 4, 5, 6","mis":"M2-1-u6-X02"},{"t":"3, 6, 8, 12","mis":"M2-1-u6-X02"}],"explanation":["3씩 뛰어 세면 3씩 커져요.","3, 6, 9, 12가 알맞아요.","3, 6, 8은 6에서 2만 커졌어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알맞게 뛰어 센 것은 어느 것인가요?","options":[{"t":"4, 8, 12, 16","correct":true},{"t":"4, 5, 6, 7","mis":"M2-1-u6-X02"},{"t":"4, 8, 10, 12","mis":"M2-1-u6-X02"}],"explanation":["4씩 뛰어 세면 4씩 커져요.","4, 8, 12, 16이 알맞아요.","4, 8, 10은 8에서 2만 커졌어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L02_basic#7','math',2,1,'u6','L02','g2_1_math_u6_L02_basic','lesson_basic','M2-1-u6-C1',2,'mc','auto','4씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요?',ARRAY['M2-1-u6-X02']::text[],true,'{"seq":7,"concept":"M2-1-u6-C1","difficulty":2,"kind":"mc","stem":"4씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요?","explanation":["4씩 커지는 수예요.","16에서 4만큼 더 뛰면 20이에요.","4씩 5번 뛰어 센 수 — 4씩 5묶음과 같아요."],"variant_rule":{"mul":{"ask":"skip"}},"options":[{"t":"20","correct":true},{"t":"17","mis":"M2-1-u6-X02"},{"t":"24","mis":"M2-1-u6-X02"}],"asset":{"type":"jump_row","cells":[4,8,12,16,null],"step":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L02_basic#8','math',2,1,'u6','L02','g2_1_math_u6_L02_basic','lesson_basic','M2-1-u6-C1',2,'match','auto','묶어 센 것과 모두 몇 개인지를 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M2-1-u6-C1","difficulty":2,"kind":"match","stem":"묶어 센 것과 모두 몇 개인지를 이으세요.","pairs":[{"l":"2씩 4묶음","r":"8개"},{"l":"5씩 3묶음","r":"15개"},{"l":"3씩 3묶음","r":"9개"}],"mis":"M2-1-u6-X06","explanation":["2씩 4묶음은 2, 4, 6, 8로 8개예요.","5씩 3묶음은 5, 10, 15로 15개예요.","3씩 3묶음은 3, 6, 9로 9개예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 묶어 센 것과 모두 몇 개인지를 이으세요.","pairs":[{"l":"4씩 2묶음","r":"8개"},{"l":"3씩 5묶음","r":"15개"},{"l":"2씩 6묶음","r":"12개"}],"explanation":["4씩 2묶음은 4, 8로 8개예요.","3씩 5묶음은 3, 6, 9, 12, 15로 15개예요.","2씩 6묶음은 2, 4, 6, 8, 10, 12로 12개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L02_basic#9','math',2,1,'u6','L02','g2_1_math_u6_L02_basic','lesson_basic','M2-1-u6-C1',2,'mc','auto','그림을 보세요. 달걀은 모두 몇 개인가요?',ARRAY['M2-1-u6-X06','M2-1-u6-X05']::text[],true,'{"seq":9,"concept":"M2-1-u6-C1","difficulty":2,"kind":"mc","stem":"그림을 보세요. 달걀은 모두 몇 개인가요?","explanation":["한 줄에 4개씩 3줄이에요.","4씩 뛰어 세면 4, 8, 12.","달걀은 모두 12개예요."],"variant_rule":{"mul":{"ask":"total","look":"rows"}},"options":[{"t":"12개","correct":true},{"t":"7개","mis":"M2-1-u6-X06"},{"t":"3개","mis":"M2-1-u6-X05"}],"asset":{"type":"mul_groups","item":"🥚","k":4,"n":3,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L02_basic#10','math',2,1,'u6','L02','g2_1_math_u6_L02_basic','lesson_basic','M2-1-u6-C1',3,'error','auto','친구들이 사탕 12개를 세었어요. 잘못 센 친구는 누구인가요?',ARRAY['M2-1-u6-X02','M2-1-u6-X15']::text[],true,'{"seq":10,"concept":"M2-1-u6-C1","difficulty":3,"kind":"error","stem":"친구들이 사탕 12개를 세었어요. 잘못 센 친구는 누구인가요?","options":[{"t":"지우 — 「3씩 뛰어 세면 3, 6, 9, 11이니까 11개야.」","correct":true,"mis_target":"M2-1-u6-X02"},{"t":"서아 — 「하나씩 세면 하나, 둘, …, 열둘이니까 12개야.」","mis":"M2-1-u6-X15"},{"t":"하루 — 「4씩 묶으면 4, 8, 12니까 12개야.」","mis":"M2-1-u6-X15"}],"explanation":["3씩 뛰어 세면 3, 6, 9, 12예요.","지우는 9 다음에 2만 뛰었어요.","서아와 하루는 바르게 셌어요."],"variant_rule":{"alt":[{"stem":"친구들이 쿠키 15개를 세었어요. 잘못 센 친구는 누구인가요?","options":[{"t":"다예 — 「5씩 뛰어 세면 5, 10, 14니까 14개야.」","correct":true,"mis_target":"M2-1-u6-X02"},{"t":"곰이 — 「3씩 묶으면 3, 6, 9, 12, 15니까 15개야.」","mis":"M2-1-u6-X15"},{"t":"펭이 — 「5씩 묶으면 5, 10, 15니까 15개야.」","mis":"M2-1-u6-X15"}],"explanation":["5씩 뛰어 세면 5, 10, 15예요.","다예는 10 다음에 4만 뛰었어요.","곰이와 펭이는 바르게 셌어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
