INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L02_challenge#2','math',2,1,'u6','L02','g2_1_math_u6_L02_challenge','lesson_challenge','M2-1-u6-C1',2,'mc','auto','딱지 12장을 같은 수씩 묶어 세려고 해요. 바르게 묶은 것은 어느 것인가요?',ARRAY['M2-1-u6-X03']::text[],false,'{"seq":2,"concept":"M2-1-u6-C1","difficulty":2,"kind":"mc","stem":"딱지 12장을 같은 수씩 묶어 세려고 해요. 바르게 묶은 것은 어느 것인가요?","options":[{"t":"3장씩 4묶음","correct":true},{"t":"5장씩 2묶음과 2장","mis":"M2-1-u6-X03"},{"t":"4장, 3장, 5장씩 3묶음","mis":"M2-1-u6-X03"}],"explanation":["묶어 셀 때는 묶음마다 같은 수씩 묶어요.","3장씩 4묶음이면 3, 6, 9, 12로 남김없이 셀 수 있어요.","남는 것이 있거나 묶음마다 수가 다르면 뛰어 세기가 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
