INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L02_challenge#4','math',2,1,'u6','L02','g2_1_math_u6_L02_challenge','lesson_challenge','M2-1-u6-C1',3,'mc','auto','구슬 20개를 가장 빠르고 정확하게 셀 수 있는 방법은 어느 것인가요?',ARRAY['M2-1-u6-X01','M2-1-u6-X02']::text[],false,'{"seq":4,"concept":"M2-1-u6-C1","difficulty":3,"kind":"mc","stem":"구슬 20개를 가장 빠르고 정확하게 셀 수 있는 방법은 어느 것인가요?","options":[{"t":"5개씩 묶어 5, 10, 15, 20으로 세요","correct":true},{"t":"하나, 둘, 셋, …으로 하나씩 세요","mis":"M2-1-u6-X01"},{"t":"2, 3, 4, 5처럼 1씩 커지게 세요","mis":"M2-1-u6-X02"}],"explanation":["20개를 하나씩 세면 스무 번 세야 해요.","5개씩 묶으면 네 번 만에 셀 수 있어요.","2, 3, 4, 5는 1씩 세는 것과 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L02_challenge#5','math',2,1,'u6','L02','g2_1_math_u6_L02_challenge','lesson_challenge','M2-1-u6-C1',3,'mc','auto','그림의 딸기를 4개씩 묶으면 몇 묶음인가요?',ARRAY['M2-1-u6-X04','M2-1-u6-X05','M2-1-u6-X03']::text[],true,'{"seq":5,"concept":"M2-1-u6-C1","difficulty":3,"kind":"mc","stem":"그림의 딸기를 4개씩 묶으면 몇 묶음인가요?","explanation":["딸기는 모두 24개예요.","4개씩 묶으면 4, 8, 12, 16, 20, 24 — 6번 묶여요.","그래서 4씩 6묶음이에요."],"variant_rule":{"mul":{"ask":"groups"}},"options":[{"t":"6묶음","correct":true},{"t":"4묶음","mis":"M2-1-u6-X04"},{"t":"24묶음","mis":"M2-1-u6-X05"},{"t":"7묶음","mis":"M2-1-u6-X03"}],"asset":{"type":"mul_groups","item":"🍓","look":"loose","total":24,"cols":7}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L02_challenge#6','math',2,1,'u6','L02','g2_1_math_u6_L02_challenge','lesson_challenge','M2-1-u6-C1',3,'error','auto','친구들이 5씩 뛰어 세었어요. 잘못 뛰어 센 친구는 누구인가요?',ARRAY['M2-1-u6-X02','M2-1-u6-X15']::text[],false,'{"seq":6,"concept":"M2-1-u6-C1","difficulty":3,"kind":"error","stem":"친구들이 5씩 뛰어 세었어요. 잘못 뛰어 센 친구는 누구인가요?","options":[{"t":"로아 — 「5, 10, 15, 25」","correct":true,"mis_target":"M2-1-u6-X02"},{"t":"준우 — 「5, 10, 15, 20」","mis":"M2-1-u6-X15"},{"t":"하린 — 「10, 15, 20, 25」","mis":"M2-1-u6-X15"}],"explanation":["5씩 뛰어 세면 5씩 커져요.","로아는 15 다음에 10을 뛰었어요.","하린이는 10부터 시작했지만 5씩 바르게 뛰었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L02_challenge#7','math',2,1,'u6','L02','g2_1_math_u6_L02_challenge','lesson_challenge','M2-1-u6-C1',3,'sa','auto','봉지 한 개에 사탕이 5개씩 있어요. 봉지 4개의 사탕은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M2-1-u6-C1","difficulty":3,"kind":"sa","stem":"봉지 한 개에 사탕이 5개씩 있어요. 봉지 4개의 사탕은 모두 몇 개인가요? 숫자로 쓰세요.","explanation":["봉지 한 개에 5개씩, 4개이면 5씩 4묶음이에요.","5 × 4 = 20이에요.","사탕은 모두 20개예요."],"variant_rule":{"mul":{"ask":"story"}},"answer":["20","20개"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L02_challenge#8','math',2,1,'u6','L02','g2_1_math_u6_L02_challenge','lesson_challenge','M2-1-u6-C1',4,'essay','teacher','딱지 18장을 세려고 해요. 하나씩 세는 방법과 묶어 세는 방법을 견주어, 묶어 세기가 편리한 까닭을 쓰고 몇씩 몇 묶음인지 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-1-u6-C1","difficulty":4,"kind":"essay","stem":"딱지 18장을 세려고 해요. 하나씩 세는 방법과 묶어 세는 방법을 견주어, 묶어 세기가 편리한 까닭을 쓰고 몇씩 몇 묶음인지 써 보세요.","answer_guide":{"answer":"예: 하나씩 세면 열여덟 번 세야 해서 오래 걸리고 헷갈리기 쉽다. 6장씩 묶으면 6, 12, 18로 세 번 만에 셀 수 있다. 6씩 3묶음이다.","scoring_points":["하나씩 세기는 오래 걸리고 헷갈리기 쉽다고 썼는가","같은 수씩 묶으면 뛰어 세어 빠르다고 썼는가","18장을 남김없이 묶는 「몇씩 몇 묶음」을 바르게 썼는가"]},"explanation":["하나씩 세면 정확하지만 느려요.","같은 수씩 묶으면 뛰어 셀 수 있어요.","2씩 9묶음, 3씩 6묶음, 6씩 3묶음, 9씩 2묶음 모두 18장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L02_challenge#9','math',2,1,'u6','L02','g2_1_math_u6_L02_challenge','lesson_challenge','M2-1-u6-C1',4,'essay','teacher','그림의 사과를 두 가지 방법으로 묶어 「몇씩 몇 묶음」으로 쓰고, 뛰어 세어 모두 몇 개인지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-1-u6-C1","difficulty":4,"kind":"essay","stem":"그림의 사과를 두 가지 방법으로 묶어 「몇씩 몇 묶음」으로 쓰고, 뛰어 세어 모두 몇 개인지 써 보세요.","answer_guide":{"answer":"예: 4씩 5묶음 — 4, 8, 12, 16, 20. 5씩 4묶음 — 5, 10, 15, 20. 사과는 모두 20개이다.","scoring_points":["한 가지 방법으로 남김없이 묶어 「몇씩 몇 묶음」으로 썼는가","다른 방법으로도 남김없이 묶어 썼는가","뛰어 세어 모두 20개라고 썼는가"]},"explanation":["20개는 여러 가지로 묶을 수 있어요.","4씩 5묶음, 5씩 4묶음, 2씩 10묶음 등이 있어요.","어떻게 묶어도 모두 20개예요."],"asset":{"type":"mul_groups","item":"🍎","look":"loose","total":20,"cols":7}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L02_challenge#10','math',2,1,'u6','L02','g2_1_math_u6_L02_challenge','lesson_challenge','M2-1-u6-C1',4,'mc','auto','공깃돌을 6씩 뛰어 세었더니 6, 12, 18, 24, 30이었어요. 공깃돌을 「몇씩 몇 묶음」으로 나타내고 모두 몇 개인지 바르게 말한 것은 어느 것인가요?',ARRAY['M2-1-u6-X04','M2-1-u6-X06','M2-1-u6-X03']::text[],false,'{"seq":10,"concept":"M2-1-u6-C1","difficulty":4,"kind":"mc","stem":"공깃돌을 6씩 뛰어 세었더니 6, 12, 18, 24, 30이었어요. 공깃돌을 「몇씩 몇 묶음」으로 나타내고 모두 몇 개인지 바르게 말한 것은 어느 것인가요?","options":[{"t":"6씩 5묶음, 30개","correct":true},{"t":"5씩 6묶음, 30개","mis":"M2-1-u6-X04"},{"t":"6씩 5묶음, 11개","mis":"M2-1-u6-X06"},{"t":"6씩 6묶음, 36개","mis":"M2-1-u6-X03"}],"explanation":["6씩 뛰어 센 수가 6, 12, 18, 24, 30으로 다섯 개예요.","6씩 5묶음이고 마지막 수 30이 모두 몇 개인지 알려 줘요.","6과 5를 더한 11은 공깃돌의 수가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L03_basic#1','math',2,1,'u6','L03','g2_1_math_u6_L03_basic','lesson_basic','M2-1-u6-C2',1,'mc','auto','그림을 「몇씩 몇 묶음」으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u6-X04','M2-1-u6-X03']::text[],true,'{"seq":1,"concept":"M2-1-u6-C2","difficulty":1,"kind":"mc","stem":"그림을 「몇씩 몇 묶음」으로 바르게 나타낸 것은 어느 것인가요?","explanation":["한 묶음에 공이 5개씩 있어요.","묶음은 모두 4개예요.","그래서 5씩 4묶음이에요 — 「몇씩」은 한 묶음 안의 수, 「몇 묶음」은 묶음의 수예요."],"variant_rule":{"mul":{"ask":"name"}},"options":[{"t":"5씩 4묶음","correct":true},{"t":"4씩 5묶음","mis":"M2-1-u6-X04"},{"t":"5씩 5묶음","mis":"M2-1-u6-X03"}],"asset":{"type":"mul_groups","item":"⚽","k":5,"n":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L03_basic#2','math',2,1,'u6','L03','g2_1_math_u6_L03_basic','lesson_basic','M2-1-u6-C2',1,'mc','auto','그림을 보세요. 딸기는 모두 몇 개인가요?',ARRAY['M2-1-u6-X06','M2-1-u6-X05']::text[],true,'{"seq":2,"concept":"M2-1-u6-C2","difficulty":1,"kind":"mc","stem":"그림을 보세요. 딸기는 모두 몇 개인가요?","explanation":["2개씩 5묶음이에요.","2씩 뛰어 세면 2, 4, 6, 8, 10.","딸기는 모두 10개예요."],"variant_rule":{"mul":{"ask":"total"}},"options":[{"t":"10개","correct":true},{"t":"7개","mis":"M2-1-u6-X06"},{"t":"5개","mis":"M2-1-u6-X05"}],"asset":{"type":"mul_groups","item":"🍓","k":2,"n":5}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L03_basic#3','math',2,1,'u6','L03','g2_1_math_u6_L03_basic','lesson_basic','M2-1-u6-C2',1,'mc','auto','공 20개를 같은 수씩 남김없이 묶는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M2-1-u6-X03']::text[],true,'{"seq":3,"concept":"M2-1-u6-C2","difficulty":1,"kind":"mc","stem":"공 20개를 같은 수씩 남김없이 묶는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"5씩 4묶음","correct":true},{"t":"5씩 5묶음","mis":"M2-1-u6-X03"},{"t":"3씩 4묶음","mis":"M2-1-u6-X03"}],"explanation":["5씩 4묶음은 5, 10, 15, 20으로 20개예요.","5씩 5묶음은 25개, 3씩 4묶음은 12개예요.","묶은 뒤 뛰어 세어 20이 되는지 확인해요."],"variant_rule":{"alt":[{"stem":"콩 주머니 18개를 같은 수씩 남김없이 묶는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"6씩 3묶음","correct":true},{"t":"6씩 4묶음","mis":"M2-1-u6-X03"},{"t":"5씩 3묶음","mis":"M2-1-u6-X03"}],"explanation":["6씩 3묶음은 6, 12, 18로 18개예요.","6씩 4묶음은 24개, 5씩 3묶음은 15개예요.","묶은 뒤 뛰어 세어 18이 되는지 확인해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L03_basic#4','math',2,1,'u6','L03','g2_1_math_u6_L03_basic','lesson_basic','M2-1-u6-C2',1,'ox','auto','같은 공 20개를 5씩 4묶음으로도, 4씩 5묶음으로도 묶을 수 있어요.',ARRAY['M2-1-u6-X13']::text[],true,'{"seq":4,"concept":"M2-1-u6-C2","difficulty":1,"kind":"ox","stem":"같은 공 20개를 5씩 4묶음으로도, 4씩 5묶음으로도 묶을 수 있어요.","answer":"O","reason_options":[{"t":"묶는 방법은 여러 가지이고 어떻게 묶어도 20개니까","correct":true},{"t":"묶는 방법은 한 가지로 정해져 있으니까","mis":"M2-1-u6-X13"}],"mis":"M2-1-u6-X13","explanation":["같은 물건도 여러 가지로 묶을 수 있어요.","5씩 4묶음은 5, 10, 15, 20, 4씩 5묶음은 4, 8, 12, 16, 20이에요.","묶는 방법이 달라도 모두 20개예요."],"variant_rule":{"alt":[{"stem":"사과 12개는 3씩 4묶음으로만 묶을 수 있어요.","answer":"X","reason_options":[{"t":"2씩 6묶음, 4씩 3묶음, 6씩 2묶음으로도 묶을 수 있으니까","correct":true},{"t":"한 물건은 한 가지 방법으로만 묶어야 하니까","mis":"M2-1-u6-X13"}],"explanation":["12개는 여러 가지로 묶을 수 있어요.","2씩 6묶음, 3씩 4묶음, 4씩 3묶음, 6씩 2묶음 모두 12개예요.","그래서 「~으로만」은 틀린 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L03_basic#5','math',2,1,'u6','L03','g2_1_math_u6_L03_basic','lesson_basic','M2-1-u6-C2',2,'mc','auto','그림의 공을 6개씩 묶으면 몇 묶음인가요?',ARRAY['M2-1-u6-X04','M2-1-u6-X05']::text[],true,'{"seq":5,"concept":"M2-1-u6-C2","difficulty":2,"kind":"mc","stem":"그림의 공을 6개씩 묶으면 몇 묶음인가요?","explanation":["공은 모두 18개예요.","6개씩 묶으면 6, 12, 18 — 3번 묶여요.","그래서 6씩 3묶음이에요."],"variant_rule":{"mul":{"ask":"groups"}},"options":[{"t":"3묶음","correct":true},{"t":"6묶음","mis":"M2-1-u6-X04"},{"t":"18묶음","mis":"M2-1-u6-X05"}],"asset":{"type":"mul_groups","item":"⚽","look":"loose","total":18,"cols":7}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L03_basic#6','math',2,1,'u6','L03','g2_1_math_u6_L03_basic','lesson_basic','M2-1-u6-C2',2,'mc','auto','그림을 보세요. 딸기는 모두 몇 개인가요?',ARRAY['M2-1-u6-X06','M2-1-u6-X05']::text[],true,'{"seq":6,"concept":"M2-1-u6-C2","difficulty":2,"kind":"mc","stem":"그림을 보세요. 딸기는 모두 몇 개인가요?","explanation":["6개씩 4묶음이에요.","6씩 뛰어 세면 6, 12, 18, 24.","딸기는 모두 24개예요."],"variant_rule":{"mul":{"ask":"total"}},"options":[{"t":"24개","correct":true},{"t":"10개","mis":"M2-1-u6-X06"},{"t":"4개","mis":"M2-1-u6-X05"}],"asset":{"type":"mul_groups","item":"🍓","k":6,"n":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L03_basic#7','math',2,1,'u6','L03','g2_1_math_u6_L03_basic','lesson_basic','M2-1-u6-C2',2,'mc','auto','그림을 알맞게 묶어 센 것은 어느 것인가요?',ARRAY['M2-1-u6-X06','M2-1-u6-X03']::text[],true,'{"seq":7,"concept":"M2-1-u6-C2","difficulty":2,"kind":"mc","stem":"그림을 알맞게 묶어 센 것은 어느 것인가요?","options":[{"t":"6씩 3묶음, 모두 18개","correct":true},{"t":"6씩 3묶음, 모두 9개","mis":"M2-1-u6-X06"},{"t":"6씩 4묶음, 모두 24개","mis":"M2-1-u6-X03"}],"explanation":["한 묶음에 6개씩, 묶음은 3개예요.","6, 12, 18로 뛰어 세면 18개예요.","6과 3을 더한 9는 모두 몇 개가 아니에요."],"asset":{"type":"mul_groups","item":"🥚","k":6,"n":3},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림을 알맞게 묶어 센 것은 어느 것인가요?","options":[{"t":"4씩 5묶음, 모두 20개","correct":true},{"t":"4씩 5묶음, 모두 9개","mis":"M2-1-u6-X06"},{"t":"4씩 4묶음, 모두 16개","mis":"M2-1-u6-X03"}],"explanation":["한 묶음에 4개씩, 묶음은 5개예요.","4, 8, 12, 16, 20으로 뛰어 세면 20개예요.","4와 5를 더한 9는 모두 몇 개가 아니에요."],"asset":{"type":"mul_groups","item":"🍪","k":4,"n":5}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L03_basic#8','math',2,1,'u6','L03','g2_1_math_u6_L03_basic','lesson_basic','M2-1-u6-C2',2,'match','auto','「몇씩 몇 묶음」과 모두 몇 개인지를 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M2-1-u6-C2","difficulty":2,"kind":"match","stem":"「몇씩 몇 묶음」과 모두 몇 개인지를 이으세요.","pairs":[{"l":"4씩 5묶음","r":"20개"},{"l":"3씩 6묶음","r":"18개"},{"l":"6씩 2묶음","r":"12개"}],"mis":"M2-1-u6-X06","explanation":["4씩 5묶음 → 4, 8, 12, 16, 20","3씩 6묶음 → 3, 6, 9, 12, 15, 18","6씩 2묶음 → 6, 12"],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 「몇씩 몇 묶음」과 모두 몇 개인지를 이으세요.","pairs":[{"l":"7씩 2묶음","r":"14개"},{"l":"2씩 8묶음","r":"16개"},{"l":"5씩 5묶음","r":"25개"}],"explanation":["7씩 2묶음 → 7, 14","2씩 8묶음 → 2, 4, 6, 8, 10, 12, 14, 16","5씩 5묶음 → 5, 10, 15, 20, 25"]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L03_basic#9','math',2,1,'u6','L03','g2_1_math_u6_L03_basic','lesson_basic','M2-1-u6-C2',2,'sa','auto','그림을 보세요. 달걀은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M2-1-u6-C2","difficulty":2,"kind":"sa","stem":"그림을 보세요. 달걀은 모두 몇 개인가요? 숫자로 쓰세요.","explanation":["한 줄에 5개씩 3줄이에요.","5씩 뛰어 세면 5, 10, 15.","달걀은 모두 15개예요."],"variant_rule":{"mul":{"ask":"total","look":"rows"}},"answer":["15","15개"],"asset":{"type":"mul_groups","item":"🥚","k":5,"n":3,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L03_basic#10','math',2,1,'u6','L03','g2_1_math_u6_L03_basic','lesson_basic','M2-1-u6-C2',3,'error','auto','사과 12개를 친구들이 같은 수씩 묶어 보았어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u6-X03','M2-1-u6-X15']::text[],true,'{"seq":10,"concept":"M2-1-u6-C2","difficulty":3,"kind":"error","stem":"사과 12개를 친구들이 같은 수씩 묶어 보았어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은솔 — 「5씩 묶으면 3묶음이야.」","correct":true,"mis_target":"M2-1-u6-X03"},{"t":"도윤 — 「3씩 묶으면 4묶음이야.」","mis":"M2-1-u6-X15"},{"t":"예린 — 「4씩 묶으면 3묶음이야.」","mis":"M2-1-u6-X15"}],"explanation":["5씩 묶으면 5, 10으로 2묶음이 되고 2개가 남아요.","은솔이의 말이 틀렸어요.","3씩 4묶음, 4씩 3묶음은 모두 12개로 남김없이 묶여요."],"asset":{"type":"mul_groups","item":"🍎","look":"loose","total":12,"cols":6},"variant_rule":{"alt":[{"stem":"딸기 16개를 친구들이 같은 수씩 묶어 보았어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태민 — 「3씩 묶으면 5묶음이야.」","correct":true,"mis_target":"M2-1-u6-X03"},{"t":"아린 — 「4씩 묶으면 4묶음이야.」","mis":"M2-1-u6-X15"},{"t":"지안 — 「8씩 묶으면 2묶음이야.」","mis":"M2-1-u6-X15"}],"explanation":["3씩 묶으면 5묶음이 되고 1개가 남아요.","태민이의 말이 틀렸어요.","4씩 4묶음, 8씩 2묶음은 모두 16개로 남김없이 묶여요."],"asset":{"type":"mul_groups","item":"🍓","look":"loose","total":16,"cols":6}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L03_challenge#1','math',2,1,'u6','L03','g2_1_math_u6_L03_challenge','lesson_challenge','M2-1-u6-C2',2,'mc','auto','그림을 「몇씩 몇 묶음」으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u6-X04','M2-1-u6-X03']::text[],true,'{"seq":1,"concept":"M2-1-u6-C2","difficulty":2,"kind":"mc","stem":"그림을 「몇씩 몇 묶음」으로 바르게 나타낸 것은 어느 것인가요?","explanation":["한 묶음에 별이 4개씩 있어요.","묶음은 모두 6개예요.","그래서 4씩 6묶음이에요 — 「몇씩」은 한 묶음 안의 수, 「몇 묶음」은 묶음의 수예요."],"variant_rule":{"mul":{"ask":"name"}},"options":[{"t":"4씩 6묶음","correct":true},{"t":"6씩 4묶음","mis":"M2-1-u6-X04"},{"t":"4씩 7묶음","mis":"M2-1-u6-X03"}],"asset":{"type":"mul_groups","item":"⭐","k":4,"n":6}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L03_challenge#2','math',2,1,'u6','L03','g2_1_math_u6_L03_challenge','lesson_challenge','M2-1-u6-C2',2,'ox','auto','공 20개를 5씩 묶을 때보다 4씩 묶을 때 공이 더 많아져요.',ARRAY['M2-1-u6-X08']::text[],false,'{"seq":2,"concept":"M2-1-u6-C2","difficulty":2,"kind":"ox","stem":"공 20개를 5씩 묶을 때보다 4씩 묶을 때 공이 더 많아져요.","answer":"X","reason_options":[{"t":"묶는 방법만 다르고 공의 수는 그대로 20개니까","correct":true},{"t":"묶음이 많아지면 공도 많아지니까","mis":"M2-1-u6-X08"}],"mis":"M2-1-u6-X08","explanation":["5씩 묶으면 4묶음, 4씩 묶으면 5묶음이에요.","묶음의 수는 달라도 공은 모두 20개예요.","묶는 방법을 바꾸어도 전체 수는 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L03_challenge#3','math',2,1,'u6','L03','g2_1_math_u6_L03_challenge','lesson_challenge','M2-1-u6-C2',3,'mc','auto','그림의 공을 7개씩 묶으면 몇 묶음인가요?',ARRAY['M2-1-u6-X04','M2-1-u6-X05','M2-1-u6-X03']::text[],true,'{"seq":3,"concept":"M2-1-u6-C2","difficulty":3,"kind":"mc","stem":"그림의 공을 7개씩 묶으면 몇 묶음인가요?","explanation":["공은 모두 28개예요.","7개씩 묶으면 7, 14, 21, 28 — 4번 묶여요.","그래서 7씩 4묶음이에요."],"variant_rule":{"mul":{"ask":"groups"}},"options":[{"t":"4묶음","correct":true},{"t":"7묶음","mis":"M2-1-u6-X04"},{"t":"28묶음","mis":"M2-1-u6-X05"},{"t":"5묶음","mis":"M2-1-u6-X03"}],"asset":{"type":"mul_groups","item":"⚽","look":"loose","total":28,"cols":8}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L03_challenge#4','math',2,1,'u6','L03','g2_1_math_u6_L03_challenge','lesson_challenge','M2-1-u6-C2',3,'mc','auto','구슬 24개를 같은 수씩 묶으려고 해요. 남김없이 묶을 수 없는 방법은 어느 것인가요?',ARRAY['M2-1-u6-X15']::text[],false,'{"seq":4,"concept":"M2-1-u6-C2","difficulty":3,"kind":"mc","stem":"구슬 24개를 같은 수씩 묶으려고 해요. 남김없이 묶을 수 없는 방법은 어느 것인가요?","options":[{"t":"5개씩 묶기","correct":true},{"t":"4개씩 묶기","mis":"M2-1-u6-X15"},{"t":"6개씩 묶기","mis":"M2-1-u6-X15"}],"explanation":["5씩 뛰어 세면 5, 10, 15, 20, 25로 24에 딱 맞지 않아요.","4씩 6묶음, 6씩 4묶음은 24개로 남김없이 묶여요.","「없는」 방법을 묻는지 다시 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L03_challenge#5','math',2,1,'u6','L03','g2_1_math_u6_L03_challenge','lesson_challenge','M2-1-u6-C2',3,'mc','auto','딸기를 6개씩 4묶음으로 묶었어요. 같은 딸기를 4개씩 묶으면 몇 묶음이 될까요?',ARRAY['M2-1-u6-X08','M2-1-u6-X05']::text[],false,'{"seq":5,"concept":"M2-1-u6-C2","difficulty":3,"kind":"mc","stem":"딸기를 6개씩 4묶음으로 묶었어요. 같은 딸기를 4개씩 묶으면 몇 묶음이 될까요?","options":[{"t":"6묶음","correct":true},{"t":"4묶음","mis":"M2-1-u6-X08"},{"t":"24묶음","mis":"M2-1-u6-X05"}],"explanation":["6씩 4묶음은 6, 12, 18, 24로 24개예요.","24개를 4씩 묶으면 4, 8, 12, 16, 20, 24로 6묶음이에요.","묶는 수가 바뀌면 묶음의 수도 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L03_challenge#6','math',2,1,'u6','L03','g2_1_math_u6_L03_challenge','lesson_challenge','M2-1-u6-C2',3,'mc','auto','그림을 보세요. 공은 모두 몇 개인가요?',ARRAY['M2-1-u6-X06','M2-1-u6-X05','M2-1-u6-X02']::text[],true,'{"seq":6,"concept":"M2-1-u6-C2","difficulty":3,"kind":"mc","stem":"그림을 보세요. 공은 모두 몇 개인가요?","explanation":["8개씩 4묶음이에요.","8씩 뛰어 세면 8, 16, 24, 32.","공은 모두 32개예요."],"variant_rule":{"mul":{"ask":"total"}},"options":[{"t":"32개","correct":true},{"t":"12개","mis":"M2-1-u6-X06"},{"t":"4개","mis":"M2-1-u6-X05"},{"t":"40개","mis":"M2-1-u6-X02"}],"asset":{"type":"mul_groups","item":"⚽","k":8,"n":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L03_challenge#7','math',2,1,'u6','L03','g2_1_math_u6_L03_challenge','lesson_challenge','M2-1-u6-C2',3,'mc','auto','사탕을 ㉮는 5씩 3묶음, ㉯는 4씩 4묶음으로 묶었어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M2-1-u6-X15','M2-1-u6-X06']::text[],false,'{"seq":7,"concept":"M2-1-u6-C2","difficulty":3,"kind":"mc","stem":"사탕을 ㉮는 5씩 3묶음, ㉯는 4씩 4묶음으로 묶었어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"㉯가 1개 더 많아요","correct":true},{"t":"㉮가 1개 더 많아요","mis":"M2-1-u6-X15"},{"t":"㉮와 ㉯의 사탕 수가 같아요","mis":"M2-1-u6-X06"}],"explanation":["㉮는 5, 10, 15로 15개, ㉯는 4, 8, 12, 16으로 16개예요.","16은 15보다 1 커요.","5 + 3과 4 + 4처럼 더해서 견주면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L03_challenge#8','math',2,1,'u6','L03','g2_1_math_u6_L03_challenge','lesson_challenge','M2-1-u6-C2',4,'essay','teacher','그림의 사탕을 두 가지 방법으로 남김없이 묶어 「몇씩 몇 묶음」으로 쓰고, 각각 뛰어 세어 모두 몇 개인지 확인해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-1-u6-C2","difficulty":4,"kind":"essay","stem":"그림의 사탕을 두 가지 방법으로 남김없이 묶어 「몇씩 몇 묶음」으로 쓰고, 각각 뛰어 세어 모두 몇 개인지 확인해 보세요.","answer_guide":{"answer":"예: 3씩 6묶음 — 3, 6, 9, 12, 15, 18. 6씩 3묶음 — 6, 12, 18. 어떻게 묶어도 모두 18개이다.","scoring_points":["한 가지 방법으로 남김없이 묶어 썼는가","다른 방법으로도 남김없이 묶어 썼는가","두 방법 모두 뛰어 세어 18개임을 확인했는가"]},"explanation":["18개는 2씩 9묶음, 3씩 6묶음, 6씩 3묶음, 9씩 2묶음으로 묶을 수 있어요.","묶은 수만큼 뛰어 세어 확인해요.","어떻게 묶어도 모두 18개예요."],"asset":{"type":"mul_groups","item":"🍬","look":"loose","total":18,"cols":7}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L03_challenge#9','math',2,1,'u6','L03','g2_1_math_u6_L03_challenge','lesson_challenge','M2-1-u6-C2',4,'essay','teacher','지호는 공 15개를 4개씩 묶었더니 3묶음과 3개가 남았다고 했어요. 지호에게 남김없이 묶는 방법을 두 가지 알려 주고, 각각 「몇씩 몇 묶음」으로 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-1-u6-C2","difficulty":4,"kind":"essay","stem":"지호는 공 15개를 4개씩 묶었더니 3묶음과 3개가 남았다고 했어요. 지호에게 남김없이 묶는 방법을 두 가지 알려 주고, 각각 「몇씩 몇 묶음」으로 써 보세요.","answer_guide":{"answer":"예: 4씩 묶으면 남는 것이 생긴다. 3씩 5묶음(3, 6, 9, 12, 15)이나 5씩 3묶음(5, 10, 15)으로 묶으면 남김없이 묶인다.","scoring_points":["4씩 묶으면 남는 것이 생긴다고 썼는가","3씩 5묶음을 썼는가","5씩 3묶음을 썼는가"]},"explanation":["15를 4씩 뛰어 세면 4, 8, 12, 16으로 15에 딱 맞지 않아요.","3씩 뛰면 3, 6, 9, 12, 15, 5씩 뛰면 5, 10, 15예요.","남김없이 묶어야 「몇씩 몇 묶음」으로 말할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L03_challenge#10','math',2,1,'u6','L03','g2_1_math_u6_L03_challenge','lesson_challenge','M2-1-u6-C2',4,'mc','auto','어떤 물건을 7개씩 묶었더니 4묶음이 되었어요. 이 물건을 4개씩 묶으면 몇 묶음이 될까요?',ARRAY['M2-1-u6-X08','M2-1-u6-X05','M2-1-u6-X06']::text[],false,'{"seq":10,"concept":"M2-1-u6-C2","difficulty":4,"kind":"mc","stem":"어떤 물건을 7개씩 묶었더니 4묶음이 되었어요. 이 물건을 4개씩 묶으면 몇 묶음이 될까요?","options":[{"t":"7묶음","correct":true},{"t":"4묶음","mis":"M2-1-u6-X08"},{"t":"28묶음","mis":"M2-1-u6-X05"},{"t":"11묶음","mis":"M2-1-u6-X06"}],"explanation":["7씩 4묶음은 7, 14, 21, 28로 28개예요.","28개를 4씩 묶으면 4, 8, 12, 16, 20, 24, 28로 7묶음이에요.","7씩 4묶음과 4씩 7묶음은 같은 28개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L04_basic#1','math',2,1,'u6','L04','g2_1_math_u6_L04_basic','lesson_basic','M2-1-u6-C3',1,'mc','auto','그림을 「몇의 몇 배」로 나타내면 어느 것인가요?',ARRAY['M2-1-u6-X07','M2-1-u6-X03']::text[],true,'{"seq":1,"concept":"M2-1-u6-C3","difficulty":1,"kind":"mc","stem":"그림을 「몇의 몇 배」로 나타내면 어느 것인가요?","explanation":["2씩 4묶음이에요.","2씩 4묶음은 2의 4배예요.","「몇의」에는 한 묶음의 수, 「몇 배」에는 묶음의 수를 써요."],"variant_rule":{"mul":{"ask":"times"}},"options":[{"t":"2의 4배","correct":true},{"t":"4의 2배","mis":"M2-1-u6-X07"},{"t":"2의 5배","mis":"M2-1-u6-X03"}],"asset":{"type":"mul_groups","item":"⭐","k":2,"n":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L04_basic#2','math',2,1,'u6','L04','g2_1_math_u6_L04_basic','lesson_basic','M2-1-u6-C3',1,'sa','auto','3의 4배는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-1-u6-C3","difficulty":1,"kind":"sa","stem":"3의 4배는 얼마인가요? 숫자로 쓰세요.","explanation":["3의 4배는 3씩 4묶음이에요.","3씩 뛰어 세면 3, 6, 9, 12.","그래서 3의 4배는 12예요."],"variant_rule":{"mul":{"ask":"tval"}},"answer":["12"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L04_basic#3','math',2,1,'u6','L04','g2_1_math_u6_L04_basic','lesson_basic','M2-1-u6-C3',1,'mc','auto','2씩 5묶음을 「몇의 몇 배」로 나타내면 어느 것인가요?',ARRAY['M2-1-u6-X07','M2-1-u6-X03']::text[],true,'{"seq":3,"concept":"M2-1-u6-C3","difficulty":1,"kind":"mc","stem":"2씩 5묶음을 「몇의 몇 배」로 나타내면 어느 것인가요?","options":[{"t":"2의 5배","correct":true},{"t":"5의 2배","mis":"M2-1-u6-X07"},{"t":"2의 2배","mis":"M2-1-u6-X03"}],"explanation":["한 묶음에 2개씩, 묶음이 5개예요.","「몇의」에는 한 묶음의 수 2, 「몇 배」에는 묶음의 수 5를 써요.","그래서 2의 5배예요."],"variant_rule":{"alt":[{"stem":"4씩 3묶음을 「몇의 몇 배」로 나타내면 어느 것인가요?","options":[{"t":"4의 3배","correct":true},{"t":"3의 4배","mis":"M2-1-u6-X07"},{"t":"4의 4배","mis":"M2-1-u6-X03"}],"explanation":["한 묶음에 4개씩, 묶음이 3개예요.","「몇의」에는 4, 「몇 배」에는 3을 써요.","그래서 4의 3배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L04_basic#4','math',2,1,'u6','L04','g2_1_math_u6_L04_basic','lesson_basic','M2-1-u6-C3',1,'ox','auto','3씩 1묶음은 3의 1배예요.',ARRAY['M2-1-u6-X03']::text[],true,'{"seq":4,"concept":"M2-1-u6-C3","difficulty":1,"kind":"ox","stem":"3씩 1묶음은 3의 1배예요.","answer":"O","reason_options":[{"t":"한 묶음은 그 수의 1배니까","correct":true},{"t":"한 묶음은 아직 묶음이 아니니까 0배니까","mis":"M2-1-u6-X03"}],"mis":"M2-1-u6-X03","explanation":["한 묶음이 있으면 1배예요.","3씩 1묶음은 3의 1배이고, 3이에요.","3씩 2묶음은 3의 2배, 3씩 3묶음은 3의 3배예요."],"variant_rule":{"alt":[{"stem":"5의 1배는 5예요.","answer":"O","reason_options":[{"t":"5씩 1묶음은 5개니까","correct":true},{"t":"1배는 1개라는 뜻이니까","mis":"M2-1-u6-X05"}],"explanation":["5의 1배는 5씩 1묶음이에요.","5씩 1묶음은 5개예요.","그래서 5의 1배는 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L04_basic#5','math',2,1,'u6','L04','g2_1_math_u6_L04_basic','lesson_basic','M2-1-u6-C3',2,'mc','auto','5의 3배는 얼마인가요?',ARRAY['M2-1-u6-X06','M2-1-u6-X02']::text[],true,'{"seq":5,"concept":"M2-1-u6-C3","difficulty":2,"kind":"mc","stem":"5의 3배는 얼마인가요?","explanation":["5의 3배는 5씩 3묶음이에요.","5씩 뛰어 세면 5, 10, 15.","그래서 5의 3배는 15예요."],"variant_rule":{"mul":{"ask":"tval"}},"options":[{"t":"15","correct":true},{"t":"8","mis":"M2-1-u6-X06"},{"t":"20","mis":"M2-1-u6-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L04_basic#6','math',2,1,'u6','L04','g2_1_math_u6_L04_basic','lesson_basic','M2-1-u6-C3',2,'match','auto','「몇씩 몇 묶음」과 「몇의 몇 배」를 이으세요.','{}'::text[],true,'{"seq":6,"concept":"M2-1-u6-C3","difficulty":2,"kind":"match","stem":"「몇씩 몇 묶음」과 「몇의 몇 배」를 이으세요.","pairs":[{"l":"3씩 4묶음","r":"3의 4배"},{"l":"4씩 3묶음","r":"4의 3배"},{"l":"2씩 6묶음","r":"2의 6배"}],"mis":"M2-1-u6-X07","explanation":["「몇씩」의 수가 「몇의」로 가요.","「몇 묶음」의 수가 「몇 배」로 가요.","3씩 4묶음과 4씩 3묶음은 서로 다른 말이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 「몇씩 몇 묶음」과 「몇의 몇 배」를 이으세요.","pairs":[{"l":"5씩 2묶음","r":"5의 2배"},{"l":"2씩 5묶음","r":"2의 5배"},{"l":"6씩 3묶음","r":"6의 3배"}],"explanation":["「몇씩」의 수가 「몇의」로 가요.","「몇 묶음」의 수가 「몇 배」로 가요.","5씩 2묶음과 2씩 5묶음은 서로 다른 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L04_basic#7','math',2,1,'u6','L04','g2_1_math_u6_L04_basic','lesson_basic','M2-1-u6-C3',2,'mc','auto','그림을 「몇의 몇 배」로 나타내면 어느 것인가요?',ARRAY['M2-1-u6-X07','M2-1-u6-X03']::text[],true,'{"seq":7,"concept":"M2-1-u6-C3","difficulty":2,"kind":"mc","stem":"그림을 「몇의 몇 배」로 나타내면 어느 것인가요?","explanation":["6씩 4묶음이에요.","6씩 4묶음은 6의 4배예요.","「몇의」에는 한 묶음의 수, 「몇 배」에는 묶음의 수를 써요."],"variant_rule":{"mul":{"ask":"times"}},"options":[{"t":"6의 4배","correct":true},{"t":"4의 6배","mis":"M2-1-u6-X07"},{"t":"6의 5배","mis":"M2-1-u6-X03"}],"asset":{"type":"mul_groups","item":"🍪","k":6,"n":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L04_basic#8','math',2,1,'u6','L04','g2_1_math_u6_L04_basic','lesson_basic','M2-1-u6-C3',2,'mc','auto','공깃돌 12개를 4개씩 묶었어요. 「몇의 몇 배」로 나타내면 어느 것인가요?',ARRAY['M2-1-u6-X07','M2-1-u6-X05','M2-1-u6-X03']::text[],true,'{"seq":8,"concept":"M2-1-u6-C3","difficulty":2,"kind":"mc","stem":"공깃돌 12개를 4개씩 묶었어요. 「몇의 몇 배」로 나타내면 어느 것인가요?","options":[{"t":"4의 3배","correct":true},{"t":"3의 4배","mis":"M2-1-u6-X07"},{"t":"12의 1배","mis":"M2-1-u6-X05"},{"t":"4의 4배","mis":"M2-1-u6-X03"}],"explanation":["12개를 4씩 묶으면 4, 8, 12로 3묶음이에요.","4씩 3묶음은 4의 3배예요.","「몇의」에는 묶는 수 4를 써요."],"asset":{"type":"mul_groups","item":"⭐","look":"loose","total":12,"cols":6},"variant_rule":{"alt":[{"stem":"사탕 15개를 5개씩 묶었어요. 「몇의 몇 배」로 나타내면 어느 것인가요?","options":[{"t":"5의 3배","correct":true},{"t":"3의 5배","mis":"M2-1-u6-X07"},{"t":"15의 1배","mis":"M2-1-u6-X05"},{"t":"5의 5배","mis":"M2-1-u6-X03"}],"explanation":["15개를 5씩 묶으면 5, 10, 15로 3묶음이에요.","5씩 3묶음은 5의 3배예요.","「몇의」에는 묶는 수 5를 써요."],"asset":{"type":"mul_groups","item":"🍬","look":"loose","total":15,"cols":6}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L04_basic#9','math',2,1,'u6','L04','g2_1_math_u6_L04_basic','lesson_basic','M2-1-u6-C3',2,'ox','auto','7의 2배는 14입니다.',ARRAY['M2-1-u6-X06']::text[],true,'{"seq":9,"concept":"M2-1-u6-C3","difficulty":2,"kind":"ox","stem":"7의 2배는 14입니다.","explanation":["7의 2배는 7씩 2묶음이에요.","7씩 뛰어 세면 7, 14.","그래서 7의 2배는 14예요."],"variant_rule":{"mul":{"ask":"tval"}},"answer":"O","reason_options":[{"t":"7씩 2번 뛰어 세면 14가 되니까","correct":true},{"t":"7과 2를 더해야 하니까","mis":"M2-1-u6-X06"}],"mis":"M2-1-u6-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L04_basic#10','math',2,1,'u6','L04','g2_1_math_u6_L04_basic','lesson_basic','M2-1-u6-C3',3,'mc','auto','병아리 8마리를 2마리씩 묶으면 2의 4배예요. 같은 병아리를 4마리씩 묶으면 4의 몇 배인가요?',ARRAY['M2-1-u6-X08','M2-1-u6-X05']::text[],true,'{"seq":10,"concept":"M2-1-u6-C3","difficulty":3,"kind":"mc","stem":"병아리 8마리를 2마리씩 묶으면 2의 4배예요. 같은 병아리를 4마리씩 묶으면 4의 몇 배인가요?","explanation":["4마리씩 묶으면 4, 8 — 2묶음이에요.","그래서 4의 2배예요.","같은 8마리라도 묶는 수가 달라지면 몇 배인지도 달라져요."],"variant_rule":{"mul":{"ask":"regroup"}},"options":[{"t":"2배","correct":true},{"t":"4배","mis":"M2-1-u6-X08"},{"t":"8배","mis":"M2-1-u6-X05"}],"asset":{"type":"mul_groups","item":"🐥","look":"loose","total":8,"cols":6}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
