INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L04_challenge#2','math',2,1,'u6','L04','g2_1_math_u6_L04_challenge','lesson_challenge','M2-1-u6-C3',2,'ox','auto','사탕 12개를 3개씩 묶으면 3의 4배, 4개씩 묶으면 4의 3배예요.',ARRAY['M2-1-u6-X08']::text[],false,'{"seq":2,"concept":"M2-1-u6-C3","difficulty":2,"kind":"ox","stem":"사탕 12개를 3개씩 묶으면 3의 4배, 4개씩 묶으면 4의 3배예요.","answer":"O","reason_options":[{"t":"3씩 묶으면 4묶음, 4씩 묶으면 3묶음이니까","correct":true},{"t":"묶는 수가 달라도 몇 배는 늘 같으니까","mis":"M2-1-u6-X08"}],"mis":"M2-1-u6-X08","explanation":["12개를 3씩 묶으면 3, 6, 9, 12로 4묶음이에요.","4씩 묶으면 4, 8, 12로 3묶음이에요.","묶는 수가 달라지면 몇 배도 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L04_challenge#3','math',2,1,'u6','L04','g2_1_math_u6_L04_challenge','lesson_challenge','M2-1-u6-C3',3,'mc','auto','딸기 18개를 3개씩 묶으면 3의 6배예요. 같은 딸기를 6개씩 묶으면 6의 몇 배인가요?',ARRAY['M2-1-u6-X08','M2-1-u6-X05']::text[],true,'{"seq":3,"concept":"M2-1-u6-C3","difficulty":3,"kind":"mc","stem":"딸기 18개를 3개씩 묶으면 3의 6배예요. 같은 딸기를 6개씩 묶으면 6의 몇 배인가요?","explanation":["6개씩 묶으면 6, 12, 18 — 3묶음이에요.","그래서 6의 3배예요.","같은 18개라도 묶는 수가 달라지면 몇 배인지도 달라져요."],"variant_rule":{"mul":{"ask":"regroup"}},"options":[{"t":"3배","correct":true},{"t":"6배","mis":"M2-1-u6-X08"},{"t":"18배","mis":"M2-1-u6-X05"}],"asset":{"type":"mul_groups","item":"🍓","look":"loose","total":18,"cols":7}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L04_challenge#4','math',2,1,'u6','L04','g2_1_math_u6_L04_challenge','lesson_challenge','M2-1-u6-C3',3,'mc','auto','8의 2배와 2의 8배를 바르게 말한 것은 어느 것인가요?',ARRAY['M2-1-u6-X13','M2-1-u6-X06']::text[],false,'{"seq":4,"concept":"M2-1-u6-C3","difficulty":3,"kind":"mc","stem":"8의 2배와 2의 8배를 바르게 말한 것은 어느 것인가요?","options":[{"t":"두 수는 16으로 같아요","correct":true},{"t":"8의 2배가 더 커요","mis":"M2-1-u6-X13"},{"t":"두 수는 10으로 같아요","mis":"M2-1-u6-X06"}],"explanation":["8의 2배는 8, 16으로 16이에요.","2의 8배는 2, 4, 6, 8, 10, 12, 14, 16으로 16이에요.","같은 16을 8씩 묶느냐 2씩 묶느냐의 차이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L04_challenge#5','math',2,1,'u6','L04','g2_1_math_u6_L04_challenge','lesson_challenge','M2-1-u6-C3',3,'mc','auto','같은 사탕 24개를 3개씩 묶을 때와 6개씩 묶을 때를 견주었어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M2-1-u6-X08']::text[],false,'{"seq":5,"concept":"M2-1-u6-C3","difficulty":3,"kind":"mc","stem":"같은 사탕 24개를 3개씩 묶을 때와 6개씩 묶을 때를 견주었어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"6개씩 묶을 때 몇 배가 더 작아요","correct":true},{"t":"6개씩 묶을 때 몇 배가 더 커요","mis":"M2-1-u6-X08"},{"t":"몇 배는 서로 같아요","mis":"M2-1-u6-X08"}],"explanation":["3씩 묶으면 3의 8배, 6씩 묶으면 6의 4배예요.","묶는 수가 커지면 묶음의 수는 줄어요.","그래서 6개씩 묶을 때 몇 배가 더 작아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L04_challenge#6','math',2,1,'u6','L04','g2_1_math_u6_L04_challenge','lesson_challenge','M2-1-u6-C3',3,'sa','auto','9의 3배는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M2-1-u6-C3","difficulty":3,"kind":"sa","stem":"9의 3배는 얼마인가요? 숫자로 쓰세요.","explanation":["9의 3배는 9씩 3묶음이에요.","9씩 뛰어 세면 9, 18, 27.","그래서 9의 3배는 27이에요."],"variant_rule":{"mul":{"ask":"tval"}},"answer":["27"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L04_challenge#7','math',2,1,'u6','L04','g2_1_math_u6_L04_challenge','lesson_challenge','M2-1-u6-C3',3,'error','auto','그림을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u6-X07','M2-1-u6-X15']::text[],false,'{"seq":7,"concept":"M2-1-u6-C3","difficulty":3,"kind":"error","stem":"그림을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「3의 5배야.」","correct":true,"mis_target":"M2-1-u6-X07"},{"t":"서윤 — 「5씩 3묶음이야.」","mis":"M2-1-u6-X15"},{"t":"준우 — 「5의 3배야.」","mis":"M2-1-u6-X15"}],"explanation":["한 묶음에 5개씩, 묶음이 3개예요.","5씩 3묶음은 5의 3배예요.","하람이는 「몇의」와 「몇 배」를 뒤바꾸었어요."],"asset":{"type":"mul_groups","item":"🦋","k":5,"n":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L04_challenge#8','math',2,1,'u6','L04','g2_1_math_u6_L04_challenge','lesson_challenge','M2-1-u6-C3',4,'essay','teacher','그림의 쿠키 12개를 4개씩 묶어 「몇의 몇 배」로, 3개씩 묶어 「몇의 몇 배」로 나타내고, 두 결과를 견주어 알게 된 것을 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-1-u6-C3","difficulty":4,"kind":"essay","stem":"그림의 쿠키 12개를 4개씩 묶어 「몇의 몇 배」로, 3개씩 묶어 「몇의 몇 배」로 나타내고, 두 결과를 견주어 알게 된 것을 써 보세요.","answer_guide":{"answer":"예: 4개씩 묶으면 4의 3배, 3개씩 묶으면 3의 4배이다. 같은 12개라도 묶는 수가 달라지면 몇 배도 달라진다.","scoring_points":["4개씩 묶어 4의 3배라고 썼는가","3개씩 묶어 3의 4배라고 썼는가","묶는 수가 달라지면 몇 배가 달라진다는 것을 썼는가"]},"explanation":["4씩 묶으면 4, 8, 12로 3묶음이에요.","3씩 묶으면 3, 6, 9, 12로 4묶음이에요.","같은 수도 묶는 수에 따라 몇 배가 달라져요."],"asset":{"type":"mul_groups","item":"🍪","look":"loose","total":12,"cols":6}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L04_challenge#9','math',2,1,'u6','L04','g2_1_math_u6_L04_challenge','lesson_challenge','M2-1-u6-C3',4,'essay','teacher','6의 4배가 얼마인지 구하는 방법을 「몇씩 몇 묶음」과 뛰어 세기를 써서 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-1-u6-C3","difficulty":4,"kind":"essay","stem":"6의 4배가 얼마인지 구하는 방법을 「몇씩 몇 묶음」과 뛰어 세기를 써서 설명해 보세요.","answer_guide":{"answer":"예: 6의 4배는 6씩 4묶음이다. 6씩 뛰어 세면 6, 12, 18, 24이므로 6의 4배는 24이다.","scoring_points":["6의 4배를 6씩 4묶음으로 바꾸어 썼는가","6씩 네 번 뛰어 세었는가","6의 4배는 24라고 썼는가"]},"explanation":["6의 4배는 6이 4번 있는 것이에요.","6, 12, 18, 24로 뛰어 세요.","그래서 6의 4배는 24예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L04_challenge#10','math',2,1,'u6','L04','g2_1_math_u6_L04_challenge','lesson_challenge','M2-1-u6-C3',4,'mc','auto','어떤 수의 3배는 15예요. 어떤 수의 5배는 얼마인가요?',ARRAY['M2-1-u6-X08','M2-1-u6-X02','M2-1-u6-X06']::text[],false,'{"seq":10,"concept":"M2-1-u6-C3","difficulty":4,"kind":"mc","stem":"어떤 수의 3배는 15예요. 어떤 수의 5배는 얼마인가요?","options":[{"t":"25","correct":true},{"t":"15","mis":"M2-1-u6-X08"},{"t":"20","mis":"M2-1-u6-X02"},{"t":"8","mis":"M2-1-u6-X06"}],"explanation":["어떤 수를 3번 뛰어 세어 15가 되면 어떤 수는 5예요 — 5, 10, 15.","5의 5배는 5, 10, 15, 20, 25로 25예요.","몇 배가 바뀌면 값도 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L05_basic#1','math',2,1,'u6','L05','g2_1_math_u6_L05_basic','lesson_basic','M2-1-u6-C4',1,'mc','auto','갈색 막대는 빨강 막대를 겹치지 않게 이어 붙인 길이와 같아요. 갈색 막대는 빨강 막대의 몇 배인가요?',ARRAY['M2-1-u6-X10']::text[],true,'{"seq":1,"concept":"M2-1-u6-C4","difficulty":1,"kind":"mc","stem":"갈색 막대는 빨강 막대를 겹치지 않게 이어 붙인 길이와 같아요. 갈색 막대는 빨강 막대의 몇 배인가요?","explanation":["빨강 막대를 겹치지 않게 이어 붙인 자리를 세어요.","빨강 막대가 4번 들어가요.","그래서 갈색 막대는 빨강 막대의 4배예요."],"variant_rule":{"mul":{"ask":"bars"}},"options":[{"t":"4배","correct":true},{"t":"5배","mis":"M2-1-u6-X10"},{"t":"3배","mis":"M2-1-u6-X10"}],"asset":{"type":"times_bars","base":1,"times":4,"a":"빨강","b":"갈색"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L05_basic#2','math',2,1,'u6','L05','g2_1_math_u6_L05_basic','lesson_basic','M2-1-u6-C4',1,'mc','auto','참외 2개가 기준이에요. 토마토 6개는 참외의 몇 배인가요?',ARRAY['M2-1-u6-X09']::text[],true,'{"seq":2,"concept":"M2-1-u6-C4","difficulty":1,"kind":"mc","stem":"참외 2개가 기준이에요. 토마토 6개는 참외의 몇 배인가요?","options":[{"t":"3배","correct":true},{"t":"6배","mis":"M2-1-u6-X09"},{"t":"2배","mis":"M2-1-u6-X09"}],"explanation":["토마토 6개를 참외 수 2개씩 묶어요.","2, 4, 6으로 3묶음이에요.","그래서 토마토는 참외의 3배예요."],"variant_rule":{"alt":[{"stem":"사과 3개가 기준이에요. 귤 12개는 사과의 몇 배인가요?","options":[{"t":"4배","correct":true},{"t":"12배","mis":"M2-1-u6-X09"},{"t":"3배","mis":"M2-1-u6-X09"}],"explanation":["귤 12개를 사과 수 3개씩 묶어요.","3, 6, 9, 12로 4묶음이에요.","그래서 귤은 사과의 4배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L05_basic#3','math',2,1,'u6','L05','g2_1_math_u6_L05_basic','lesson_basic','M2-1-u6-C4',1,'sa','auto','초록 막대는 연두 막대를 겹치지 않게 이어 붙인 길이와 같아요. 초록 막대는 연두 막대의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-1-u6-C4","difficulty":1,"kind":"sa","stem":"초록 막대는 연두 막대를 겹치지 않게 이어 붙인 길이와 같아요. 초록 막대는 연두 막대의 몇 배인가요? 숫자로 쓰세요.","explanation":["연두 막대를 겹치지 않게 이어 붙인 자리를 세어요.","연두 막대가 2번 들어가요.","그래서 초록 막대는 연두 막대의 2배예요."],"variant_rule":{"mul":{"ask":"bars"}},"answer":["2","2배"],"asset":{"type":"times_bars","base":2,"times":2,"a":"연두","b":"초록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L05_basic#4','math',2,1,'u6','L05','g2_1_math_u6_L05_basic','lesson_basic','M2-1-u6-C4',1,'ox','auto','갈색 막대가 빨강 막대의 4배라는 것은 빨강 막대를 겹치지 않게 4번 이어 붙인 길이라는 뜻이에요.',ARRAY['M2-1-u6-X10']::text[],true,'{"seq":4,"concept":"M2-1-u6-C4","difficulty":1,"kind":"ox","stem":"갈색 막대가 빨강 막대의 4배라는 것은 빨강 막대를 겹치지 않게 4번 이어 붙인 길이라는 뜻이에요.","answer":"O","reason_options":[{"t":"기준 막대를 겹치지 않게 이어 붙인 횟수가 몇 배니까","correct":true},{"t":"빨강 막대와 갈색 막대를 더한 길이라는 뜻이니까","mis":"M2-1-u6-X10"}],"mis":"M2-1-u6-X10","explanation":["몇 배는 기준을 몇 번 이어 붙였는지를 말해요.","빨강 막대를 겹치지 않게 4번 이어 붙이면 갈색 막대와 길이가 같아요.","그래서 갈색 막대는 빨강 막대의 4배예요."],"variant_rule":{"alt":[{"stem":"초록 막대가 연두 막대의 2배라는 것은 연두 막대를 겹쳐서 2번 놓은 길이라는 뜻이에요.","answer":"X","reason_options":[{"t":"겹치지 않게 이어 붙여야 하니까","correct":true},{"t":"겹쳐 놓아도 2번 놓았으면 되니까","mis":"M2-1-u6-X10"}],"explanation":["겹쳐서 놓으면 길이가 짧아져요.","연두 막대를 겹치지 않게 2번 이어 붙인 길이가 초록 막대예요.","몇 배를 잴 때는 겹치지 않게 이어 붙여요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L05_basic#5','math',2,1,'u6','L05','g2_1_math_u6_L05_basic','lesson_basic','M2-1-u6-C4',2,'mc','auto','사과는 3개, 딸기는 12개예요. 딸기의 수는 사과의 수의 몇 배인가요?',ARRAY['M2-1-u6-X09']::text[],true,'{"seq":5,"concept":"M2-1-u6-C4","difficulty":2,"kind":"mc","stem":"사과는 3개, 딸기는 12개예요. 딸기의 수는 사과의 수의 몇 배인가요?","explanation":["사과 3개가 기준이에요.","딸기 12개를 3개씩 묶으면 4묶음이에요.","그래서 딸기의 수는 사과의 수의 4배예요."],"variant_rule":{"mul":{"ask":"cmp"}},"options":[{"t":"4배","correct":true},{"t":"12배","mis":"M2-1-u6-X09"},{"t":"9배","mis":"M2-1-u6-X09"}],"asset":{"type":"times_bars","base":3,"times":4,"a":"사과","b":"딸기","item":"🍎","item2":"🍓"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L05_basic#6','math',2,1,'u6','L05','g2_1_math_u6_L05_basic','lesson_basic','M2-1-u6-C4',2,'mc','auto','갈색 막대가 빨강 막대의 4배라는 것은 어떤 뜻인가요?',ARRAY['M2-1-u6-X10']::text[],false,'{"seq":6,"concept":"M2-1-u6-C4","difficulty":2,"kind":"mc","stem":"갈색 막대가 빨강 막대의 4배라는 것은 어떤 뜻인가요?","options":[{"t":"빨강 막대를 겹치지 않게 4번 이어 붙인 길이와 같다는 뜻","correct":true},{"t":"빨강 막대를 겹쳐서 4번 놓은 길이와 같다는 뜻","mis":"M2-1-u6-X10"},{"t":"빨강 막대와 갈색 막대를 더한 길이라는 뜻","mis":"M2-1-u6-X10"}],"explanation":["몇 배는 기준을 몇 번 이어 붙였는지를 말해요.","겹쳐 놓으면 길이가 달라져요.","두 막대를 더한 길이와는 상관없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L05_basic#7','math',2,1,'u6','L05','g2_1_math_u6_L05_basic','lesson_basic','M2-1-u6-C4',2,'mc','auto','파랑 막대는 노랑 막대를 겹치지 않게 이어 붙인 길이와 같아요. 파랑 막대는 노랑 막대의 몇 배인가요?',ARRAY['M2-1-u6-X10','M2-1-u6-X09']::text[],true,'{"seq":7,"concept":"M2-1-u6-C4","difficulty":2,"kind":"mc","stem":"파랑 막대는 노랑 막대를 겹치지 않게 이어 붙인 길이와 같아요. 파랑 막대는 노랑 막대의 몇 배인가요?","explanation":["노랑 막대를 겹치지 않게 이어 붙인 자리를 세어요.","노랑 막대가 3번 들어가요.","그래서 파랑 막대는 노랑 막대의 3배예요."],"variant_rule":{"mul":{"ask":"bars"}},"options":[{"t":"3배","correct":true},{"t":"4배","mis":"M2-1-u6-X10"},{"t":"6배","mis":"M2-1-u6-X09"}],"asset":{"type":"times_bars","base":2,"times":3,"a":"노랑","b":"파랑"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L05_basic#8','math',2,1,'u6','L05','g2_1_math_u6_L05_basic','lesson_basic','M2-1-u6-C4',2,'match','auto','이어 붙인 모양과 몇 배를 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M2-1-u6-C4","difficulty":2,"kind":"match","stem":"이어 붙인 모양과 몇 배를 이으세요.","pairs":[{"l":"노랑 막대 3개를 겹치지 않게 이어 붙인 길이","r":"노랑 막대의 3배"},{"l":"노랑 막대 5개를 겹치지 않게 이어 붙인 길이","r":"노랑 막대의 5배"},{"l":"노랑 막대 2개를 겹치지 않게 이어 붙인 길이","r":"노랑 막대의 2배"}],"mis":"M2-1-u6-X10","explanation":["이어 붙인 막대의 수가 몇 배예요.","3개를 이으면 3배, 5개를 이으면 5배예요.","2개를 이으면 2배예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 이어 붙인 모양과 몇 배를 이으세요.","pairs":[{"l":"흰색 막대 6개를 겹치지 않게 이어 붙인 길이","r":"흰색 막대의 6배"},{"l":"흰색 막대 4개를 겹치지 않게 이어 붙인 길이","r":"흰색 막대의 4배"},{"l":"흰색 막대 1개의 길이","r":"흰색 막대의 1배"}],"explanation":["이어 붙인 막대의 수가 몇 배예요.","6개를 이으면 6배, 4개를 이으면 4배예요.","막대 하나는 1배예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L05_basic#9','math',2,1,'u6','L05','g2_1_math_u6_L05_basic','lesson_basic','M2-1-u6-C4',2,'sa','auto','도넛은 2개, 쿠키는 10개예요. 쿠키의 수는 도넛의 수의 몇 배인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M2-1-u6-C4","difficulty":2,"kind":"sa","stem":"도넛은 2개, 쿠키는 10개예요. 쿠키의 수는 도넛의 수의 몇 배인가요? 숫자로 쓰세요.","explanation":["도넛 2개가 기준이에요.","쿠키 10개를 2개씩 묶으면 5묶음이에요.","그래서 쿠키의 수는 도넛의 수의 5배예요."],"variant_rule":{"mul":{"ask":"cmp"}},"answer":["5","5배"],"asset":{"type":"times_bars","base":2,"times":5,"a":"도넛","b":"쿠키","item":"🍩","item2":"🍪"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L05_basic#10','math',2,1,'u6','L05','g2_1_math_u6_L05_basic','lesson_basic','M2-1-u6-C4',3,'error','auto','연우는 참외를 2개, 민준이는 참외를 6개 땄어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u6-X09','M2-1-u6-X15']::text[],true,'{"seq":10,"concept":"M2-1-u6-C4","difficulty":3,"kind":"error","stem":"연우는 참외를 2개, 민준이는 참외를 6개 땄어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"소율 — 「연우의 참외 수는 민준이의 참외 수의 3배야.」","correct":true,"mis_target":"M2-1-u6-X09"},{"t":"태민 — 「민준이의 참외 수는 연우의 참외 수의 3배야.」","mis":"M2-1-u6-X15"},{"t":"아린 — 「민준이가 연우보다 4개 더 많이 땄어.」","mis":"M2-1-u6-X15"}],"explanation":["기준은 연우의 참외 2개예요.","6을 2씩 묶으면 3묶음이니 민준이의 참외 수가 연우의 3배예요.","소율이는 기준을 거꾸로 잡았어요."],"variant_rule":{"alt":[{"stem":"서아는 딱지를 3장, 하루는 딱지를 12장 가지고 있어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"곰이 — 「하루의 딱지 수는 서아의 딱지 수의 9배야.」","correct":true,"mis_target":"M2-1-u6-X09"},{"t":"펭이 — 「하루의 딱지 수는 서아의 딱지 수의 4배야.」","mis":"M2-1-u6-X15"},{"t":"다예 — 「하루가 서아보다 9장 더 많아.」","mis":"M2-1-u6-X15"}],"explanation":["12를 3씩 묶으면 4묶음이니 4배예요.","9는 두 수의 차이예요.","곰이는 차이를 몇 배라고 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L05_challenge#1','math',2,1,'u6','L05','g2_1_math_u6_L05_challenge','lesson_challenge','M2-1-u6-C4',2,'mc','auto','보라 막대의 길이는 하늘 막대의 길이의 몇 배인가요?',ARRAY['M2-1-u6-X10','M2-1-u6-X09']::text[],true,'{"seq":1,"concept":"M2-1-u6-C4","difficulty":2,"kind":"mc","stem":"보라 막대의 길이는 하늘 막대의 길이의 몇 배인가요?","explanation":["하늘 막대는 2칸, 보라 막대는 8칸이에요.","2칸씩 묶으면 보라 막대는 4묶음이에요.","그래서 보라 막대는 하늘 막대의 4배예요 — 칸 수를 그대로 배로 말하면 안 돼요."],"variant_rule":{"mul":{"ask":"bars","grid":true}},"options":[{"t":"4배","correct":true},{"t":"5배","mis":"M2-1-u6-X10"},{"t":"8배","mis":"M2-1-u6-X09"}],"asset":{"type":"times_bars","base":2,"times":4,"a":"하늘","b":"보라","grid":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L05_challenge#2','math',2,1,'u6','L05','g2_1_math_u6_L05_challenge','lesson_challenge','M2-1-u6-C4',2,'mc','auto','흰색 막대를 겹치지 않게 6번 이어 붙이면 보라 막대와 길이가 같아요. 보라 막대는 흰색 막대의 몇 배인가요?',ARRAY['M2-1-u6-X10']::text[],false,'{"seq":2,"concept":"M2-1-u6-C4","difficulty":2,"kind":"mc","stem":"흰색 막대를 겹치지 않게 6번 이어 붙이면 보라 막대와 길이가 같아요. 보라 막대는 흰색 막대의 몇 배인가요?","options":[{"t":"6배","correct":true},{"t":"7배","mis":"M2-1-u6-X10"},{"t":"5배","mis":"M2-1-u6-X10"}],"explanation":["이어 붙인 횟수가 몇 배예요.","흰색 막대를 6번 이어 붙였어요.","그래서 보라 막대는 흰색 막대의 6배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L05_challenge#3','math',2,1,'u6','L05','g2_1_math_u6_L05_challenge','lesson_challenge','M2-1-u6-C4',3,'mc','auto','초록 막대의 길이는 주황 막대의 길이의 몇 배인가요?',ARRAY['M2-1-u6-X10','M2-1-u6-X09']::text[],true,'{"seq":3,"concept":"M2-1-u6-C4","difficulty":3,"kind":"mc","stem":"초록 막대의 길이는 주황 막대의 길이의 몇 배인가요?","explanation":["주황 막대는 3칸, 초록 막대는 12칸이에요.","3칸씩 묶으면 초록 막대는 4묶음이에요.","그래서 초록 막대는 주황 막대의 4배예요 — 칸 수를 그대로 배로 말하면 안 돼요."],"variant_rule":{"mul":{"ask":"bars","grid":true}},"options":[{"t":"4배","correct":true},{"t":"5배","mis":"M2-1-u6-X10"},{"t":"12배","mis":"M2-1-u6-X09"}],"asset":{"type":"times_bars","base":3,"times":4,"a":"주황","b":"초록","grid":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L05_challenge#4','math',2,1,'u6','L05','g2_1_math_u6_L05_challenge','lesson_challenge','M2-1-u6-C4',3,'mc','auto','쿠키는 4개, 사탕은 12개예요. 사탕의 수는 쿠키의 수의 몇 배인가요?',ARRAY['M2-1-u6-X09']::text[],true,'{"seq":4,"concept":"M2-1-u6-C4","difficulty":3,"kind":"mc","stem":"쿠키는 4개, 사탕은 12개예요. 사탕의 수는 쿠키의 수의 몇 배인가요?","explanation":["쿠키 4개가 기준이에요.","사탕 12개를 4개씩 묶으면 3묶음이에요.","그래서 사탕의 수는 쿠키의 수의 3배예요."],"variant_rule":{"mul":{"ask":"cmp"}},"options":[{"t":"3배","correct":true},{"t":"12배","mis":"M2-1-u6-X09"},{"t":"8배","mis":"M2-1-u6-X09"},{"t":"4배","mis":"M2-1-u6-X09"}],"asset":{"type":"times_bars","base":4,"times":3,"a":"쿠키","b":"사탕","item":"🍪","item2":"🍬"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L05_challenge#5','math',2,1,'u6','L05','g2_1_math_u6_L05_challenge','lesson_challenge','M2-1-u6-C4',3,'mc','auto','빨강 막대는 2칸이에요. 파랑 막대는 빨강 막대의 3배, 초록 막대는 빨강 막대의 5배예요. 초록 막대는 파랑 막대보다 몇 칸 더 길까요?',ARRAY['M2-1-u6-X09','M2-1-u6-X06']::text[],false,'{"seq":5,"concept":"M2-1-u6-C4","difficulty":3,"kind":"mc","stem":"빨강 막대는 2칸이에요. 파랑 막대는 빨강 막대의 3배, 초록 막대는 빨강 막대의 5배예요. 초록 막대는 파랑 막대보다 몇 칸 더 길까요?","options":[{"t":"4칸","correct":true},{"t":"2칸","mis":"M2-1-u6-X09"},{"t":"8칸","mis":"M2-1-u6-X06"}],"explanation":["파랑 막대는 2의 3배로 6칸이에요.","초록 막대는 2의 5배로 10칸이에요.","10 − 6 = 4이니 4칸 더 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L05_challenge#6','math',2,1,'u6','L05','g2_1_math_u6_L05_challenge','lesson_challenge','M2-1-u6-C4',3,'mc','auto','노랑 막대는 1칸, 빨강 막대는 2칸, 갈색 막대는 8칸이에요. 갈색 막대는 빨강 막대의 몇 배인가요?',ARRAY['M2-1-u6-X09']::text[],false,'{"seq":6,"concept":"M2-1-u6-C4","difficulty":3,"kind":"mc","stem":"노랑 막대는 1칸, 빨강 막대는 2칸, 갈색 막대는 8칸이에요. 갈색 막대는 빨강 막대의 몇 배인가요?","options":[{"t":"4배","correct":true},{"t":"8배","mis":"M2-1-u6-X09"},{"t":"6배","mis":"M2-1-u6-X09"}],"explanation":["기준은 빨강 막대 2칸이에요.","8칸을 2칸씩 묶으면 4묶음이에요.","노랑 막대를 기준으로 하면 8배지만, 빨강 막대가 기준이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L05_challenge#7','math',2,1,'u6','L05','g2_1_math_u6_L05_challenge','lesson_challenge','M2-1-u6-C4',3,'error','auto','색 막대로 몇 배를 재는 방법을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u6-X10','M2-1-u6-X15']::text[],false,'{"seq":7,"concept":"M2-1-u6-C4","difficulty":3,"kind":"error","stem":"색 막대로 몇 배를 재는 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지안 — 「기준 막대를 조금씩 겹쳐 가며 놓아 센 횟수가 몇 배야.」","correct":true,"mis_target":"M2-1-u6-X10"},{"t":"은솔 — 「기준 막대를 겹치지 않게 이어 붙여 센 횟수가 몇 배야.」","mis":"M2-1-u6-X15"},{"t":"도윤 — 「막대 끝을 서로 딱 맞추어 이어 붙여야 해.」","mis":"M2-1-u6-X15"}],"explanation":["겹쳐 놓으면 길이가 짧아져 횟수가 달라져요.","지안이의 방법이 잘못되었어요.","겹치지 않게 끝을 맞추어 이어 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L05_challenge#8','math',2,1,'u6','L05','g2_1_math_u6_L05_challenge','lesson_challenge','M2-1-u6-C4',4,'essay','teacher','초록 막대는 연두 막대의 몇 배인지 구하고, 어떻게 구했는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-1-u6-C4","difficulty":4,"kind":"essay","stem":"초록 막대는 연두 막대의 몇 배인지 구하고, 어떻게 구했는지 설명해 보세요.","answer_guide":{"answer":"예: 연두 막대는 2칸, 초록 막대는 6칸이다. 연두 막대를 겹치지 않게 이어 붙이면 3번 들어가므로 초록 막대는 연두 막대의 3배이다.","scoring_points":["두 막대의 칸 수를 바르게 셌는가","연두 막대를 기준으로 이어 붙인 횟수를 셌는가","3배라고 답했는가"]},"explanation":["연두 막대 2칸이 기준이에요.","6칸을 2칸씩 묶으면 3묶음이에요.","칸 수 6을 그대로 6배라고 하면 안 돼요."],"asset":{"type":"times_bars","base":2,"times":3,"a":"연두","b":"초록","grid":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L05_challenge#9','math',2,1,'u6','L05','g2_1_math_u6_L05_challenge','lesson_challenge','M2-1-u6-C4',4,'essay','teacher','참외는 3개, 토마토는 9개예요. 토마토의 수는 참외의 수의 몇 배인지 구하고, 「차이」와 「몇 배」가 어떻게 다른지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-1-u6-C4","difficulty":4,"kind":"essay","stem":"참외는 3개, 토마토는 9개예요. 토마토의 수는 참외의 수의 몇 배인지 구하고, 「차이」와 「몇 배」가 어떻게 다른지 써 보세요.","answer_guide":{"answer":"예: 9를 3씩 묶으면 3묶음이므로 토마토는 참외의 3배이다. 차이는 9 − 3 = 6으로 몇 개 더 많은지이고, 몇 배는 기준이 몇 번 들어가는지이다.","scoring_points":["토마토는 참외의 3배라고 썼는가","차이 6을 바르게 구했는가","몇 배는 기준이 몇 번 들어가는지라고 설명했는가"]},"explanation":["기준은 참외 3개예요.","9를 3씩 묶으면 3묶음이에요.","6은 차이, 3은 몇 배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L05_challenge#10','math',2,1,'u6','L05','g2_1_math_u6_L05_challenge','lesson_challenge','M2-1-u6-C4',4,'mc','auto','민준이는 딱지를 4장 가지고 있어요. 연우는 민준이의 3배, 하린이는 연우의 2배를 가지고 있어요. 하린이는 딱지를 몇 장 가지고 있나요?',ARRAY['M2-1-u6-X09','M2-1-u6-X06']::text[],false,'{"seq":10,"concept":"M2-1-u6-C4","difficulty":4,"kind":"mc","stem":"민준이는 딱지를 4장 가지고 있어요. 연우는 민준이의 3배, 하린이는 연우의 2배를 가지고 있어요. 하린이는 딱지를 몇 장 가지고 있나요?","options":[{"t":"24장","correct":true},{"t":"12장","mis":"M2-1-u6-X09"},{"t":"9장","mis":"M2-1-u6-X06"},{"t":"8장","mis":"M2-1-u6-X09"}],"explanation":["연우는 4의 3배로 12장이에요.","하린이는 연우의 2배이니 12의 2배로 24장이에요.","하린이의 기준은 민준이가 아니라 연우예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L06_basic#1','math',2,1,'u6','L06','g2_1_math_u6_L06_basic','lesson_basic','M2-1-u6-C5',1,'sa','auto','2 × 7은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-1-u6-C5","difficulty":1,"kind":"sa","stem":"2 × 7은 얼마인가요? 숫자로 쓰세요.","explanation":["2 × 7은 2의 7배예요.","2씩 뛰어 세면 2, 4, 6, 8, 10, 12, 14.","그래서 2 × 7 = 14예요."],"variant_rule":{"mul":{"ask":"value"}},"answer":["14"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L06_basic#2','math',2,1,'u6','L06','g2_1_math_u6_L06_basic','lesson_basic','M2-1-u6-C5',1,'mc','auto','3 × 6을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-1-u6-X11']::text[],true,'{"seq":2,"concept":"M2-1-u6-C5","difficulty":1,"kind":"mc","stem":"3 × 6을 바르게 읽은 것은 어느 것인가요?","explanation":["× 는 「곱하기」라고 읽어요.","앞의 수부터 차례로 읽어 「3 곱하기 6」이에요.","3 × 6 = 18은 「3 곱하기 6은 18과 같습니다」라고도 읽어요."],"variant_rule":{"mul":{"ask":"read"}},"options":[{"t":"3 곱하기 6","correct":true},{"t":"3 더하기 6","mis":"M2-1-u6-X11"},{"t":"6 곱하기 3","mis":"M2-1-u6-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L06_basic#3','math',2,1,'u6','L06','g2_1_math_u6_L06_basic','lesson_basic','M2-1-u6-C5',1,'mc','auto','5 + 5 + 5를 곱셈식으로 나타내면 어느 것인가요?',ARRAY['M2-1-u6-X12','M2-1-u6-X11']::text[],true,'{"seq":3,"concept":"M2-1-u6-C5","difficulty":1,"kind":"mc","stem":"5 + 5 + 5를 곱셈식으로 나타내면 어느 것인가요?","explanation":["5가 3번 나와요.","5를 3번 더한 것은 5 × 3이에요.","5 × 3 = 15 — 덧셈식보다 짧게 쓸 수 있어요."],"variant_rule":{"mul":{"ask":"add"}},"options":[{"t":"5 × 3","correct":true},{"t":"5 × 2","mis":"M2-1-u6-X12"},{"t":"5 + 3","mis":"M2-1-u6-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L06_basic#4','math',2,1,'u6','L06','g2_1_math_u6_L06_basic','lesson_basic','M2-1-u6-C5',1,'ox','auto','3의 6배를 곱셈식으로 3 × 6이라고 써요.',ARRAY['M2-1-u6-X11']::text[],true,'{"seq":4,"concept":"M2-1-u6-C5","difficulty":1,"kind":"ox","stem":"3의 6배를 곱셈식으로 3 × 6이라고 써요.","answer":"O","reason_options":[{"t":"몇의 몇 배는 몇 × 몇으로 쓰니까","correct":true},{"t":"× 는 두 수를 더하라는 기호니까","mis":"M2-1-u6-X11"}],"mis":"M2-1-u6-X11","explanation":["3의 6배는 3씩 6묶음이에요.","이것을 곱셈 기호 ×를 써서 3 × 6이라고 써요.","3 × 6은 「3 곱하기 6」이라고 읽어요."],"variant_rule":{"alt":[{"stem":"4의 5배를 곱셈식으로 4 + 5라고 써요.","answer":"X","reason_options":[{"t":"몇의 몇 배는 × 를 써서 4 × 5로 쓰니까","correct":true},{"t":"두 수가 나오면 더하면 되니까","mis":"M2-1-u6-X11"}],"explanation":["4의 5배는 4씩 5묶음이에요.","곱셈식으로는 4 × 5라고 써요.","4 + 5는 4와 5를 더한 9예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L06_basic#5','math',2,1,'u6','L06','g2_1_math_u6_L06_basic','lesson_basic','M2-1-u6-C5',2,'mc','auto','6 × 4는 얼마인가요?',ARRAY['M2-1-u6-X11','M2-1-u6-X02']::text[],true,'{"seq":5,"concept":"M2-1-u6-C5","difficulty":2,"kind":"mc","stem":"6 × 4는 얼마인가요?","explanation":["6 × 4는 6의 4배예요.","6씩 뛰어 세면 6, 12, 18, 24.","그래서 6 × 4 = 24예요."],"variant_rule":{"mul":{"ask":"value"}},"options":[{"t":"24","correct":true},{"t":"10","mis":"M2-1-u6-X11"},{"t":"30","mis":"M2-1-u6-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L06_basic#6','math',2,1,'u6','L06','g2_1_math_u6_L06_basic','lesson_basic','M2-1-u6-C5',2,'match','auto','같은 수의 덧셈식과 곱셈식을 이으세요.','{}'::text[],true,'{"seq":6,"concept":"M2-1-u6-C5","difficulty":2,"kind":"match","stem":"같은 수의 덧셈식과 곱셈식을 이으세요.","pairs":[{"l":"3 + 3 + 3 + 3","r":"3 × 4"},{"l":"4 + 4 + 4","r":"4 × 3"},{"l":"2 + 2 + 2 + 2 + 2","r":"2 × 5"}],"mis":"M2-1-u6-X12","explanation":["더한 수가 몇 번 나오는지 세어요.","3을 4번 더하면 3 × 4, 4를 3번 더하면 4 × 3이에요.","2를 5번 더하면 2 × 5예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 같은 수의 덧셈식과 곱셈식을 이으세요.","pairs":[{"l":"5 + 5 + 5","r":"5 × 3"},{"l":"6 + 6","r":"6 × 2"},{"l":"3 + 3 + 3 + 3 + 3","r":"3 × 5"}],"explanation":["더한 수가 몇 번 나오는지 세어요.","5를 3번 더하면 5 × 3, 6을 2번 더하면 6 × 2예요.","3을 5번 더하면 3 × 5예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L06_basic#7','math',2,1,'u6','L06','g2_1_math_u6_L06_basic','lesson_basic','M2-1-u6-C5',2,'mc','auto','4 + 4 + 4를 곱셈식으로 나타내면 어느 것인가요?',ARRAY['M2-1-u6-X12','M2-1-u6-X11']::text[],true,'{"seq":7,"concept":"M2-1-u6-C5","difficulty":2,"kind":"mc","stem":"4 + 4 + 4를 곱셈식으로 나타내면 어느 것인가요?","explanation":["4가 3번 나와요.","4를 3번 더한 것은 4 × 3이에요.","4 × 3 = 12 — 덧셈식보다 짧게 쓸 수 있어요."],"variant_rule":{"mul":{"ask":"add"}},"options":[{"t":"4 × 3","correct":true},{"t":"4 × 2","mis":"M2-1-u6-X12"},{"t":"4 + 3","mis":"M2-1-u6-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L06_basic#8','math',2,1,'u6','L06','g2_1_math_u6_L06_basic','lesson_basic','M2-1-u6-C5',2,'sa','auto','4와 5의 곱은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M2-1-u6-C5","difficulty":2,"kind":"sa","stem":"4와 5의 곱은 얼마인가요? 숫자로 쓰세요.","explanation":["4 × 5는 4의 5배예요.","4씩 뛰어 세면 4, 8, 12, 16, 20.","그래서 4와 5의 곱은 20이에요."],"variant_rule":{"mul":{"ask":"prod"}},"answer":["20"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L06_basic#9','math',2,1,'u6','L06','g2_1_math_u6_L06_basic','lesson_basic','M2-1-u6-C5',2,'ox','auto','6 × 3 = 12입니다.',ARRAY['M2-1-u6-X02']::text[],true,'{"seq":9,"concept":"M2-1-u6-C5","difficulty":2,"kind":"ox","stem":"6 × 3 = 12입니다.","explanation":["6 × 3은 6의 3배예요.","6씩 뛰어 세면 6, 12, 18.","그래서 6 × 3 = 18이에요."],"variant_rule":{"mul":{"ask":"value"}},"answer":"X","reason_options":[{"t":"6씩 3번 뛰어 세면 12가 아니라 18이 되니까","correct":true},{"t":"6씩 2번만 뛰어 세면 되니까","mis":"M2-1-u6-X02"}],"mis":"M2-1-u6-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L06_basic#10','math',2,1,'u6','L06','g2_1_math_u6_L06_basic','lesson_basic','M2-1-u6-C5',3,'error','auto','4 × 5에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u6-X11','M2-1-u6-X15']::text[],true,'{"seq":10,"concept":"M2-1-u6-C5","difficulty":3,"kind":"error","stem":"4 × 5에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「4 × 5는 4 더하기 5라고 읽어.」","correct":true,"mis_target":"M2-1-u6-X11"},{"t":"지호 — 「4 × 5는 4 곱하기 5라고 읽어.」","mis":"M2-1-u6-X15"},{"t":"서아 — 「4와 5의 곱은 20이야.」","mis":"M2-1-u6-X15"}],"explanation":["× 는 「곱하기」라고 읽어요.","하린이는 × 를 「더하기」로 읽었어요.","4 × 5 = 20이니 4와 5의 곱은 20이에요."],"variant_rule":{"alt":[{"stem":"3 × 7에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태민 — 「3 × 7은 10이야.」","correct":true,"mis_target":"M2-1-u6-X11"},{"t":"아린 — 「3 × 7은 3을 7번 더한 것과 같아.」","mis":"M2-1-u6-X15"},{"t":"지안 — 「3 × 7은 3 곱하기 7이라고 읽어.」","mis":"M2-1-u6-X15"}],"explanation":["3 × 7은 3씩 7번 뛰어 센 21이에요.","태민이는 3과 7을 더했어요.","아린이와 지안이는 바르게 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L06_challenge#1','math',2,1,'u6','L06','g2_1_math_u6_L06_challenge','lesson_challenge','M2-1-u6-C5',2,'mc','auto','7 × 4를 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-1-u6-X11']::text[],true,'{"seq":1,"concept":"M2-1-u6-C5","difficulty":2,"kind":"mc","stem":"7 × 4를 바르게 읽은 것은 어느 것인가요?","explanation":["× 는 「곱하기」라고 읽어요.","앞의 수부터 차례로 읽어 「7 곱하기 4」예요.","7 × 4 = 28은 「7 곱하기 4는 28과 같습니다」라고도 읽어요."],"variant_rule":{"mul":{"ask":"read"}},"options":[{"t":"7 곱하기 4","correct":true},{"t":"7 더하기 4","mis":"M2-1-u6-X11"},{"t":"4 곱하기 7","mis":"M2-1-u6-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L06_challenge#2','math',2,1,'u6','L06','g2_1_math_u6_L06_challenge','lesson_challenge','M2-1-u6-C5',2,'ox','auto','3 + 3 + 3 + 3 + 3 + 3 = 3 × 5입니다.',ARRAY['M2-1-u6-X12']::text[],true,'{"seq":2,"concept":"M2-1-u6-C5","difficulty":2,"kind":"ox","stem":"3 + 3 + 3 + 3 + 3 + 3 = 3 × 5입니다.","explanation":["3이 몇 번 나오는지 세어요 — 6번이에요.","3을 6번 더한 것은 3 × 6이에요.","더하기 기호의 수가 아니라 더한 수의 개수를 세어요."],"variant_rule":{"mul":{"ask":"add"}},"answer":"X","reason_options":[{"t":"3을 6번 더했으니 3 × 6이 맞으니까","correct":true},{"t":"더하기 기호가 5개니까","mis":"M2-1-u6-X12"}],"mis":"M2-1-u6-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L06_challenge#3','math',2,1,'u6','L06','g2_1_math_u6_L06_challenge','lesson_challenge','M2-1-u6-C5',3,'mc','auto','6 + 6 + 6 + 6을 곱셈식으로 나타내고 계산한 것은 어느 것인가요?',ARRAY['M2-1-u6-X12','M2-1-u6-X11']::text[],false,'{"seq":3,"concept":"M2-1-u6-C5","difficulty":3,"kind":"mc","stem":"6 + 6 + 6 + 6을 곱셈식으로 나타내고 계산한 것은 어느 것인가요?","options":[{"t":"6 × 4 = 24","correct":true},{"t":"6 × 3 = 18","mis":"M2-1-u6-X12"},{"t":"6 + 4 = 10","mis":"M2-1-u6-X11"}],"explanation":["6을 4번 더했어요.","곱셈식으로 6 × 4이고, 6, 12, 18, 24로 뛰어 세면 24예요.","더하기 기호의 수 3이 아니라 6이 나온 횟수 4를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L06_challenge#4','math',2,1,'u6','L06','g2_1_math_u6_L06_challenge','lesson_challenge','M2-1-u6-C5',3,'sa','auto','8 × 4는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M2-1-u6-C5","difficulty":3,"kind":"sa","stem":"8 × 4는 얼마인가요? 숫자로 쓰세요.","explanation":["8 × 4는 8의 4배예요.","8씩 뛰어 세면 8, 16, 24, 32.","그래서 8 × 4 = 32예요."],"variant_rule":{"mul":{"ask":"value"}},"answer":["32"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L06_challenge#5','math',2,1,'u6','L06','g2_1_math_u6_L06_challenge','lesson_challenge','M2-1-u6-C5',3,'mc','auto','같은 수를 여러 번 더하는 것을 곱셈식으로 나타내면 좋은 점은 어느 것인가요?',ARRAY['M2-1-u6-X11']::text[],false,'{"seq":5,"concept":"M2-1-u6-C5","difficulty":3,"kind":"mc","stem":"같은 수를 여러 번 더하는 것을 곱셈식으로 나타내면 좋은 점은 어느 것인가요?","options":[{"t":"식을 짧고 간단하게 쓸 수 있어요","correct":true},{"t":"더한 수보다 답이 커져요","mis":"M2-1-u6-X11"},{"t":"뛰어 세지 않아도 답이 저절로 나와요","mis":"M2-1-u6-X11"}],"explanation":["5 + 5 + 5 + 5 + 5 + 5는 길지만 5 × 6은 짧아요.","두 식의 값은 30으로 같아요.","곱셈식의 값은 뛰어 세어 구해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L06_challenge#6','math',2,1,'u6','L06','g2_1_math_u6_L06_challenge','lesson_challenge','M2-1-u6-C5',3,'mc','auto','5 + 5 + 5 + 5 + 5 + 5 = 5 × □에서 □ 안에 알맞은 수는 어느 것인가요?',ARRAY['M2-1-u6-X12','M2-1-u6-X11']::text[],false,'{"seq":6,"concept":"M2-1-u6-C5","difficulty":3,"kind":"mc","stem":"5 + 5 + 5 + 5 + 5 + 5 = 5 × □에서 □ 안에 알맞은 수는 어느 것인가요?","options":[{"t":"6","correct":true},{"t":"5","mis":"M2-1-u6-X12"},{"t":"11","mis":"M2-1-u6-X11"}],"explanation":["5가 몇 번 나오는지 세어요.","5를 6번 더했어요.","그래서 5 × 6이에요 — 더하기 기호 5개를 세면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L06_challenge#7','math',2,1,'u6','L06','g2_1_math_u6_L06_challenge','lesson_challenge','M2-1-u6-C5',3,'mc','auto','9와 4의 곱은 얼마인가요?',ARRAY['M2-1-u6-X11','M2-1-u6-X02']::text[],true,'{"seq":7,"concept":"M2-1-u6-C5","difficulty":3,"kind":"mc","stem":"9와 4의 곱은 얼마인가요?","explanation":["9 × 4는 9의 4배예요.","9씩 뛰어 세면 9, 18, 27, 36.","그래서 9와 4의 곱은 36이에요."],"variant_rule":{"mul":{"ask":"prod"}},"options":[{"t":"36","correct":true},{"t":"13","mis":"M2-1-u6-X11"},{"t":"45","mis":"M2-1-u6-X02"},{"t":"27","mis":"M2-1-u6-X02"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L06_challenge#8','math',2,1,'u6','L06','g2_1_math_u6_L06_challenge','lesson_challenge','M2-1-u6-C5',4,'essay','teacher','3 + 3 + 3 + 3 + 3을 곱셈식으로 나타내고, 그 곱셈식을 두 가지 방법으로 읽어 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-1-u6-C5","difficulty":4,"kind":"essay","stem":"3 + 3 + 3 + 3 + 3을 곱셈식으로 나타내고, 그 곱셈식을 두 가지 방법으로 읽어 보세요.","answer_guide":{"answer":"예: 3 × 5 = 15. 「3 곱하기 5는 15와 같습니다.」 「3과 5의 곱은 15입니다.」","scoring_points":["3 × 5로 나타냈는가","곱을 15로 바르게 구했는가","「곱하기」와 「곱」을 써서 두 가지로 읽었는가"]},"explanation":["3을 5번 더했으니 3 × 5예요.","3, 6, 9, 12, 15로 뛰어 세면 15예요.","「3 곱하기 5는 15와 같습니다」, 「3과 5의 곱은 15입니다」라고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L06_challenge#9','math',2,1,'u6','L06','g2_1_math_u6_L06_challenge','lesson_challenge','M2-1-u6-C5',4,'essay','teacher','친구가 2 × 6을 계산해서 8이라고 했어요. 무엇이 잘못되었는지 쓰고 바르게 계산해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-1-u6-C5","difficulty":4,"kind":"essay","stem":"친구가 2 × 6을 계산해서 8이라고 했어요. 무엇이 잘못되었는지 쓰고 바르게 계산해 보세요.","answer_guide":{"answer":"예: 2와 6을 더해서 8이라고 했다. 2 × 6은 2를 6번 더한 것(2씩 6묶음)이므로 2, 4, 6, 8, 10, 12로 12이다.","scoring_points":["2와 6을 더한 것이 잘못이라고 썼는가","2 × 6을 2를 6번 더한 것(2의 6배)으로 설명했는가","12라고 바르게 계산했는가"]},"explanation":["× 는 더하기가 아니에요.","2 × 6은 2의 6배, 2를 6번 더한 것이에요.","2씩 뛰어 세면 12예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L06_challenge#10','math',2,1,'u6','L06','g2_1_math_u6_L06_challenge','lesson_challenge','M2-1-u6-C5',4,'mc','auto','값이 가장 큰 것은 어느 것인가요?',ARRAY['M2-1-u6-X02','M2-1-u6-X12','M2-1-u6-X11']::text[],false,'{"seq":10,"concept":"M2-1-u6-C5","difficulty":4,"kind":"mc","stem":"값이 가장 큰 것은 어느 것인가요?","options":[{"t":"4의 7배","correct":true},{"t":"5 × 5","mis":"M2-1-u6-X02"},{"t":"3 + 3 + 3 + 3 + 3 + 3 + 3 + 3","mis":"M2-1-u6-X12"},{"t":"9 + 9","mis":"M2-1-u6-X11"}],"explanation":["4의 7배는 4, 8, 12, 16, 20, 24, 28로 28이에요.","5 × 5는 25, 3을 8번 더하면 24, 9 + 9는 18이에요.","모두 뛰어 세어 값을 구한 뒤 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L07_basic#1','math',2,1,'u6','L07','g2_1_math_u6_L07_basic','lesson_basic','M2-1-u6-C6',1,'mc','auto','그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u6-X11','M2-1-u6-X03']::text[],true,'{"seq":1,"concept":"M2-1-u6-C6","difficulty":1,"kind":"mc","stem":"그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["4개씩 6묶음이에요.","4의 6배이니 곱셈식으로 4 × 6이에요.","4 × 6 = 24, 모두 24개예요."],"variant_rule":{"mul":{"ask":"expr"}},"options":[{"t":"4 × 6","correct":true},{"t":"4 + 6","mis":"M2-1-u6-X11"},{"t":"4 × 7","mis":"M2-1-u6-X03"}],"asset":{"type":"mul_groups","item":"⭐","k":4,"n":6}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L07_basic#2','math',2,1,'u6','L07','g2_1_math_u6_L07_basic','lesson_basic','M2-1-u6-C6',1,'mc','auto','6 × 4와 곱이 같은 곱셈식은 어느 것인가요?',ARRAY['M2-1-u6-X13']::text[],true,'{"seq":2,"concept":"M2-1-u6-C6","difficulty":1,"kind":"mc","stem":"6 × 4와 곱이 같은 곱셈식은 어느 것인가요?","explanation":["6 × 4는 6씩 4묶음, 4 × 6은 4씩 6묶음이에요.","같은 24개를 가로로 묶느냐 세로로 묶느냐의 차이예요.","그래서 6 × 4와 4 × 6의 곱은 24로 같아요."],"variant_rule":{"mul":{"ask":"same"}},"options":[{"t":"4 × 6","correct":true},{"t":"6 × 6","mis":"M2-1-u6-X13"},{"t":"4 × 4","mis":"M2-1-u6-X13"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L07_basic#3','math',2,1,'u6','L07','g2_1_math_u6_L07_basic','lesson_basic','M2-1-u6-C6',1,'sa','auto','자전거 한 대에 바퀴가 2개씩 있어요. 자전거 5대의 바퀴는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-1-u6-C6","difficulty":1,"kind":"sa","stem":"자전거 한 대에 바퀴가 2개씩 있어요. 자전거 5대의 바퀴는 모두 몇 개인가요? 숫자로 쓰세요.","explanation":["자전거 한 대에 2개씩, 5대이면 2씩 5묶음이에요.","2 × 5 = 10이에요.","바퀴는 모두 10개예요."],"variant_rule":{"mul":{"ask":"story"}},"answer":["10","10개"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L07_basic#4','math',2,1,'u6','L07','g2_1_math_u6_L07_basic','lesson_basic','M2-1-u6-C6',1,'ox','auto','4 × 6과 6 × 4는 곱이 같아요.',ARRAY['M2-1-u6-X13']::text[],true,'{"seq":4,"concept":"M2-1-u6-C6","difficulty":1,"kind":"ox","stem":"4 × 6과 6 × 4는 곱이 같아요.","answer":"O","reason_options":[{"t":"같은 24개를 가로로도 세로로도 묶을 수 있으니까","correct":true},{"t":"앞의 수가 크면 곱도 크니까","mis":"M2-1-u6-X13"}],"mis":"M2-1-u6-X13","explanation":["4 × 6은 4씩 6묶음, 6 × 4는 6씩 4묶음이에요.","두 식 모두 24예요.","곱하는 두 수의 순서를 바꾸어도 곱은 같아요."],"variant_rule":{"alt":[{"stem":"3 × 8과 8 × 3은 곱이 달라요.","answer":"X","reason_options":[{"t":"둘 다 24로 곱이 같으니까","correct":true},{"t":"수의 순서가 다르면 곱도 다르니까","mis":"M2-1-u6-X13"}],"explanation":["3 × 8은 3씩 8묶음으로 24예요.","8 × 3은 8씩 3묶음으로 24예요.","순서를 바꾸어도 곱은 같아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L07_basic#5','math',2,1,'u6','L07','g2_1_math_u6_L07_basic','lesson_basic','M2-1-u6-C6',2,'mc','auto','사자 한 마리에 다리가 4개씩 있어요. 사자 3마리의 다리는 모두 몇 개인가요?',ARRAY['M2-1-u6-X06','M2-1-u6-X14']::text[],true,'{"seq":5,"concept":"M2-1-u6-C6","difficulty":2,"kind":"mc","stem":"사자 한 마리에 다리가 4개씩 있어요. 사자 3마리의 다리는 모두 몇 개인가요?","explanation":["사자 한 마리에 4개씩, 3마리이면 4씩 3묶음이에요.","4 × 3 = 12예요.","다리는 모두 12개예요."],"variant_rule":{"mul":{"ask":"story"}},"options":[{"t":"12개","correct":true},{"t":"7개","mis":"M2-1-u6-X06"},{"t":"3개","mis":"M2-1-u6-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L07_basic#6','math',2,1,'u6','L07','g2_1_math_u6_L07_basic','lesson_basic','M2-1-u6-C6',2,'mc','auto','곱이 24인 곱셈식이 아닌 것은 어느 것인가요?',ARRAY['M2-1-u6-X15']::text[],true,'{"seq":6,"concept":"M2-1-u6-C6","difficulty":2,"kind":"mc","stem":"곱이 24인 곱셈식이 아닌 것은 어느 것인가요?","explanation":["5 × 5 = 25예요.","나머지 곱셈식의 곱은 모두 24예요.","「아닌 것」을 묻는지 다시 읽어요 — 같은 수도 여러 곱셈식으로 나타낼 수 있어요."],"variant_rule":{"mul":{"ask":"notx"}},"options":[{"t":"5 × 5","correct":true},{"t":"8 × 3","mis":"M2-1-u6-X15"},{"t":"3 × 8","mis":"M2-1-u6-X15"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L07_basic#7','math',2,1,'u6','L07','g2_1_math_u6_L07_basic','lesson_basic','M2-1-u6-C6',2,'mc','auto','그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u6-X11','M2-1-u6-X03']::text[],true,'{"seq":7,"concept":"M2-1-u6-C6","difficulty":2,"kind":"mc","stem":"그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["한 줄에 6개씩 3줄이에요.","6의 3배이니 곱셈식으로 6 × 3이에요.","6 × 3 = 18, 모두 18개예요."],"variant_rule":{"mul":{"ask":"expr","look":"rows"}},"options":[{"t":"6 × 3","correct":true},{"t":"6 + 3","mis":"M2-1-u6-X11"},{"t":"6 × 4","mis":"M2-1-u6-X03"}],"asset":{"type":"mul_groups","item":"⚽","k":6,"n":3,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L07_basic#8','math',2,1,'u6','L07','g2_1_math_u6_L07_basic','lesson_basic','M2-1-u6-C6',2,'match','auto','곱셈식과 곱을 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M2-1-u6-C6","difficulty":2,"kind":"match","stem":"곱셈식과 곱을 이으세요.","pairs":[{"l":"4 × 6","r":"24"},{"l":"2 × 5","r":"10"},{"l":"3 × 4","r":"12"}],"mis":"M2-1-u6-X02","explanation":["4씩 뛰어 세면 4, 8, 12, 16, 20, 24예요.","2씩 뛰어 세면 2, 4, 6, 8, 10이에요.","3씩 뛰어 세면 3, 6, 9, 12예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 곱셈식과 곱을 이으세요.","pairs":[{"l":"5 × 4","r":"20"},{"l":"3 × 6","r":"18"},{"l":"7 × 2","r":"14"}],"explanation":["5씩 뛰어 세면 5, 10, 15, 20이에요.","3씩 뛰어 세면 3, 6, 9, 12, 15, 18이에요.","7씩 뛰어 세면 7, 14예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L07_basic#9','math',2,1,'u6','L07','g2_1_math_u6_L07_basic','lesson_basic','M2-1-u6-C6',2,'mc','auto','닭 한 마리에 다리가 2개씩 있어요. 닭 6마리의 다리 수를 구하는 곱셈식은 어느 것인가요?',ARRAY['M2-1-u6-X11','M2-1-u6-X14']::text[],true,'{"seq":9,"concept":"M2-1-u6-C6","difficulty":2,"kind":"mc","stem":"닭 한 마리에 다리가 2개씩 있어요. 닭 6마리의 다리 수를 구하는 곱셈식은 어느 것인가요?","explanation":["한 마리에 2개씩 — 한 묶음은 2예요.","닭이 6마리이니 2씩 6묶음, 2의 6배예요.","곱셈식은 2 × 6 = 12예요."],"variant_rule":{"mul":{"ask":"sexpr"}},"options":[{"t":"2 × 6","correct":true},{"t":"2 + 6","mis":"M2-1-u6-X11"},{"t":"2 × 2","mis":"M2-1-u6-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L07_basic#10','math',2,1,'u6','L07','g2_1_math_u6_L07_basic','lesson_basic','M2-1-u6-C6',3,'error','auto','소고 24개를 곱셈식으로 나타냈어요. 잘못 나타낸 친구는 누구인가요?',ARRAY['M2-1-u6-X02','M2-1-u6-X15']::text[],true,'{"seq":10,"concept":"M2-1-u6-C6","difficulty":3,"kind":"error","stem":"소고 24개를 곱셈식으로 나타냈어요. 잘못 나타낸 친구는 누구인가요?","options":[{"t":"예린 — 「5 × 5」","correct":true,"mis_target":"M2-1-u6-X02"},{"t":"태민 — 「3 × 8」","mis":"M2-1-u6-X15"},{"t":"아린 — 「8 × 3」","mis":"M2-1-u6-X15"}],"explanation":["5 × 5는 5씩 5묶음으로 25예요.","24가 아니므로 예린이가 잘못 나타냈어요.","3 × 8과 8 × 3은 모두 24예요."],"variant_rule":{"alt":[{"stem":"구슬 18개를 곱셈식으로 나타냈어요. 잘못 나타낸 친구는 누구인가요?","options":[{"t":"하루 — 「4 × 4」","correct":true,"mis_target":"M2-1-u6-X02"},{"t":"서아 — 「3 × 6」","mis":"M2-1-u6-X15"},{"t":"지우 — 「2 × 9」","mis":"M2-1-u6-X15"}],"explanation":["4 × 4는 4씩 4묶음으로 16이에요.","18이 아니므로 하루가 잘못 나타냈어요.","3 × 6과 2 × 9는 모두 18이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L07_challenge#1','math',2,1,'u6','L07','g2_1_math_u6_L07_challenge','lesson_challenge','M2-1-u6-C6',2,'mc','auto','문어 한 마리에 다리가 8개씩 있어요. 문어 3마리의 다리 수를 구하는 곱셈식은 어느 것인가요?',ARRAY['M2-1-u6-X11','M2-1-u6-X14']::text[],true,'{"seq":1,"concept":"M2-1-u6-C6","difficulty":2,"kind":"mc","stem":"문어 한 마리에 다리가 8개씩 있어요. 문어 3마리의 다리 수를 구하는 곱셈식은 어느 것인가요?","explanation":["한 마리에 8개씩 — 한 묶음은 8이에요.","문어가 3마리이니 8씩 3묶음, 8의 3배예요.","곱셈식은 8 × 3 = 24예요."],"variant_rule":{"mul":{"ask":"sexpr"}},"options":[{"t":"8 × 3","correct":true},{"t":"8 + 3","mis":"M2-1-u6-X11"},{"t":"8 × 8","mis":"M2-1-u6-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L07_challenge#2','math',2,1,'u6','L07','g2_1_math_u6_L07_challenge','lesson_challenge','M2-1-u6-C6',2,'mc','auto','3 × 8과 곱이 같은 곱셈식은 어느 것인가요?',ARRAY['M2-1-u6-X13']::text[],true,'{"seq":2,"concept":"M2-1-u6-C6","difficulty":2,"kind":"mc","stem":"3 × 8과 곱이 같은 곱셈식은 어느 것인가요?","explanation":["3 × 8은 3씩 8묶음, 8 × 3은 8씩 3묶음이에요.","같은 24개를 가로로 묶느냐 세로로 묶느냐의 차이예요.","그래서 3 × 8과 8 × 3의 곱은 24로 같아요."],"variant_rule":{"mul":{"ask":"same"}},"options":[{"t":"8 × 3","correct":true},{"t":"3 × 3","mis":"M2-1-u6-X13"},{"t":"8 × 8","mis":"M2-1-u6-X13"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L07_challenge#3','math',2,1,'u6','L07','g2_1_math_u6_L07_challenge','lesson_challenge','M2-1-u6-C6',3,'mc','auto','곱이 18인 곱셈식이 아닌 것은 어느 것인가요?',ARRAY['M2-1-u6-X15']::text[],true,'{"seq":3,"concept":"M2-1-u6-C6","difficulty":3,"kind":"mc","stem":"곱이 18인 곱셈식이 아닌 것은 어느 것인가요?","explanation":["4 × 4 = 16이에요.","나머지 곱셈식의 곱은 모두 18이에요.","「아닌 것」을 묻는지 다시 읽어요 — 같은 수도 여러 곱셈식으로 나타낼 수 있어요."],"variant_rule":{"mul":{"ask":"notx"}},"options":[{"t":"4 × 4","correct":true},{"t":"6 × 3","mis":"M2-1-u6-X15"},{"t":"3 × 6","mis":"M2-1-u6-X15"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L07_challenge#4','math',2,1,'u6','L07','g2_1_math_u6_L07_challenge','lesson_challenge','M2-1-u6-C6',3,'sa','auto','개미 한 마리에 다리가 6개씩 있어요. 개미 5마리의 다리는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M2-1-u6-C6","difficulty":3,"kind":"sa","stem":"개미 한 마리에 다리가 6개씩 있어요. 개미 5마리의 다리는 모두 몇 개인가요? 숫자로 쓰세요.","explanation":["개미 한 마리에 6개씩, 5마리이면 6씩 5묶음이에요.","6 × 5 = 30이에요.","다리는 모두 30개예요."],"variant_rule":{"mul":{"ask":"story"}},"answer":["30","30개"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L07_challenge#5','math',2,1,'u6','L07','g2_1_math_u6_L07_challenge','lesson_challenge','M2-1-u6-C6',3,'mc','auto','종이비행기를 매일 3개씩 5일 동안 만들었어요. 만든 종이비행기의 수를 구하는 곱셈식으로 알맞은 것은 어느 것인가요?',ARRAY['M2-1-u6-X14','M2-1-u6-X11']::text[],false,'{"seq":5,"concept":"M2-1-u6-C6","difficulty":3,"kind":"mc","stem":"종이비행기를 매일 3개씩 5일 동안 만들었어요. 만든 종이비행기의 수를 구하는 곱셈식으로 알맞은 것은 어느 것인가요?","options":[{"t":"3 × 5 (3개씩 5일)","correct":true},{"t":"5 × 3 (5개씩 3일)","mis":"M2-1-u6-X14"},{"t":"3 + 5","mis":"M2-1-u6-X11"}],"explanation":["하루에 3개씩 — 한 묶음은 3이에요.","5일 동안이니 3씩 5묶음, 3 × 5예요.","「5개씩 3일」은 다른 상황이에요(곱은 같아도 상황이 달라요)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L07_challenge#6','math',2,1,'u6','L07','g2_1_math_u6_L07_challenge','lesson_challenge','M2-1-u6-C6',3,'mc','auto','한 상자에 컵케이크가 4개씩 들어 있어요. 6상자에 든 컵케이크의 수를 곱셈식으로 바르게 구한 것은 어느 것인가요?',ARRAY['M2-1-u6-X11','M2-1-u6-X14']::text[],false,'{"seq":6,"concept":"M2-1-u6-C6","difficulty":3,"kind":"mc","stem":"한 상자에 컵케이크가 4개씩 들어 있어요. 6상자에 든 컵케이크의 수를 곱셈식으로 바르게 구한 것은 어느 것인가요?","options":[{"t":"4 × 6 = 24","correct":true},{"t":"4 + 6 = 10","mis":"M2-1-u6-X11"},{"t":"6 × 6 = 36","mis":"M2-1-u6-X14"}],"explanation":["한 상자에 4개씩 — 한 묶음은 4예요.","6상자이니 4씩 6묶음, 4 × 6이에요.","4, 8, 12, 16, 20, 24로 뛰어 세면 24예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L07_challenge#7','math',2,1,'u6','L07','g2_1_math_u6_L07_challenge','lesson_challenge','M2-1-u6-C6',3,'mc','auto','그림의 별을 나타내는 곱셈식이 아닌 것은 어느 것인가요?',ARRAY['M2-1-u6-X15']::text[],false,'{"seq":7,"concept":"M2-1-u6-C6","difficulty":3,"kind":"mc","stem":"그림의 별을 나타내는 곱셈식이 아닌 것은 어느 것인가요?","options":[{"t":"5 × 4","correct":true},{"t":"6 × 4","mis":"M2-1-u6-X15"},{"t":"4 × 6","mis":"M2-1-u6-X15"},{"t":"3 × 8","mis":"M2-1-u6-X15"}],"explanation":["별은 한 줄에 6개씩 4줄로 24개예요.","6 × 4, 4 × 6, 3 × 8은 모두 24예요.","5 × 4는 20이라 그림과 달라요 — 「아닌 것」을 물었어요."],"asset":{"type":"mul_groups","item":"⭐","k":6,"n":4,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L07_challenge#8','math',2,1,'u6','L07','g2_1_math_u6_L07_challenge','lesson_challenge','M2-1-u6-C6',4,'essay','teacher','그림의 별을 두 가지 곱셈식으로 나타내고, 두 곱셈식의 곱이 같은 까닭을 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M2-1-u6-C6","difficulty":4,"kind":"essay","stem":"그림의 별을 두 가지 곱셈식으로 나타내고, 두 곱셈식의 곱이 같은 까닭을 써 보세요.","answer_guide":{"answer":"예: 한 줄에 8개씩 3줄이므로 8 × 3 = 24, 세로로 3개씩 8줄로 보면 3 × 8 = 24이다. 같은 별을 묶는 방법만 바꾸었으므로 곱이 같다.","scoring_points":["가로로 묶은 곱셈식을 썼는가","세로로 묶은 곱셈식을 썼는가","같은 별을 묶는 방법만 바꾸었기 때문이라고 썼는가"]},"explanation":["가로로 보면 8씩 3줄이에요.","세로로 보면 3씩 8줄이에요.","같은 24개를 다르게 묶었을 뿐이에요."],"asset":{"type":"mul_groups","item":"⭐","k":8,"n":3,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L07_challenge#9','math',2,1,'u6','L07','g2_1_math_u6_L07_challenge','lesson_challenge','M2-1-u6-C6',4,'essay','teacher','우리 생활에서 곱셈식으로 나타낼 수 있는 상황을 하나 만들고, 곱셈식과 답을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-1-u6-C6","difficulty":4,"kind":"essay","stem":"우리 생활에서 곱셈식으로 나타낼 수 있는 상황을 하나 만들고, 곱셈식과 답을 써 보세요.","answer_guide":{"answer":"예: 세발자전거 한 대에 바퀴가 3개씩 있다. 세발자전거 4대의 바퀴는 3 × 4 = 12, 모두 12개이다.","scoring_points":["같은 수씩 여러 묶음이 있는 상황을 만들었는가","한 묶음의 수와 묶음의 수를 바르게 써서 곱셈식으로 나타냈는가","답을 뛰어 세어 바르게 구했는가"]},"explanation":["「한 ○에 몇 개씩」 있는 것을 찾아요.","한 묶음의 수 × 묶음의 수로 써요.","뛰어 세어 답을 구해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_L07_challenge#10','math',2,1,'u6','L07','g2_1_math_u6_L07_challenge','lesson_challenge','M2-1-u6-C6',4,'mc','auto','의자가 한 줄에 5개씩 4줄 있고, 그 뒤에 한 줄에 4개씩 3줄이 더 있어요. 의자는 모두 몇 개인가요?',ARRAY['M2-1-u6-X06','M2-1-u6-X14','M2-1-u6-X05']::text[],false,'{"seq":10,"concept":"M2-1-u6-C6","difficulty":4,"kind":"mc","stem":"의자가 한 줄에 5개씩 4줄 있고, 그 뒤에 한 줄에 4개씩 3줄이 더 있어요. 의자는 모두 몇 개인가요?","options":[{"t":"32개","correct":true},{"t":"16개","mis":"M2-1-u6-X06"},{"t":"35개","mis":"M2-1-u6-X14"},{"t":"20개","mis":"M2-1-u6-X05"}],"explanation":["앞쪽은 5 × 4 = 20개예요.","뒤쪽은 4 × 3 = 12개예요.","20 + 12 = 32이니 모두 32개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_a#1','math',2,1,'u6','','g2_1_math_u6_review_a','unit_review','M2-1-u6-C1',1,'sa','auto','2씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-1-u6-C1","difficulty":1,"kind":"sa","stem":"2씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["2씩 커지는 수예요.","8에서 2만큼 더 뛰면 10이에요.","2씩 5번 뛰어 센 수 — 2씩 5묶음과 같아요."],"variant_rule":{"mul":{"ask":"skip"}},"answer":["10"],"asset":{"type":"jump_row","cells":[2,4,6,8,null],"step":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_a#2','math',2,1,'u6','','g2_1_math_u6_review_a','unit_review','M2-1-u6-C2',1,'mc','auto','그림을 보세요. 쿠키는 모두 몇 개인가요?',ARRAY['M2-1-u6-X06','M2-1-u6-X05']::text[],true,'{"seq":2,"concept":"M2-1-u6-C2","difficulty":1,"kind":"mc","stem":"그림을 보세요. 쿠키는 모두 몇 개인가요?","explanation":["6개씩 3묶음이에요.","6씩 뛰어 세면 6, 12, 18.","쿠키는 모두 18개예요."],"variant_rule":{"mul":{"ask":"total"}},"options":[{"t":"18개","correct":true},{"t":"9개","mis":"M2-1-u6-X06"},{"t":"3개","mis":"M2-1-u6-X05"}],"asset":{"type":"mul_groups","item":"🍪","k":6,"n":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_a#3','math',2,1,'u6','','g2_1_math_u6_review_a','unit_review','M2-1-u6-C2',1,'mc','auto','그림을 「몇씩 몇 묶음」으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u6-X04','M2-1-u6-X03']::text[],true,'{"seq":3,"concept":"M2-1-u6-C2","difficulty":1,"kind":"mc","stem":"그림을 「몇씩 몇 묶음」으로 바르게 나타낸 것은 어느 것인가요?","explanation":["한 묶음에 병아리가 3마리씩 있어요.","묶음은 모두 4개예요.","그래서 3씩 4묶음이에요 — 「몇씩」은 한 묶음 안의 수, 「몇 묶음」은 묶음의 수예요."],"variant_rule":{"mul":{"ask":"name"}},"options":[{"t":"3씩 4묶음","correct":true},{"t":"4씩 3묶음","mis":"M2-1-u6-X04"},{"t":"3씩 5묶음","mis":"M2-1-u6-X03"}],"asset":{"type":"mul_groups","item":"🐥","k":3,"n":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_a#4','math',2,1,'u6','','g2_1_math_u6_review_a','unit_review','M2-1-u6-C3',1,'mc','auto','그림을 「몇의 몇 배」로 나타내면 어느 것인가요?',ARRAY['M2-1-u6-X07','M2-1-u6-X03']::text[],true,'{"seq":4,"concept":"M2-1-u6-C3","difficulty":1,"kind":"mc","stem":"그림을 「몇의 몇 배」로 나타내면 어느 것인가요?","explanation":["6씩 3묶음이에요.","6씩 3묶음은 6의 3배예요.","「몇의」에는 한 묶음의 수, 「몇 배」에는 묶음의 수를 써요."],"variant_rule":{"mul":{"ask":"times"}},"options":[{"t":"6의 3배","correct":true},{"t":"3의 6배","mis":"M2-1-u6-X07"},{"t":"6의 4배","mis":"M2-1-u6-X03"}],"asset":{"type":"mul_groups","item":"🎈","k":6,"n":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_a#5','math',2,1,'u6','','g2_1_math_u6_review_a','unit_review','M2-1-u6-C3',1,'sa','auto','6의 3배는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M2-1-u6-C3","difficulty":1,"kind":"sa","stem":"6의 3배는 얼마인가요? 숫자로 쓰세요.","explanation":["6의 3배는 6씩 3묶음이에요.","6씩 뛰어 세면 6, 12, 18.","그래서 6의 3배는 18이에요."],"variant_rule":{"mul":{"ask":"tval"}},"answer":["18"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_a#6','math',2,1,'u6','','g2_1_math_u6_review_a','unit_review','M2-1-u6-C4',1,'mc','auto','갈색 막대는 빨강 막대를 겹치지 않게 이어 붙인 길이와 같아요. 갈색 막대는 빨강 막대의 몇 배인가요?',ARRAY['M2-1-u6-X10']::text[],true,'{"seq":6,"concept":"M2-1-u6-C4","difficulty":1,"kind":"mc","stem":"갈색 막대는 빨강 막대를 겹치지 않게 이어 붙인 길이와 같아요. 갈색 막대는 빨강 막대의 몇 배인가요?","explanation":["빨강 막대를 겹치지 않게 이어 붙인 자리를 세어요.","빨강 막대가 5번 들어가요.","그래서 갈색 막대는 빨강 막대의 5배예요."],"variant_rule":{"mul":{"ask":"bars"}},"options":[{"t":"5배","correct":true},{"t":"6배","mis":"M2-1-u6-X10"},{"t":"4배","mis":"M2-1-u6-X10"}],"asset":{"type":"times_bars","base":1,"times":5,"a":"빨강","b":"갈색"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_a#7','math',2,1,'u6','','g2_1_math_u6_review_a','unit_review','M2-1-u6-C5',1,'mc','auto','6 × 3을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-1-u6-X11']::text[],true,'{"seq":7,"concept":"M2-1-u6-C5","difficulty":1,"kind":"mc","stem":"6 × 3을 바르게 읽은 것은 어느 것인가요?","explanation":["× 는 「곱하기」라고 읽어요.","앞의 수부터 차례로 읽어 「6 곱하기 3」이에요.","6 × 3 = 18은 「6 곱하기 3은 18과 같습니다」라고도 읽어요."],"variant_rule":{"mul":{"ask":"read"}},"options":[{"t":"6 곱하기 3","correct":true},{"t":"6 더하기 3","mis":"M2-1-u6-X11"},{"t":"3 곱하기 6","mis":"M2-1-u6-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_a#8','math',2,1,'u6','','g2_1_math_u6_review_a','unit_review','M2-1-u6-C5',1,'sa','auto','6 × 3은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M2-1-u6-C5","difficulty":1,"kind":"sa","stem":"6 × 3은 얼마인가요? 숫자로 쓰세요.","explanation":["6 × 3은 6의 3배예요.","6씩 뛰어 세면 6, 12, 18.","그래서 6 × 3 = 18이에요."],"variant_rule":{"mul":{"ask":"value"}},"answer":["18"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_a#9','math',2,1,'u6','','g2_1_math_u6_review_a','unit_review','M2-1-u6-C5',2,'mc','auto','2 + 2 + 2 + 2 + 2 + 2를 곱셈식으로 나타내면 어느 것인가요?',ARRAY['M2-1-u6-X12','M2-1-u6-X11']::text[],true,'{"seq":9,"concept":"M2-1-u6-C5","difficulty":2,"kind":"mc","stem":"2 + 2 + 2 + 2 + 2 + 2를 곱셈식으로 나타내면 어느 것인가요?","explanation":["2가 6번 나와요.","2를 6번 더한 것은 2 × 6이에요.","2 × 6 = 12 — 덧셈식보다 짧게 쓸 수 있어요."],"variant_rule":{"mul":{"ask":"add"}},"options":[{"t":"2 × 6","correct":true},{"t":"2 × 5","mis":"M2-1-u6-X12"},{"t":"2 + 6","mis":"M2-1-u6-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_a#10','math',2,1,'u6','','g2_1_math_u6_review_a','unit_review','M2-1-u6-C6',2,'mc','auto','그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u6-X11','M2-1-u6-X03']::text[],true,'{"seq":10,"concept":"M2-1-u6-C6","difficulty":2,"kind":"mc","stem":"그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["한 줄에 5개씩 2줄이에요.","5의 2배이니 곱셈식으로 5 × 2예요.","5 × 2 = 10, 모두 10개예요."],"variant_rule":{"mul":{"ask":"expr","look":"rows"}},"options":[{"t":"5 × 2","correct":true},{"t":"5 + 2","mis":"M2-1-u6-X11"},{"t":"5 × 3","mis":"M2-1-u6-X03"}],"asset":{"type":"mul_groups","item":"🍅","k":5,"n":2,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_a#11','math',2,1,'u6','','g2_1_math_u6_review_a','unit_review','M2-1-u6-C6',2,'mc','auto','꽃 한 송이에 꽃잎이 5장씩 있어요. 꽃 5송이의 꽃잎은 모두 몇 장인가요?',ARRAY['M2-1-u6-X06','M2-1-u6-X14']::text[],true,'{"seq":11,"concept":"M2-1-u6-C6","difficulty":2,"kind":"mc","stem":"꽃 한 송이에 꽃잎이 5장씩 있어요. 꽃 5송이의 꽃잎은 모두 몇 장인가요?","explanation":["꽃 한 송이에 5장씩, 5송이이면 5씩 5묶음이에요.","5 × 5 = 25예요.","꽃잎은 모두 25장이에요."],"variant_rule":{"mul":{"ask":"story"}},"options":[{"t":"25장","correct":true},{"t":"10장","mis":"M2-1-u6-X06"},{"t":"5장","mis":"M2-1-u6-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_a#12','math',2,1,'u6','','g2_1_math_u6_review_a','unit_review','M2-1-u6-C6',2,'mc','auto','7 × 5와 곱이 같은 곱셈식은 어느 것인가요?',ARRAY['M2-1-u6-X13']::text[],true,'{"seq":12,"concept":"M2-1-u6-C6","difficulty":2,"kind":"mc","stem":"7 × 5와 곱이 같은 곱셈식은 어느 것인가요?","explanation":["7 × 5는 7씩 5묶음, 5 × 7은 5씩 7묶음이에요.","같은 35개를 가로로 묶느냐 세로로 묶느냐의 차이예요.","그래서 7 × 5와 5 × 7의 곱은 35로 같아요."],"variant_rule":{"mul":{"ask":"same"}},"options":[{"t":"5 × 7","correct":true},{"t":"7 × 7","mis":"M2-1-u6-X13"},{"t":"5 × 5","mis":"M2-1-u6-X13"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_a#13','math',2,1,'u6','','g2_1_math_u6_review_a','unit_review','M2-1-u6-C2',2,'mc','auto','그림의 쿠키를 3개씩 묶으면 몇 묶음인가요?',ARRAY['M2-1-u6-X04','M2-1-u6-X05']::text[],true,'{"seq":13,"concept":"M2-1-u6-C2","difficulty":2,"kind":"mc","stem":"그림의 쿠키를 3개씩 묶으면 몇 묶음인가요?","explanation":["쿠키는 모두 18개예요.","3개씩 묶으면 3, 6, 9, 12, 15, 18 — 6번 묶여요.","그래서 3씩 6묶음이에요."],"variant_rule":{"mul":{"ask":"groups"}},"options":[{"t":"6묶음","correct":true},{"t":"3묶음","mis":"M2-1-u6-X04"},{"t":"18묶음","mis":"M2-1-u6-X05"}],"asset":{"type":"mul_groups","item":"🍪","look":"loose","total":18,"cols":7}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_a#14','math',2,1,'u6','','g2_1_math_u6_review_a','unit_review','M2-1-u6-C4',2,'mc','auto','사과는 2개, 토마토는 8개예요. 토마토의 수는 사과의 수의 몇 배인가요?',ARRAY['M2-1-u6-X09']::text[],true,'{"seq":14,"concept":"M2-1-u6-C4","difficulty":2,"kind":"mc","stem":"사과는 2개, 토마토는 8개예요. 토마토의 수는 사과의 수의 몇 배인가요?","explanation":["사과 2개가 기준이에요.","토마토 8개를 2개씩 묶으면 4묶음이에요.","그래서 토마토의 수는 사과의 수의 4배예요."],"variant_rule":{"mul":{"ask":"cmp"}},"options":[{"t":"4배","correct":true},{"t":"8배","mis":"M2-1-u6-X09"},{"t":"6배","mis":"M2-1-u6-X09"}],"asset":{"type":"times_bars","base":2,"times":4,"a":"사과","b":"토마토","item":"🍎","item2":"🍅"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_a#15','math',2,1,'u6','','g2_1_math_u6_review_a','unit_review','M2-1-u6-C3',2,'ox','auto','6씩 3묶음은 6의 3배이고, 모두 18개예요.',ARRAY['M2-1-u6-X06']::text[],false,'{"seq":15,"concept":"M2-1-u6-C3","difficulty":2,"kind":"ox","stem":"6씩 3묶음은 6의 3배이고, 모두 18개예요.","answer":"O","reason_options":[{"t":"6씩 뛰어 세면 6, 12, 18이니까","correct":true},{"t":"6과 3을 더해 9개니까","mis":"M2-1-u6-X06"}],"mis":"M2-1-u6-X06","explanation":["6씩 3묶음은 6의 3배예요.","6, 12, 18로 뛰어 세면 18이에요.","그래서 바른 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_a#16','math',2,1,'u6','','g2_1_math_u6_review_a','unit_review','M2-1-u6-C7',2,'match','auto','같은 뜻을 나타내는 것끼리 이으세요.','{}'::text[],false,'{"seq":16,"concept":"M2-1-u6-C7","difficulty":2,"kind":"match","stem":"같은 뜻을 나타내는 것끼리 이으세요.","pairs":[{"l":"3 + 3","r":"3 × 2"},{"l":"2씩 3묶음","r":"2 × 3"},{"l":"3의 3배","r":"3 × 3"}],"mis":"M2-1-u6-X07","explanation":["3 + 3은 3을 2번 더했으니 3 × 2예요.","2씩 3묶음은 2의 3배, 2 × 3이에요.","3의 3배는 3 × 3이에요 — 「몇의」 수가 × 앞에 와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_a#17','math',2,1,'u6','','g2_1_math_u6_review_a','unit_review','M2-1-u6-C6',3,'mc','auto','곱이 18인 곱셈식이 아닌 것은 어느 것인가요?',ARRAY['M2-1-u6-X15']::text[],true,'{"seq":17,"concept":"M2-1-u6-C6","difficulty":3,"kind":"mc","stem":"곱이 18인 곱셈식이 아닌 것은 어느 것인가요?","explanation":["4 × 4 = 16이에요.","나머지 곱셈식의 곱은 모두 18이에요.","「아닌 것」을 묻는지 다시 읽어요 — 같은 수도 여러 곱셈식으로 나타낼 수 있어요."],"variant_rule":{"mul":{"ask":"notx"}},"options":[{"t":"4 × 4","correct":true},{"t":"3 × 6","mis":"M2-1-u6-X15"},{"t":"6 × 3","mis":"M2-1-u6-X15"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_a#18','math',2,1,'u6','','g2_1_math_u6_review_a','unit_review','M2-1-u6-C3',3,'mc','auto','풍선 12개를 2개씩 묶으면 2의 6배예요. 같은 풍선을 4개씩 묶으면 4의 몇 배인가요?',ARRAY['M2-1-u6-X08','M2-1-u6-X07']::text[],true,'{"seq":18,"concept":"M2-1-u6-C3","difficulty":3,"kind":"mc","stem":"풍선 12개를 2개씩 묶으면 2의 6배예요. 같은 풍선을 4개씩 묶으면 4의 몇 배인가요?","explanation":["4개씩 묶으면 4, 8, 12 — 3묶음이에요.","그래서 4의 3배예요.","같은 12개라도 묶는 수가 달라지면 몇 배인지도 달라져요."],"variant_rule":{"mul":{"ask":"regroup"}},"options":[{"t":"3배","correct":true},{"t":"6배","mis":"M2-1-u6-X08"},{"t":"4배","mis":"M2-1-u6-X07"}],"asset":{"type":"mul_groups","item":"🎈","look":"loose","total":12,"cols":7}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_a#19','math',2,1,'u6','','g2_1_math_u6_review_a','unit_review','M2-1-u6-C4',3,'mc','auto','초록 막대의 길이는 빨강 막대의 길이의 몇 배인가요?',ARRAY['M2-1-u6-X10','M2-1-u6-X09']::text[],true,'{"seq":19,"concept":"M2-1-u6-C4","difficulty":3,"kind":"mc","stem":"초록 막대의 길이는 빨강 막대의 길이의 몇 배인가요?","explanation":["빨강 막대는 2칸, 초록 막대는 10칸이에요.","2칸씩 묶으면 초록 막대는 5묶음이에요.","그래서 초록 막대는 빨강 막대의 5배예요 — 칸 수를 그대로 배로 말하면 안 돼요."],"variant_rule":{"mul":{"ask":"bars","grid":true}},"options":[{"t":"5배","correct":true},{"t":"6배","mis":"M2-1-u6-X10"},{"t":"10배","mis":"M2-1-u6-X09"}],"asset":{"type":"times_bars","base":2,"times":5,"a":"빨강","b":"초록","grid":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_a#20','math',2,1,'u6','','g2_1_math_u6_review_a','unit_review','M2-1-u6-C7',3,'mc','auto','곱셈 카드 「5 × 2」와 같은 뜻이 아닌 것은 어느 것인가요?',ARRAY['M2-1-u6-X15']::text[],false,'{"seq":20,"concept":"M2-1-u6-C7","difficulty":3,"kind":"mc","stem":"곱셈 카드 「5 × 2」와 같은 뜻이 아닌 것은 어느 것인가요?","options":[{"t":"5 + 2","correct":true},{"t":"5 + 5","mis":"M2-1-u6-X15"},{"t":"5씩 2묶음","mis":"M2-1-u6-X15"},{"t":"5의 2배","mis":"M2-1-u6-X15"}],"explanation":["5 × 2는 5를 2번 더한 것이에요.","5 + 5, 5씩 2묶음, 5의 2배는 모두 같은 뜻이에요.","5 + 2는 7이라 달라요 — 「아닌 것」을 물었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_a#21','math',2,1,'u6','','g2_1_math_u6_review_a','unit_review','M2-1-u6-C6',3,'mc','auto','강아지 한 마리에 다리가 4개씩 있어요. 강아지 6마리의 다리 수를 구하는 곱셈식은 어느 것인가요?',ARRAY['M2-1-u6-X11','M2-1-u6-X14']::text[],true,'{"seq":21,"concept":"M2-1-u6-C6","difficulty":3,"kind":"mc","stem":"강아지 한 마리에 다리가 4개씩 있어요. 강아지 6마리의 다리 수를 구하는 곱셈식은 어느 것인가요?","explanation":["한 마리에 4개씩 — 한 묶음은 4예요.","강아지가 6마리이니 4씩 6묶음, 4의 6배예요.","곱셈식은 4 × 6 = 24예요."],"variant_rule":{"mul":{"ask":"sexpr"}},"options":[{"t":"4 × 6","correct":true},{"t":"4 + 6","mis":"M2-1-u6-X11"},{"t":"4 × 4","mis":"M2-1-u6-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_a#22','math',2,1,'u6','','g2_1_math_u6_review_a','unit_review','M2-1-u6-C5',3,'error','auto','친구들이 곱셈에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u6-X13','M2-1-u6-X15']::text[],false,'{"seq":22,"concept":"M2-1-u6-C5","difficulty":3,"kind":"error","stem":"친구들이 곱셈에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"곰이 — 「5의 7배와 7의 5배는 곱이 달라.」","correct":true,"mis_target":"M2-1-u6-X13"},{"t":"펭이 — 「6씩 3묶음은 6의 3배야.」","mis":"M2-1-u6-X15"},{"t":"다예 — 「2 + 2 + 2 + 2 + 2 + 2는 2 × 6과 같아.」","mis":"M2-1-u6-X15"}],"explanation":["5의 7배와 7의 5배는 모두 35예요.","곰이의 말이 틀렸어요.","펭이와 다예는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_a#23','math',2,1,'u6','','g2_1_math_u6_review_a','unit_review','M2-1-u6-C7',4,'essay','teacher','그림을 보고 곱셈 카드를 만들려고 해요. 그림을 덧셈식, 「몇씩 몇 묶음」, 「몇의 몇 배」, 곱셈식으로 각각 나타내고 모두 몇인지 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-1-u6-C7","difficulty":4,"kind":"essay","stem":"그림을 보고 곱셈 카드를 만들려고 해요. 그림을 덧셈식, 「몇씩 몇 묶음」, 「몇의 몇 배」, 곱셈식으로 각각 나타내고 모두 몇인지 써 보세요.","answer_guide":{"answer":"예: 3 + 3 = 6, 3씩 2묶음, 3의 2배, 3 × 2 = 6. 개미는 모두 6마리이다.","scoring_points":["덧셈식을 바르게 썼는가","「몇씩 몇 묶음」과 「몇의 몇 배」를 바르게 썼는가","곱셈식과 답을 바르게 썼는가"]},"explanation":["한 묶음의 수와 묶음의 수를 먼저 찾아요.","같은 그림을 여러 가지로 나타낼 수 있어요.","모두 같은 수를 나타내요."],"asset":{"type":"mul_groups","item":"🐜","k":3,"n":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_a#24','math',2,1,'u6','','g2_1_math_u6_review_a','unit_review','M2-1-u6-C6',4,'essay','teacher','그림의 사과를 두 가지 곱셈식으로 나타내고, 두 곱셈식의 곱이 같은 까닭을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-1-u6-C6","difficulty":4,"kind":"essay","stem":"그림의 사과를 두 가지 곱셈식으로 나타내고, 두 곱셈식의 곱이 같은 까닭을 써 보세요.","answer_guide":{"answer":"예: 한 줄에 4개씩 5줄이므로 4 × 5 = 20, 세로로 5개씩 4줄이므로 5 × 4 = 20. 같은 사과를 묶는 방법만 바꾸었으므로 곱이 같다.","scoring_points":["가로로 묶은 곱셈식과 곱을 썼는가","세로로 묶은 곱셈식과 곱을 썼는가","같은 물건을 다르게 묶었을 뿐이라 곱이 같다고 썼는가"]},"explanation":["가로로 한 줄씩 묶어 보아요.","세로로 한 줄씩 묶어 보아요.","묶는 방법만 다르고 물건의 수는 같아요."],"asset":{"type":"mul_groups","item":"🍎","k":4,"n":5,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_a#25','math',2,1,'u6','','g2_1_math_u6_review_a','unit_review','M2-1-u6-C4',4,'essay','teacher','그림에서 파랑 막대는 노랑 막대의 몇 배인지 구하고, 어떻게 구했는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-1-u6-C4","difficulty":4,"kind":"essay","stem":"그림에서 파랑 막대는 노랑 막대의 몇 배인지 구하고, 어떻게 구했는지 설명해 보세요.","answer_guide":{"answer":"예: 노랑 막대는 3칸, 파랑 막대는 12칸이다. 3칸씩 묶으면 4묶음이므로 파랑 막대는 노랑 막대의 4배이다.","scoring_points":["기준이 무엇인지 바르게 찾았는가","기준만큼씩 묶거나 이어 붙인 횟수를 셌는가","몇 배인지 바르게 답했는가"]},"explanation":["견줄 때 바탕이 되는 기준을 먼저 찾아요.","기준만큼씩 묶거나 겹치지 않게 이어 붙여 세어요.","센 횟수가 몇 배예요."],"asset":{"type":"times_bars","base":3,"times":4,"a":"노랑","b":"파랑","grid":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_b#1','math',2,1,'u6','','g2_1_math_u6_review_b','unit_review','M2-1-u6-C1',1,'sa','auto','5씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-1-u6-C1","difficulty":1,"kind":"sa","stem":"5씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["5씩 커지는 수예요.","15에서 5만큼 더 뛰면 20이에요.","5씩 4번 뛰어 센 수 — 5씩 4묶음과 같아요."],"variant_rule":{"mul":{"ask":"skip"}},"answer":["20"],"asset":{"type":"jump_row","cells":[5,10,15,null],"step":5}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_b#2','math',2,1,'u6','','g2_1_math_u6_review_b','unit_review','M2-1-u6-C2',1,'mc','auto','그림을 보세요. 꽃은 모두 몇 송이인가요?',ARRAY['M2-1-u6-X06','M2-1-u6-X05']::text[],true,'{"seq":2,"concept":"M2-1-u6-C2","difficulty":1,"kind":"mc","stem":"그림을 보세요. 꽃은 모두 몇 송이인가요?","explanation":["3송이씩 5묶음이에요.","3씩 뛰어 세면 3, 6, 9, 12, 15.","꽃은 모두 15송이예요."],"variant_rule":{"mul":{"ask":"total"}},"options":[{"t":"15송이","correct":true},{"t":"8송이","mis":"M2-1-u6-X06"},{"t":"5송이","mis":"M2-1-u6-X05"}],"asset":{"type":"mul_groups","item":"🌷","k":3,"n":5}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_b#3','math',2,1,'u6','','g2_1_math_u6_review_b','unit_review','M2-1-u6-C2',1,'mc','auto','그림을 「몇씩 몇 묶음」으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u6-X04','M2-1-u6-X03']::text[],true,'{"seq":3,"concept":"M2-1-u6-C2","difficulty":1,"kind":"mc","stem":"그림을 「몇씩 몇 묶음」으로 바르게 나타낸 것은 어느 것인가요?","explanation":["한 묶음에 도넛이 6개씩 있어요.","묶음은 모두 2개예요.","그래서 6씩 2묶음이에요 — 「몇씩」은 한 묶음 안의 수, 「몇 묶음」은 묶음의 수예요."],"variant_rule":{"mul":{"ask":"name"}},"options":[{"t":"6씩 2묶음","correct":true},{"t":"2씩 6묶음","mis":"M2-1-u6-X04"},{"t":"6씩 3묶음","mis":"M2-1-u6-X03"}],"asset":{"type":"mul_groups","item":"🍩","k":6,"n":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_b#4','math',2,1,'u6','','g2_1_math_u6_review_b','unit_review','M2-1-u6-C3',1,'mc','auto','그림을 「몇의 몇 배」로 나타내면 어느 것인가요?',ARRAY['M2-1-u6-X07','M2-1-u6-X03']::text[],true,'{"seq":4,"concept":"M2-1-u6-C3","difficulty":1,"kind":"mc","stem":"그림을 「몇의 몇 배」로 나타내면 어느 것인가요?","explanation":["4씩 2묶음이에요.","4씩 2묶음은 4의 2배예요.","「몇의」에는 한 묶음의 수, 「몇 배」에는 묶음의 수를 써요."],"variant_rule":{"mul":{"ask":"times"}},"options":[{"t":"4의 2배","correct":true},{"t":"2의 4배","mis":"M2-1-u6-X07"},{"t":"4의 3배","mis":"M2-1-u6-X03"}],"asset":{"type":"mul_groups","item":"🧁","k":4,"n":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_b#5','math',2,1,'u6','','g2_1_math_u6_review_b','unit_review','M2-1-u6-C3',1,'sa','auto','2의 8배는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M2-1-u6-C3","difficulty":1,"kind":"sa","stem":"2의 8배는 얼마인가요? 숫자로 쓰세요.","explanation":["2의 8배는 2씩 8묶음이에요.","2씩 뛰어 세면 2, 4, 6, 8, 10, 12, 14, 16.","그래서 2의 8배는 16이에요."],"variant_rule":{"mul":{"ask":"tval"}},"answer":["16"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_b#6','math',2,1,'u6','','g2_1_math_u6_review_b','unit_review','M2-1-u6-C4',1,'mc','auto','파랑 막대는 연두 막대를 겹치지 않게 이어 붙인 길이와 같아요. 파랑 막대는 연두 막대의 몇 배인가요?',ARRAY['M2-1-u6-X10','M2-1-u6-X09']::text[],true,'{"seq":6,"concept":"M2-1-u6-C4","difficulty":1,"kind":"mc","stem":"파랑 막대는 연두 막대를 겹치지 않게 이어 붙인 길이와 같아요. 파랑 막대는 연두 막대의 몇 배인가요?","explanation":["연두 막대를 겹치지 않게 이어 붙인 자리를 세어요.","연두 막대가 3번 들어가요.","그래서 파랑 막대는 연두 막대의 3배예요."],"variant_rule":{"mul":{"ask":"bars"}},"options":[{"t":"3배","correct":true},{"t":"4배","mis":"M2-1-u6-X10"},{"t":"6배","mis":"M2-1-u6-X09"}],"asset":{"type":"times_bars","base":2,"times":3,"a":"연두","b":"파랑"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_b#7','math',2,1,'u6','','g2_1_math_u6_review_b','unit_review','M2-1-u6-C5',1,'mc','auto','2 × 9를 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-1-u6-X11']::text[],true,'{"seq":7,"concept":"M2-1-u6-C5","difficulty":1,"kind":"mc","stem":"2 × 9를 바르게 읽은 것은 어느 것인가요?","explanation":["× 는 「곱하기」라고 읽어요.","앞의 수부터 차례로 읽어 「2 곱하기 9」예요.","2 × 9 = 18은 「2 곱하기 9는 18과 같습니다」라고도 읽어요."],"variant_rule":{"mul":{"ask":"read"}},"options":[{"t":"2 곱하기 9","correct":true},{"t":"2 더하기 9","mis":"M2-1-u6-X11"},{"t":"9 곱하기 2","mis":"M2-1-u6-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_b#8','math',2,1,'u6','','g2_1_math_u6_review_b','unit_review','M2-1-u6-C5',1,'sa','auto','5 × 7은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M2-1-u6-C5","difficulty":1,"kind":"sa","stem":"5 × 7은 얼마인가요? 숫자로 쓰세요.","explanation":["5 × 7은 5의 7배예요.","5씩 뛰어 세면 5, 10, 15, 20, 25, 30, 35.","그래서 5 × 7 = 35예요."],"variant_rule":{"mul":{"ask":"value"}},"answer":["35"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_b#9','math',2,1,'u6','','g2_1_math_u6_review_b','unit_review','M2-1-u6-C5',2,'mc','auto','6 + 6 + 6을 곱셈식으로 나타내면 어느 것인가요?',ARRAY['M2-1-u6-X12','M2-1-u6-X11']::text[],true,'{"seq":9,"concept":"M2-1-u6-C5","difficulty":2,"kind":"mc","stem":"6 + 6 + 6을 곱셈식으로 나타내면 어느 것인가요?","explanation":["6이 3번 나와요.","6을 3번 더한 것은 6 × 3이에요.","6 × 3 = 18 — 덧셈식보다 짧게 쓸 수 있어요."],"variant_rule":{"mul":{"ask":"add"}},"options":[{"t":"6 × 3","correct":true},{"t":"6 × 2","mis":"M2-1-u6-X12"},{"t":"6 + 3","mis":"M2-1-u6-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_b#10','math',2,1,'u6','','g2_1_math_u6_review_b','unit_review','M2-1-u6-C6',2,'mc','auto','그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u6-X11','M2-1-u6-X03']::text[],true,'{"seq":10,"concept":"M2-1-u6-C6","difficulty":2,"kind":"mc","stem":"그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["한 줄에 3마리씩 6줄이에요.","3의 6배이니 곱셈식으로 3 × 6이에요.","3 × 6 = 18, 모두 18마리예요."],"variant_rule":{"mul":{"ask":"expr","look":"rows"}},"options":[{"t":"3 × 6","correct":true},{"t":"3 + 6","mis":"M2-1-u6-X11"},{"t":"3 × 7","mis":"M2-1-u6-X03"}],"asset":{"type":"mul_groups","item":"🐜","k":3,"n":6,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_b#11','math',2,1,'u6','','g2_1_math_u6_review_b','unit_review','M2-1-u6-C6',2,'mc','auto','세발자전거 한 대에 바퀴가 3개씩 있어요. 세발자전거 4대의 바퀴는 모두 몇 개인가요?',ARRAY['M2-1-u6-X06','M2-1-u6-X14']::text[],true,'{"seq":11,"concept":"M2-1-u6-C6","difficulty":2,"kind":"mc","stem":"세발자전거 한 대에 바퀴가 3개씩 있어요. 세발자전거 4대의 바퀴는 모두 몇 개인가요?","explanation":["세발자전거 한 대에 3개씩, 4대이면 3씩 4묶음이에요.","3 × 4 = 12예요.","바퀴는 모두 12개예요."],"variant_rule":{"mul":{"ask":"story"}},"options":[{"t":"12개","correct":true},{"t":"7개","mis":"M2-1-u6-X06"},{"t":"4개","mis":"M2-1-u6-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_b#12','math',2,1,'u6','','g2_1_math_u6_review_b','unit_review','M2-1-u6-C6',2,'mc','auto','2 × 9와 곱이 같은 곱셈식은 어느 것인가요?',ARRAY['M2-1-u6-X13']::text[],true,'{"seq":12,"concept":"M2-1-u6-C6","difficulty":2,"kind":"mc","stem":"2 × 9와 곱이 같은 곱셈식은 어느 것인가요?","explanation":["2 × 9는 2씩 9묶음, 9 × 2는 9씩 2묶음이에요.","같은 18개를 가로로 묶느냐 세로로 묶느냐의 차이예요.","그래서 2 × 9와 9 × 2의 곱은 18로 같아요."],"variant_rule":{"mul":{"ask":"same"}},"options":[{"t":"9 × 2","correct":true},{"t":"2 × 2","mis":"M2-1-u6-X13"},{"t":"9 × 9","mis":"M2-1-u6-X13"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_b#13','math',2,1,'u6','','g2_1_math_u6_review_b','unit_review','M2-1-u6-C2',2,'mc','auto','그림의 공을 5개씩 묶으면 몇 묶음인가요?',ARRAY['M2-1-u6-X05','M2-1-u6-X03']::text[],true,'{"seq":13,"concept":"M2-1-u6-C2","difficulty":2,"kind":"mc","stem":"그림의 공을 5개씩 묶으면 몇 묶음인가요?","explanation":["공은 모두 25개예요.","5개씩 묶으면 5, 10, 15, 20, 25 — 5번 묶여요.","그래서 5씩 5묶음이에요."],"variant_rule":{"mul":{"ask":"groups"}},"options":[{"t":"5묶음","correct":true},{"t":"25묶음","mis":"M2-1-u6-X05"},{"t":"6묶음","mis":"M2-1-u6-X03"}],"asset":{"type":"mul_groups","item":"⚽","look":"loose","total":25,"cols":7}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_b#14','math',2,1,'u6','','g2_1_math_u6_review_b','unit_review','M2-1-u6-C4',2,'mc','auto','달걀은 3개, 쿠키는 9개예요. 쿠키의 수는 달걀의 수의 몇 배인가요?',ARRAY['M2-1-u6-X09']::text[],true,'{"seq":14,"concept":"M2-1-u6-C4","difficulty":2,"kind":"mc","stem":"달걀은 3개, 쿠키는 9개예요. 쿠키의 수는 달걀의 수의 몇 배인가요?","explanation":["달걀 3개가 기준이에요.","쿠키 9개를 3개씩 묶으면 3묶음이에요.","그래서 쿠키의 수는 달걀의 수의 3배예요."],"variant_rule":{"mul":{"ask":"cmp"}},"options":[{"t":"3배","correct":true},{"t":"9배","mis":"M2-1-u6-X09"},{"t":"6배","mis":"M2-1-u6-X09"}],"asset":{"type":"times_bars","base":3,"times":3,"a":"달걀","b":"쿠키","item":"🥚","item2":"🍪"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_b#15','math',2,1,'u6','','g2_1_math_u6_review_b','unit_review','M2-1-u6-C3',2,'ox','auto','5씩 2묶음은 2의 5배예요.',ARRAY['M2-1-u6-X07']::text[],false,'{"seq":15,"concept":"M2-1-u6-C3","difficulty":2,"kind":"ox","stem":"5씩 2묶음은 2의 5배예요.","answer":"X","reason_options":[{"t":"「몇의」에는 한 묶음의 수 5가 와서 5의 2배니까","correct":true},{"t":"두 수가 같으면 순서는 상관없으니까","mis":"M2-1-u6-X07"}],"mis":"M2-1-u6-X07","explanation":["한 묶음에 5개씩, 묶음이 2개예요.","그래서 5의 2배예요.","「몇의」와 「몇 배」의 자리를 바꾸면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_b#16','math',2,1,'u6','','g2_1_math_u6_review_b','unit_review','M2-1-u6-C7',2,'match','auto','같은 뜻을 나타내는 것끼리 이으세요.','{}'::text[],false,'{"seq":16,"concept":"M2-1-u6-C7","difficulty":2,"kind":"match","stem":"같은 뜻을 나타내는 것끼리 이으세요.","pairs":[{"l":"5 + 5","r":"5 × 2"},{"l":"2씩 5묶음","r":"2 × 5"},{"l":"5의 3배","r":"5 × 3"}],"mis":"M2-1-u6-X07","explanation":["5 + 5는 5를 2번 더했으니 5 × 2예요.","2씩 5묶음은 2의 5배, 2 × 5예요.","5의 3배는 5 × 3이에요 — 「몇의」 수가 × 앞에 와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_b#17','math',2,1,'u6','','g2_1_math_u6_review_b','unit_review','M2-1-u6-C6',3,'mc','auto','곱이 16인 곱셈식이 아닌 것은 어느 것인가요?',ARRAY['M2-1-u6-X15']::text[],true,'{"seq":17,"concept":"M2-1-u6-C6","difficulty":3,"kind":"mc","stem":"곱이 16인 곱셈식이 아닌 것은 어느 것인가요?","explanation":["5 × 3 = 15예요.","나머지 곱셈식의 곱은 모두 16이에요.","「아닌 것」을 묻는지 다시 읽어요 — 같은 수도 여러 곱셈식으로 나타낼 수 있어요."],"variant_rule":{"mul":{"ask":"notx"}},"options":[{"t":"5 × 3","correct":true},{"t":"4 × 4","mis":"M2-1-u6-X15"},{"t":"8 × 2","mis":"M2-1-u6-X15"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_b#18','math',2,1,'u6','','g2_1_math_u6_review_b','unit_review','M2-1-u6-C3',3,'mc','auto','꽃 20송이를 4송이씩 묶으면 4의 5배예요. 같은 꽃을 5송이씩 묶으면 5의 몇 배인가요?',ARRAY['M2-1-u6-X08','M2-1-u6-X05']::text[],true,'{"seq":18,"concept":"M2-1-u6-C3","difficulty":3,"kind":"mc","stem":"꽃 20송이를 4송이씩 묶으면 4의 5배예요. 같은 꽃을 5송이씩 묶으면 5의 몇 배인가요?","explanation":["5송이씩 묶으면 5, 10, 15, 20 — 4묶음이에요.","그래서 5의 4배예요.","같은 20송이라도 묶는 수가 달라지면 몇 배인지도 달라져요."],"variant_rule":{"mul":{"ask":"regroup"}},"options":[{"t":"4배","correct":true},{"t":"5배","mis":"M2-1-u6-X08"},{"t":"20배","mis":"M2-1-u6-X05"}],"asset":{"type":"mul_groups","item":"🌷","look":"loose","total":20,"cols":6}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_b#19','math',2,1,'u6','','g2_1_math_u6_review_b','unit_review','M2-1-u6-C4',3,'mc','auto','갈색 막대의 길이는 하늘 막대의 길이의 몇 배인가요?',ARRAY['M2-1-u6-X10','M2-1-u6-X09']::text[],true,'{"seq":19,"concept":"M2-1-u6-C4","difficulty":3,"kind":"mc","stem":"갈색 막대의 길이는 하늘 막대의 길이의 몇 배인가요?","explanation":["하늘 막대는 3칸, 갈색 막대는 9칸이에요.","3칸씩 묶으면 갈색 막대는 3묶음이에요.","그래서 갈색 막대는 하늘 막대의 3배예요 — 칸 수를 그대로 배로 말하면 안 돼요."],"variant_rule":{"mul":{"ask":"bars","grid":true}},"options":[{"t":"3배","correct":true},{"t":"4배","mis":"M2-1-u6-X10"},{"t":"9배","mis":"M2-1-u6-X09"}],"asset":{"type":"times_bars","base":3,"times":3,"a":"하늘","b":"갈색","grid":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_b#20','math',2,1,'u6','','g2_1_math_u6_review_b','unit_review','M2-1-u6-C7',3,'mc','auto','곱셈 카드 「3 × 4」와 같은 뜻이 아닌 것은 어느 것인가요?',ARRAY['M2-1-u6-X15']::text[],false,'{"seq":20,"concept":"M2-1-u6-C7","difficulty":3,"kind":"mc","stem":"곱셈 카드 「3 × 4」와 같은 뜻이 아닌 것은 어느 것인가요?","options":[{"t":"3씩 3묶음","correct":true},{"t":"3 + 3 + 3 + 3","mis":"M2-1-u6-X15"},{"t":"3씩 4묶음","mis":"M2-1-u6-X15"},{"t":"3의 4배","mis":"M2-1-u6-X15"}],"explanation":["3 × 4는 3씩 4묶음, 3의 4배예요.","3 + 3 + 3 + 3도 3을 4번 더한 것이라 같은 뜻이에요.","3씩 3묶음은 9라 달라요 — 「아닌 것」을 물었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_b#21','math',2,1,'u6','','g2_1_math_u6_review_b','unit_review','M2-1-u6-C6',3,'mc','auto','네잎클로버 한 개에 잎이 4장씩 있어요. 네잎클로버 5개의 잎 수를 구하는 곱셈식은 어느 것인가요?',ARRAY['M2-1-u6-X11','M2-1-u6-X14']::text[],true,'{"seq":21,"concept":"M2-1-u6-C6","difficulty":3,"kind":"mc","stem":"네잎클로버 한 개에 잎이 4장씩 있어요. 네잎클로버 5개의 잎 수를 구하는 곱셈식은 어느 것인가요?","explanation":["한 개에 4장씩 — 한 묶음은 4예요.","네잎클로버가 5개이니 4씩 5묶음, 4의 5배예요.","곱셈식은 4 × 5 = 20이에요."],"variant_rule":{"mul":{"ask":"sexpr"}},"options":[{"t":"4 × 5","correct":true},{"t":"4 + 5","mis":"M2-1-u6-X11"},{"t":"4 × 4","mis":"M2-1-u6-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_b#22','math',2,1,'u6','','g2_1_math_u6_review_b','unit_review','M2-1-u6-C5',3,'error','auto','친구들이 곱셈에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u6-X12','M2-1-u6-X15']::text[],false,'{"seq":22,"concept":"M2-1-u6-C5","difficulty":3,"kind":"error","stem":"친구들이 곱셈에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지우 — 「4 + 4 + 4는 4 × 2야. 더하기가 2개니까.」","correct":true,"mis_target":"M2-1-u6-X12"},{"t":"서아 — 「4 + 4 + 4는 4 × 3이야.」","mis":"M2-1-u6-X15"},{"t":"하루 — 「4 × 3은 12야.」","mis":"M2-1-u6-X15"}],"explanation":["4가 3번 나오니 4 × 3이에요.","지우는 더하기 기호의 수를 셌어요.","서아와 하루는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_b#23','math',2,1,'u6','','g2_1_math_u6_review_b','unit_review','M2-1-u6-C7',4,'essay','teacher','그림을 보고 곱셈 카드를 만들려고 해요. 그림을 덧셈식, 「몇씩 몇 묶음」, 「몇의 몇 배」, 곱셈식으로 각각 나타내고 모두 몇인지 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-1-u6-C7","difficulty":4,"kind":"essay","stem":"그림을 보고 곱셈 카드를 만들려고 해요. 그림을 덧셈식, 「몇씩 몇 묶음」, 「몇의 몇 배」, 곱셈식으로 각각 나타내고 모두 몇인지 써 보세요.","answer_guide":{"answer":"예: 5 + 5 = 10, 5씩 2묶음, 5의 2배, 5 × 2 = 10. 토마토는 모두 10개이다.","scoring_points":["덧셈식을 바르게 썼는가","「몇씩 몇 묶음」과 「몇의 몇 배」를 바르게 썼는가","곱셈식과 답을 바르게 썼는가"]},"explanation":["한 묶음의 수와 묶음의 수를 먼저 찾아요.","같은 그림을 여러 가지로 나타낼 수 있어요.","모두 같은 수를 나타내요."],"asset":{"type":"mul_groups","item":"🍅","k":5,"n":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_b#24','math',2,1,'u6','','g2_1_math_u6_review_b','unit_review','M2-1-u6-C6',4,'essay','teacher','그림의 쿠키를 두 가지 곱셈식으로 나타내고, 두 곱셈식의 곱이 같은 까닭을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-1-u6-C6","difficulty":4,"kind":"essay","stem":"그림의 쿠키를 두 가지 곱셈식으로 나타내고, 두 곱셈식의 곱이 같은 까닭을 써 보세요.","answer_guide":{"answer":"예: 한 줄에 6개씩 3줄이므로 6 × 3 = 18, 세로로 3개씩 6줄이므로 3 × 6 = 18. 같은 쿠키를 묶는 방법만 바꾸었으므로 곱이 같다.","scoring_points":["가로로 묶은 곱셈식과 곱을 썼는가","세로로 묶은 곱셈식과 곱을 썼는가","같은 물건을 다르게 묶었을 뿐이라 곱이 같다고 썼는가"]},"explanation":["가로로 한 줄씩 묶어 보아요.","세로로 한 줄씩 묶어 보아요.","묶는 방법만 다르고 물건의 수는 같아요."],"asset":{"type":"mul_groups","item":"🍪","k":6,"n":3,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_b#25','math',2,1,'u6','','g2_1_math_u6_review_b','unit_review','M2-1-u6-C4',4,'essay','teacher','연우는 구슬을 4개, 민준이는 구슬을 20개 가지고 있어요. 민준이의 구슬 수는 연우의 구슬 수의 몇 배인지 구하고, 어떻게 구했는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-1-u6-C4","difficulty":4,"kind":"essay","stem":"연우는 구슬을 4개, 민준이는 구슬을 20개 가지고 있어요. 민준이의 구슬 수는 연우의 구슬 수의 몇 배인지 구하고, 어떻게 구했는지 설명해 보세요.","answer_guide":{"answer":"예: 기준은 연우의 구슬 4개이다. 20을 4씩 묶으면 4, 8, 12, 16, 20으로 5묶음이므로 5배이다.","scoring_points":["기준이 무엇인지 바르게 찾았는가","기준만큼씩 묶거나 이어 붙인 횟수를 셌는가","몇 배인지 바르게 답했는가"]},"explanation":["견줄 때 바탕이 되는 기준을 먼저 찾아요.","기준만큼씩 묶거나 겹치지 않게 이어 붙여 세어요.","센 횟수가 몇 배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_c#1','math',2,1,'u6','','g2_1_math_u6_review_c','unit_review','M2-1-u6-C1',1,'sa','auto','3씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-1-u6-C1","difficulty":1,"kind":"sa","stem":"3씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["3씩 커지는 수예요.","15에서 3만큼 더 뛰면 18이에요.","3씩 6번 뛰어 센 수 — 3씩 6묶음과 같아요."],"variant_rule":{"mul":{"ask":"skip"}},"answer":["18"],"asset":{"type":"jump_row","cells":[3,6,9,12,15,null],"step":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_c#2','math',2,1,'u6','','g2_1_math_u6_review_c','unit_review','M2-1-u6-C2',1,'mc','auto','그림을 보세요. 사과는 모두 몇 개인가요?',ARRAY['M2-1-u6-X06','M2-1-u6-X05']::text[],true,'{"seq":2,"concept":"M2-1-u6-C2","difficulty":1,"kind":"mc","stem":"그림을 보세요. 사과는 모두 몇 개인가요?","explanation":["4개씩 4묶음이에요.","4씩 뛰어 세면 4, 8, 12, 16.","사과는 모두 16개예요."],"variant_rule":{"mul":{"ask":"total"}},"options":[{"t":"16개","correct":true},{"t":"8개","mis":"M2-1-u6-X06"},{"t":"4개","mis":"M2-1-u6-X05"}],"asset":{"type":"mul_groups","item":"🍎","k":4,"n":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_c#3','math',2,1,'u6','','g2_1_math_u6_review_c','unit_review','M2-1-u6-C2',1,'mc','auto','그림을 「몇씩 몇 묶음」으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u6-X04','M2-1-u6-X03']::text[],true,'{"seq":3,"concept":"M2-1-u6-C2","difficulty":1,"kind":"mc","stem":"그림을 「몇씩 몇 묶음」으로 바르게 나타낸 것은 어느 것인가요?","explanation":["한 묶음에 나비가 2마리씩 있어요.","묶음은 모두 7개예요.","그래서 2씩 7묶음이에요 — 「몇씩」은 한 묶음 안의 수, 「몇 묶음」은 묶음의 수예요."],"variant_rule":{"mul":{"ask":"name"}},"options":[{"t":"2씩 7묶음","correct":true},{"t":"7씩 2묶음","mis":"M2-1-u6-X04"},{"t":"2씩 8묶음","mis":"M2-1-u6-X03"}],"asset":{"type":"mul_groups","item":"🦋","k":2,"n":7}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_c#4','math',2,1,'u6','','g2_1_math_u6_review_c','unit_review','M2-1-u6-C3',1,'mc','auto','그림을 「몇의 몇 배」로 나타내면 어느 것인가요?',ARRAY['M2-1-u6-X07','M2-1-u6-X03']::text[],true,'{"seq":4,"concept":"M2-1-u6-C3","difficulty":1,"kind":"mc","stem":"그림을 「몇의 몇 배」로 나타내면 어느 것인가요?","explanation":["3씩 5묶음이에요.","3씩 5묶음은 3의 5배예요.","「몇의」에는 한 묶음의 수, 「몇 배」에는 묶음의 수를 써요."],"variant_rule":{"mul":{"ask":"times"}},"options":[{"t":"3의 5배","correct":true},{"t":"5의 3배","mis":"M2-1-u6-X07"},{"t":"3의 6배","mis":"M2-1-u6-X03"}],"asset":{"type":"mul_groups","item":"🐞","k":3,"n":5}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_c#5','math',2,1,'u6','','g2_1_math_u6_review_c','unit_review','M2-1-u6-C3',1,'sa','auto','5의 5배는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M2-1-u6-C3","difficulty":1,"kind":"sa","stem":"5의 5배는 얼마인가요? 숫자로 쓰세요.","explanation":["5의 5배는 5씩 5묶음이에요.","5씩 뛰어 세면 5, 10, 15, 20, 25.","그래서 5의 5배는 25예요."],"variant_rule":{"mul":{"ask":"tval"}},"answer":["25"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_c#6','math',2,1,'u6','','g2_1_math_u6_review_c','unit_review','M2-1-u6-C4',1,'mc','auto','보라 막대는 노랑 막대를 겹치지 않게 이어 붙인 길이와 같아요. 보라 막대는 노랑 막대의 몇 배인가요?',ARRAY['M2-1-u6-X10','M2-1-u6-X09']::text[],true,'{"seq":6,"concept":"M2-1-u6-C4","difficulty":1,"kind":"mc","stem":"보라 막대는 노랑 막대를 겹치지 않게 이어 붙인 길이와 같아요. 보라 막대는 노랑 막대의 몇 배인가요?","explanation":["노랑 막대를 겹치지 않게 이어 붙인 자리를 세어요.","노랑 막대가 2번 들어가요.","그래서 보라 막대는 노랑 막대의 2배예요."],"variant_rule":{"mul":{"ask":"bars"}},"options":[{"t":"2배","correct":true},{"t":"3배","mis":"M2-1-u6-X10"},{"t":"6배","mis":"M2-1-u6-X09"}],"asset":{"type":"times_bars","base":3,"times":2,"a":"노랑","b":"보라"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_c#7','math',2,1,'u6','','g2_1_math_u6_review_c','unit_review','M2-1-u6-C5',1,'mc','auto','5 × 7을 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-1-u6-X11']::text[],true,'{"seq":7,"concept":"M2-1-u6-C5","difficulty":1,"kind":"mc","stem":"5 × 7을 바르게 읽은 것은 어느 것인가요?","explanation":["× 는 「곱하기」라고 읽어요.","앞의 수부터 차례로 읽어 「5 곱하기 7」이에요.","5 × 7 = 35는 「5 곱하기 7은 35와 같습니다」라고도 읽어요."],"variant_rule":{"mul":{"ask":"read"}},"options":[{"t":"5 곱하기 7","correct":true},{"t":"5 더하기 7","mis":"M2-1-u6-X11"},{"t":"7 곱하기 5","mis":"M2-1-u6-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_c#8','math',2,1,'u6','','g2_1_math_u6_review_c','unit_review','M2-1-u6-C5',1,'sa','auto','2 × 6은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M2-1-u6-C5","difficulty":1,"kind":"sa","stem":"2 × 6은 얼마인가요? 숫자로 쓰세요.","explanation":["2 × 6은 2의 6배예요.","2씩 뛰어 세면 2, 4, 6, 8, 10, 12.","그래서 2 × 6 = 12예요."],"variant_rule":{"mul":{"ask":"value"}},"answer":["12"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_c#9','math',2,1,'u6','','g2_1_math_u6_review_c','unit_review','M2-1-u6-C5',2,'mc','auto','3 + 3 + 3 + 3 + 3을 곱셈식으로 나타내면 어느 것인가요?',ARRAY['M2-1-u6-X12','M2-1-u6-X11']::text[],true,'{"seq":9,"concept":"M2-1-u6-C5","difficulty":2,"kind":"mc","stem":"3 + 3 + 3 + 3 + 3을 곱셈식으로 나타내면 어느 것인가요?","explanation":["3이 5번 나와요.","3을 5번 더한 것은 3 × 5예요.","3 × 5 = 15 — 덧셈식보다 짧게 쓸 수 있어요."],"variant_rule":{"mul":{"ask":"add"}},"options":[{"t":"3 × 5","correct":true},{"t":"3 × 4","mis":"M2-1-u6-X12"},{"t":"3 + 5","mis":"M2-1-u6-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_c#10','math',2,1,'u6','','g2_1_math_u6_review_c','unit_review','M2-1-u6-C6',2,'mc','auto','그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u6-X11','M2-1-u6-X03']::text[],true,'{"seq":10,"concept":"M2-1-u6-C6","difficulty":2,"kind":"mc","stem":"그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["한 줄에 7개씩 3줄이에요.","7의 3배이니 곱셈식으로 7 × 3이에요.","7 × 3 = 21, 모두 21개예요."],"variant_rule":{"mul":{"ask":"expr","look":"rows"}},"options":[{"t":"7 × 3","correct":true},{"t":"7 + 3","mis":"M2-1-u6-X11"},{"t":"7 × 4","mis":"M2-1-u6-X03"}],"asset":{"type":"mul_groups","item":"⭐","k":7,"n":3,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_c#11','math',2,1,'u6','','g2_1_math_u6_review_c','unit_review','M2-1-u6-C6',2,'mc','auto','오리 한 마리에 다리가 2개씩 있어요. 오리 6마리의 다리는 모두 몇 개인가요?',ARRAY['M2-1-u6-X06','M2-1-u6-X14']::text[],true,'{"seq":11,"concept":"M2-1-u6-C6","difficulty":2,"kind":"mc","stem":"오리 한 마리에 다리가 2개씩 있어요. 오리 6마리의 다리는 모두 몇 개인가요?","explanation":["오리 한 마리에 2개씩, 6마리이면 2씩 6묶음이에요.","2 × 6 = 12예요.","다리는 모두 12개예요."],"variant_rule":{"mul":{"ask":"story"}},"options":[{"t":"12개","correct":true},{"t":"8개","mis":"M2-1-u6-X06"},{"t":"6개","mis":"M2-1-u6-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_c#12','math',2,1,'u6','','g2_1_math_u6_review_c','unit_review','M2-1-u6-C6',2,'mc','auto','4 × 6과 곱이 같은 곱셈식은 어느 것인가요?',ARRAY['M2-1-u6-X13']::text[],true,'{"seq":12,"concept":"M2-1-u6-C6","difficulty":2,"kind":"mc","stem":"4 × 6과 곱이 같은 곱셈식은 어느 것인가요?","explanation":["4 × 6은 4씩 6묶음, 6 × 4는 6씩 4묶음이에요.","같은 24개를 가로로 묶느냐 세로로 묶느냐의 차이예요.","그래서 4 × 6과 6 × 4의 곱은 24로 같아요."],"variant_rule":{"mul":{"ask":"same"}},"options":[{"t":"6 × 4","correct":true},{"t":"4 × 4","mis":"M2-1-u6-X13"},{"t":"6 × 6","mis":"M2-1-u6-X13"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_c#13','math',2,1,'u6','','g2_1_math_u6_review_c','unit_review','M2-1-u6-C2',2,'mc','auto','그림의 사탕을 4개씩 묶으면 몇 묶음인가요?',ARRAY['M2-1-u6-X04','M2-1-u6-X05']::text[],true,'{"seq":13,"concept":"M2-1-u6-C2","difficulty":2,"kind":"mc","stem":"그림의 사탕을 4개씩 묶으면 몇 묶음인가요?","explanation":["사탕은 모두 28개예요.","4개씩 묶으면 4, 8, 12, 16, 20, 24, 28 — 7번 묶여요.","그래서 4씩 7묶음이에요."],"variant_rule":{"mul":{"ask":"groups"}},"options":[{"t":"7묶음","correct":true},{"t":"4묶음","mis":"M2-1-u6-X04"},{"t":"28묶음","mis":"M2-1-u6-X05"}],"asset":{"type":"mul_groups","item":"🍬","look":"loose","total":28,"cols":6}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_c#14','math',2,1,'u6','','g2_1_math_u6_review_c','unit_review','M2-1-u6-C4',2,'mc','auto','도넛은 5개, 컵케이크는 10개예요. 컵케이크의 수는 도넛의 수의 몇 배인가요?',ARRAY['M2-1-u6-X09']::text[],true,'{"seq":14,"concept":"M2-1-u6-C4","difficulty":2,"kind":"mc","stem":"도넛은 5개, 컵케이크는 10개예요. 컵케이크의 수는 도넛의 수의 몇 배인가요?","explanation":["도넛 5개가 기준이에요.","컵케이크 10개를 5개씩 묶으면 2묶음이에요.","그래서 컵케이크의 수는 도넛의 수의 2배예요."],"variant_rule":{"mul":{"ask":"cmp"}},"options":[{"t":"2배","correct":true},{"t":"10배","mis":"M2-1-u6-X09"},{"t":"5배","mis":"M2-1-u6-X09"}],"asset":{"type":"times_bars","base":5,"times":2,"a":"도넛","b":"컵케이크","item":"🍩","item2":"🧁"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_c#15','math',2,1,'u6','','g2_1_math_u6_review_c','unit_review','M2-1-u6-C3',2,'ox','auto','같은 12개를 2씩 묶으면 2의 6배, 6씩 묶으면 6의 2배예요.',ARRAY['M2-1-u6-X08']::text[],false,'{"seq":15,"concept":"M2-1-u6-C3","difficulty":2,"kind":"ox","stem":"같은 12개를 2씩 묶으면 2의 6배, 6씩 묶으면 6의 2배예요.","answer":"O","reason_options":[{"t":"2씩 묶으면 6묶음, 6씩 묶으면 2묶음이니까","correct":true},{"t":"묶는 수가 달라도 몇 배는 같으니까","mis":"M2-1-u6-X08"}],"mis":"M2-1-u6-X08","explanation":["2, 4, 6, 8, 10, 12로 2씩 6묶음이에요.","6, 12로 6씩 2묶음이에요.","묶는 수가 달라지면 몇 배도 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_c#16','math',2,1,'u6','','g2_1_math_u6_review_c','unit_review','M2-1-u6-C7',2,'match','auto','같은 뜻을 나타내는 것끼리 이으세요.','{}'::text[],false,'{"seq":16,"concept":"M2-1-u6-C7","difficulty":2,"kind":"match","stem":"같은 뜻을 나타내는 것끼리 이으세요.","pairs":[{"l":"4 + 4 + 4","r":"4 × 3"},{"l":"3씩 4묶음","r":"3 × 4"},{"l":"4의 2배","r":"4 × 2"}],"mis":"M2-1-u6-X07","explanation":["4 + 4 + 4는 4를 3번 더했으니 4 × 3이에요.","3씩 4묶음은 3의 4배, 3 × 4예요.","4의 2배는 4 × 2예요 — 「몇의」 수가 × 앞에 와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_c#17','math',2,1,'u6','','g2_1_math_u6_review_c','unit_review','M2-1-u6-C6',3,'mc','auto','곱이 20인 곱셈식이 아닌 것은 어느 것인가요?',ARRAY['M2-1-u6-X15']::text[],true,'{"seq":17,"concept":"M2-1-u6-C6","difficulty":3,"kind":"mc","stem":"곱이 20인 곱셈식이 아닌 것은 어느 것인가요?","explanation":["3 × 7 = 21이에요.","나머지 곱셈식의 곱은 모두 20이에요.","「아닌 것」을 묻는지 다시 읽어요 — 같은 수도 여러 곱셈식으로 나타낼 수 있어요."],"variant_rule":{"mul":{"ask":"notx"}},"options":[{"t":"3 × 7","correct":true},{"t":"5 × 4","mis":"M2-1-u6-X15"},{"t":"4 × 5","mis":"M2-1-u6-X15"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_c#18','math',2,1,'u6','','g2_1_math_u6_review_c','unit_review','M2-1-u6-C3',3,'mc','auto','별 16개를 8개씩 묶으면 8의 2배예요. 같은 별을 2개씩 묶으면 2의 몇 배인가요?',ARRAY['M2-1-u6-X08','M2-1-u6-X05']::text[],true,'{"seq":18,"concept":"M2-1-u6-C3","difficulty":3,"kind":"mc","stem":"별 16개를 8개씩 묶으면 8의 2배예요. 같은 별을 2개씩 묶으면 2의 몇 배인가요?","explanation":["2개씩 묶으면 2, 4, 6, 8, 10, 12, 14, 16 — 8묶음이에요.","그래서 2의 8배예요.","같은 16개라도 묶는 수가 달라지면 몇 배인지도 달라져요."],"variant_rule":{"mul":{"ask":"regroup"}},"options":[{"t":"8배","correct":true},{"t":"2배","mis":"M2-1-u6-X08"},{"t":"16배","mis":"M2-1-u6-X05"}],"asset":{"type":"mul_groups","item":"⭐","look":"loose","total":16,"cols":6}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_c#19','math',2,1,'u6','','g2_1_math_u6_review_c','unit_review','M2-1-u6-C4',3,'mc','auto','파랑 막대의 길이는 노랑 막대의 길이의 몇 배인가요?',ARRAY['M2-1-u6-X10','M2-1-u6-X09']::text[],true,'{"seq":19,"concept":"M2-1-u6-C4","difficulty":3,"kind":"mc","stem":"파랑 막대의 길이는 노랑 막대의 길이의 몇 배인가요?","explanation":["노랑 막대는 2칸, 파랑 막대는 12칸이에요.","2칸씩 묶으면 파랑 막대는 6묶음이에요.","그래서 파랑 막대는 노랑 막대의 6배예요 — 칸 수를 그대로 배로 말하면 안 돼요."],"variant_rule":{"mul":{"ask":"bars","grid":true}},"options":[{"t":"6배","correct":true},{"t":"7배","mis":"M2-1-u6-X10"},{"t":"12배","mis":"M2-1-u6-X09"}],"asset":{"type":"times_bars","base":2,"times":6,"a":"노랑","b":"파랑","grid":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_c#20','math',2,1,'u6','','g2_1_math_u6_review_c','unit_review','M2-1-u6-C7',3,'mc','auto','곱셈 카드 「6 × 3」과 같은 뜻이 아닌 것은 어느 것인가요?',ARRAY['M2-1-u6-X15']::text[],false,'{"seq":20,"concept":"M2-1-u6-C7","difficulty":3,"kind":"mc","stem":"곱셈 카드 「6 × 3」과 같은 뜻이 아닌 것은 어느 것인가요?","options":[{"t":"6 + 3","correct":true},{"t":"6 + 6 + 6","mis":"M2-1-u6-X15"},{"t":"6씩 3묶음","mis":"M2-1-u6-X15"},{"t":"6의 3배","mis":"M2-1-u6-X15"}],"explanation":["6 × 3은 6을 3번 더한 것이에요.","6 + 6 + 6, 6씩 3묶음, 6의 3배는 모두 같은 뜻이에요.","6 + 3은 9라 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_c#21','math',2,1,'u6','','g2_1_math_u6_review_c','unit_review','M2-1-u6-C6',3,'mc','auto','개미 한 마리에 다리가 6개씩 있어요. 개미 3마리의 다리 수를 구하는 곱셈식은 어느 것인가요?',ARRAY['M2-1-u6-X11','M2-1-u6-X14']::text[],true,'{"seq":21,"concept":"M2-1-u6-C6","difficulty":3,"kind":"mc","stem":"개미 한 마리에 다리가 6개씩 있어요. 개미 3마리의 다리 수를 구하는 곱셈식은 어느 것인가요?","explanation":["한 마리에 6개씩 — 한 묶음은 6이에요.","개미가 3마리이니 6씩 3묶음, 6의 3배예요.","곱셈식은 6 × 3 = 18이에요."],"variant_rule":{"mul":{"ask":"sexpr"}},"options":[{"t":"6 × 3","correct":true},{"t":"6 + 3","mis":"M2-1-u6-X11"},{"t":"6 × 6","mis":"M2-1-u6-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_c#22','math',2,1,'u6','','g2_1_math_u6_review_c','unit_review','M2-1-u6-C5',3,'error','auto','친구들이 곱셈에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u6-X11','M2-1-u6-X15']::text[],false,'{"seq":22,"concept":"M2-1-u6-C5","difficulty":3,"kind":"error","stem":"친구들이 곱셈에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「7 × 3은 7 더하기 3이라고 읽어.」","correct":true,"mis_target":"M2-1-u6-X11"},{"t":"은솔 — 「7과 3의 곱은 21이야.」","mis":"M2-1-u6-X15"},{"t":"예린 — 「7 × 3은 7씩 3묶음이야.」","mis":"M2-1-u6-X15"}],"explanation":["× 는 「곱하기」라고 읽어요.","도윤이의 말이 틀렸어요.","7 × 3 = 21이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_c#23','math',2,1,'u6','','g2_1_math_u6_review_c','unit_review','M2-1-u6-C7',4,'essay','teacher','그림을 보고 곱셈 카드를 만들려고 해요. 그림을 덧셈식, 「몇씩 몇 묶음」, 「몇의 몇 배」, 곱셈식으로 각각 나타내고 모두 몇인지 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-1-u6-C7","difficulty":4,"kind":"essay","stem":"그림을 보고 곱셈 카드를 만들려고 해요. 그림을 덧셈식, 「몇씩 몇 묶음」, 「몇의 몇 배」, 곱셈식으로 각각 나타내고 모두 몇인지 써 보세요.","answer_guide":{"answer":"예: 4 + 4 + 4 = 12, 4씩 3묶음, 4의 3배, 4 × 3 = 12. 나비는 모두 12마리이다.","scoring_points":["덧셈식을 바르게 썼는가","「몇씩 몇 묶음」과 「몇의 몇 배」를 바르게 썼는가","곱셈식과 답을 바르게 썼는가"]},"explanation":["한 묶음의 수와 묶음의 수를 먼저 찾아요.","같은 그림을 여러 가지로 나타낼 수 있어요.","모두 같은 수를 나타내요."],"asset":{"type":"mul_groups","item":"🦋","k":4,"n":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_c#24','math',2,1,'u6','','g2_1_math_u6_review_c','unit_review','M2-1-u6-C6',4,'essay','teacher','그림의 꽃을 두 가지 곱셈식으로 나타내고, 두 곱셈식의 곱이 같은 까닭을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-1-u6-C6","difficulty":4,"kind":"essay","stem":"그림의 꽃을 두 가지 곱셈식으로 나타내고, 두 곱셈식의 곱이 같은 까닭을 써 보세요.","answer_guide":{"answer":"예: 한 줄에 7송이씩 2줄이므로 7 × 2 = 14, 세로로 2송이씩 7줄이므로 2 × 7 = 14. 같은 꽃을 묶는 방법만 바꾸었으므로 곱이 같다.","scoring_points":["가로로 묶은 곱셈식과 곱을 썼는가","세로로 묶은 곱셈식과 곱을 썼는가","같은 물건을 다르게 묶었을 뿐이라 곱이 같다고 썼는가"]},"explanation":["가로로 한 줄씩 묶어 보아요.","세로로 한 줄씩 묶어 보아요.","묶는 방법만 다르고 물건의 수는 같아요."],"asset":{"type":"mul_groups","item":"🌷","k":7,"n":2,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_c#25','math',2,1,'u6','','g2_1_math_u6_review_c','unit_review','M2-1-u6-C4',4,'essay','teacher','그림에서 초록 막대는 빨강 막대의 몇 배인지 구하고, 어떻게 구했는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-1-u6-C4","difficulty":4,"kind":"essay","stem":"그림에서 초록 막대는 빨강 막대의 몇 배인지 구하고, 어떻게 구했는지 설명해 보세요.","answer_guide":{"answer":"예: 빨강 막대는 2칸, 초록 막대는 10칸이다. 빨강 막대를 겹치지 않게 이어 붙이면 5번 들어가므로 초록 막대는 빨강 막대의 5배이다.","scoring_points":["기준이 무엇인지 바르게 찾았는가","기준만큼씩 묶거나 이어 붙인 횟수를 셌는가","몇 배인지 바르게 답했는가"]},"explanation":["견줄 때 바탕이 되는 기준을 먼저 찾아요.","기준만큼씩 묶거나 겹치지 않게 이어 붙여 세어요.","센 횟수가 몇 배예요."],"asset":{"type":"times_bars","base":2,"times":5,"a":"빨강","b":"초록","grid":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_d#1','math',2,1,'u6','','g2_1_math_u6_review_d','unit_review','M2-1-u6-C1',1,'sa','auto','4씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-1-u6-C1","difficulty":1,"kind":"sa","stem":"4씩 뛰어 세었어요. ?에 알맞은 수는 얼마인가요? 숫자로 쓰세요.","explanation":["4씩 커지는 수예요.","12에서 4만큼 더 뛰면 16이에요.","4씩 4번 뛰어 센 수 — 4씩 4묶음과 같아요."],"variant_rule":{"mul":{"ask":"skip"}},"answer":["16"],"asset":{"type":"jump_row","cells":[4,8,12,null],"step":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_d#2','math',2,1,'u6','','g2_1_math_u6_review_d','unit_review','M2-1-u6-C2',1,'mc','auto','그림을 보세요. 물고기는 모두 몇 마리인가요?',ARRAY['M2-1-u6-X06','M2-1-u6-X05']::text[],true,'{"seq":2,"concept":"M2-1-u6-C2","difficulty":1,"kind":"mc","stem":"그림을 보세요. 물고기는 모두 몇 마리인가요?","explanation":["5마리씩 2묶음이에요.","5씩 뛰어 세면 5, 10.","물고기는 모두 10마리예요."],"variant_rule":{"mul":{"ask":"total"}},"options":[{"t":"10마리","correct":true},{"t":"7마리","mis":"M2-1-u6-X06"},{"t":"2마리","mis":"M2-1-u6-X05"}],"asset":{"type":"mul_groups","item":"🐟","k":5,"n":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_d#3','math',2,1,'u6','','g2_1_math_u6_review_d','unit_review','M2-1-u6-C2',1,'mc','auto','그림을 「몇씩 몇 묶음」으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u6-X04','M2-1-u6-X03']::text[],true,'{"seq":3,"concept":"M2-1-u6-C2","difficulty":1,"kind":"mc","stem":"그림을 「몇씩 몇 묶음」으로 바르게 나타낸 것은 어느 것인가요?","explanation":["한 묶음에 당근이 4개씩 있어요.","묶음은 모두 5개예요.","그래서 4씩 5묶음이에요 — 「몇씩」은 한 묶음 안의 수, 「몇 묶음」은 묶음의 수예요."],"variant_rule":{"mul":{"ask":"name"}},"options":[{"t":"4씩 5묶음","correct":true},{"t":"5씩 4묶음","mis":"M2-1-u6-X04"},{"t":"4씩 6묶음","mis":"M2-1-u6-X03"}],"asset":{"type":"mul_groups","item":"🥕","k":4,"n":5}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_d#4','math',2,1,'u6','','g2_1_math_u6_review_d','unit_review','M2-1-u6-C3',1,'mc','auto','그림을 「몇의 몇 배」로 나타내면 어느 것인가요?',ARRAY['M2-1-u6-X07','M2-1-u6-X03']::text[],true,'{"seq":4,"concept":"M2-1-u6-C3","difficulty":1,"kind":"mc","stem":"그림을 「몇의 몇 배」로 나타내면 어느 것인가요?","explanation":["5씩 4묶음이에요.","5씩 4묶음은 5의 4배예요.","「몇의」에는 한 묶음의 수, 「몇 배」에는 묶음의 수를 써요."],"variant_rule":{"mul":{"ask":"times"}},"options":[{"t":"5의 4배","correct":true},{"t":"4의 5배","mis":"M2-1-u6-X07"},{"t":"5의 5배","mis":"M2-1-u6-X03"}],"asset":{"type":"mul_groups","item":"🍅","k":5,"n":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_d#5','math',2,1,'u6','','g2_1_math_u6_review_d','unit_review','M2-1-u6-C3',1,'sa','auto','3의 7배는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M2-1-u6-C3","difficulty":1,"kind":"sa","stem":"3의 7배는 얼마인가요? 숫자로 쓰세요.","explanation":["3의 7배는 3씩 7묶음이에요.","3씩 뛰어 세면 3, 6, 9, 12, 15, 18, 21.","그래서 3의 7배는 21이에요."],"variant_rule":{"mul":{"ask":"tval"}},"answer":["21"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_d#6','math',2,1,'u6','','g2_1_math_u6_review_d','unit_review','M2-1-u6-C4',1,'mc','auto','초록 막대는 분홍 막대를 겹치지 않게 이어 붙인 길이와 같아요. 초록 막대는 분홍 막대의 몇 배인가요?',ARRAY['M2-1-u6-X10']::text[],true,'{"seq":6,"concept":"M2-1-u6-C4","difficulty":1,"kind":"mc","stem":"초록 막대는 분홍 막대를 겹치지 않게 이어 붙인 길이와 같아요. 초록 막대는 분홍 막대의 몇 배인가요?","explanation":["분홍 막대를 겹치지 않게 이어 붙인 자리를 세어요.","분홍 막대가 6번 들어가요.","그래서 초록 막대는 분홍 막대의 6배예요."],"variant_rule":{"mul":{"ask":"bars"}},"options":[{"t":"6배","correct":true},{"t":"7배","mis":"M2-1-u6-X10"},{"t":"5배","mis":"M2-1-u6-X10"}],"asset":{"type":"times_bars","base":1,"times":6,"a":"분홍","b":"초록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_d#7','math',2,1,'u6','','g2_1_math_u6_review_d','unit_review','M2-1-u6-C5',1,'mc','auto','8 × 2를 바르게 읽은 것은 어느 것인가요?',ARRAY['M2-1-u6-X11']::text[],true,'{"seq":7,"concept":"M2-1-u6-C5","difficulty":1,"kind":"mc","stem":"8 × 2를 바르게 읽은 것은 어느 것인가요?","explanation":["× 는 「곱하기」라고 읽어요.","앞의 수부터 차례로 읽어 「8 곱하기 2」예요.","8 × 2 = 16은 「8 곱하기 2는 16과 같습니다」라고도 읽어요."],"variant_rule":{"mul":{"ask":"read"}},"options":[{"t":"8 곱하기 2","correct":true},{"t":"8 더하기 2","mis":"M2-1-u6-X11"},{"t":"2 곱하기 8","mis":"M2-1-u6-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_d#8','math',2,1,'u6','','g2_1_math_u6_review_d','unit_review','M2-1-u6-C5',1,'sa','auto','3 × 5는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M2-1-u6-C5","difficulty":1,"kind":"sa","stem":"3 × 5는 얼마인가요? 숫자로 쓰세요.","explanation":["3 × 5는 3의 5배예요.","3씩 뛰어 세면 3, 6, 9, 12, 15.","그래서 3 × 5 = 15예요."],"variant_rule":{"mul":{"ask":"value"}},"answer":["15"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_d#9','math',2,1,'u6','','g2_1_math_u6_review_d','unit_review','M2-1-u6-C5',2,'mc','auto','7 + 7 + 7 + 7을 곱셈식으로 나타내면 어느 것인가요?',ARRAY['M2-1-u6-X12','M2-1-u6-X11']::text[],true,'{"seq":9,"concept":"M2-1-u6-C5","difficulty":2,"kind":"mc","stem":"7 + 7 + 7 + 7을 곱셈식으로 나타내면 어느 것인가요?","explanation":["7이 4번 나와요.","7을 4번 더한 것은 7 × 4예요.","7 × 4 = 28 — 덧셈식보다 짧게 쓸 수 있어요."],"variant_rule":{"mul":{"ask":"add"}},"options":[{"t":"7 × 4","correct":true},{"t":"7 × 3","mis":"M2-1-u6-X12"},{"t":"7 + 4","mis":"M2-1-u6-X11"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_d#10','math',2,1,'u6','','g2_1_math_u6_review_d','unit_review','M2-1-u6-C6',2,'mc','auto','그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M2-1-u6-X11','M2-1-u6-X03']::text[],true,'{"seq":10,"concept":"M2-1-u6-C6","difficulty":2,"kind":"mc","stem":"그림을 곱셈식으로 바르게 나타낸 것은 어느 것인가요?","explanation":["한 줄에 4개씩 5줄이에요.","4의 5배이니 곱셈식으로 4 × 5예요.","4 × 5 = 20, 모두 20개예요."],"variant_rule":{"mul":{"ask":"expr","look":"rows"}},"options":[{"t":"4 × 5","correct":true},{"t":"4 + 5","mis":"M2-1-u6-X11"},{"t":"4 × 6","mis":"M2-1-u6-X03"}],"asset":{"type":"mul_groups","item":"🍓","k":4,"n":5,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_d#11','math',2,1,'u6','','g2_1_math_u6_review_d','unit_review','M2-1-u6-C6',2,'mc','auto','자동차 한 대에 바퀴가 4개씩 있어요. 자동차 3대의 바퀴는 모두 몇 개인가요?',ARRAY['M2-1-u6-X06','M2-1-u6-X14']::text[],true,'{"seq":11,"concept":"M2-1-u6-C6","difficulty":2,"kind":"mc","stem":"자동차 한 대에 바퀴가 4개씩 있어요. 자동차 3대의 바퀴는 모두 몇 개인가요?","explanation":["자동차 한 대에 4개씩, 3대이면 4씩 3묶음이에요.","4 × 3 = 12예요.","바퀴는 모두 12개예요."],"variant_rule":{"mul":{"ask":"story"}},"options":[{"t":"12개","correct":true},{"t":"7개","mis":"M2-1-u6-X06"},{"t":"3개","mis":"M2-1-u6-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_d#12','math',2,1,'u6','','g2_1_math_u6_review_d','unit_review','M2-1-u6-C6',2,'mc','auto','3 × 7과 곱이 같은 곱셈식은 어느 것인가요?',ARRAY['M2-1-u6-X13']::text[],true,'{"seq":12,"concept":"M2-1-u6-C6","difficulty":2,"kind":"mc","stem":"3 × 7과 곱이 같은 곱셈식은 어느 것인가요?","explanation":["3 × 7은 3씩 7묶음, 7 × 3은 7씩 3묶음이에요.","같은 21개를 가로로 묶느냐 세로로 묶느냐의 차이예요.","그래서 3 × 7과 7 × 3의 곱은 21로 같아요."],"variant_rule":{"mul":{"ask":"same"}},"options":[{"t":"7 × 3","correct":true},{"t":"3 × 3","mis":"M2-1-u6-X13"},{"t":"7 × 7","mis":"M2-1-u6-X13"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_d#13','math',2,1,'u6','','g2_1_math_u6_review_d','unit_review','M2-1-u6-C2',2,'mc','auto','그림의 달걀을 6개씩 묶으면 몇 묶음인가요?',ARRAY['M2-1-u6-X04','M2-1-u6-X05']::text[],true,'{"seq":13,"concept":"M2-1-u6-C2","difficulty":2,"kind":"mc","stem":"그림의 달걀을 6개씩 묶으면 몇 묶음인가요?","explanation":["달걀은 모두 24개예요.","6개씩 묶으면 6, 12, 18, 24 — 4번 묶여요.","그래서 6씩 4묶음이에요."],"variant_rule":{"mul":{"ask":"groups"}},"options":[{"t":"4묶음","correct":true},{"t":"6묶음","mis":"M2-1-u6-X04"},{"t":"24묶음","mis":"M2-1-u6-X05"}],"asset":{"type":"mul_groups","item":"🥚","look":"loose","total":24,"cols":7}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_d#14','math',2,1,'u6','','g2_1_math_u6_review_d','unit_review','M2-1-u6-C4',2,'mc','auto','당근은 4개, 딸기는 16개예요. 딸기의 수는 당근의 수의 몇 배인가요?',ARRAY['M2-1-u6-X09']::text[],true,'{"seq":14,"concept":"M2-1-u6-C4","difficulty":2,"kind":"mc","stem":"당근은 4개, 딸기는 16개예요. 딸기의 수는 당근의 수의 몇 배인가요?","explanation":["당근 4개가 기준이에요.","딸기 16개를 4개씩 묶으면 4묶음이에요.","그래서 딸기의 수는 당근의 수의 4배예요."],"variant_rule":{"mul":{"ask":"cmp"}},"options":[{"t":"4배","correct":true},{"t":"16배","mis":"M2-1-u6-X09"},{"t":"12배","mis":"M2-1-u6-X09"}],"asset":{"type":"times_bars","base":4,"times":4,"a":"당근","b":"딸기","item":"🥕","item2":"🍓"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_d#15','math',2,1,'u6','','g2_1_math_u6_review_d','unit_review','M2-1-u6-C3',2,'ox','auto','4의 1배는 1이에요.',ARRAY['M2-1-u6-X05']::text[],false,'{"seq":15,"concept":"M2-1-u6-C3","difficulty":2,"kind":"ox","stem":"4의 1배는 1이에요.","answer":"X","reason_options":[{"t":"4씩 1묶음이니 4니까","correct":true},{"t":"1배는 1개라는 뜻이니까","mis":"M2-1-u6-X05"}],"mis":"M2-1-u6-X05","explanation":["4의 1배는 4씩 1묶음이에요.","4씩 1묶음은 4개예요.","그래서 4의 1배는 4예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_d#16','math',2,1,'u6','','g2_1_math_u6_review_d','unit_review','M2-1-u6-C7',2,'match','auto','같은 뜻을 나타내는 것끼리 이으세요.','{}'::text[],false,'{"seq":16,"concept":"M2-1-u6-C7","difficulty":2,"kind":"match","stem":"같은 뜻을 나타내는 것끼리 이으세요.","pairs":[{"l":"6 + 6","r":"6 × 2"},{"l":"2씩 6묶음","r":"2 × 6"},{"l":"3의 6배","r":"3 × 6"}],"mis":"M2-1-u6-X07","explanation":["6 + 6은 6을 2번 더했으니 6 × 2예요.","2씩 6묶음은 2의 6배, 2 × 6이에요.","3의 6배는 3 × 6이에요 — 「몇의」 수가 × 앞에 와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_d#17','math',2,1,'u6','','g2_1_math_u6_review_d','unit_review','M2-1-u6-C6',3,'mc','auto','곱이 30인 곱셈식이 아닌 것은 어느 것인가요?',ARRAY['M2-1-u6-X15']::text[],true,'{"seq":17,"concept":"M2-1-u6-C6","difficulty":3,"kind":"mc","stem":"곱이 30인 곱셈식이 아닌 것은 어느 것인가요?","explanation":["7 × 4 = 28이에요.","나머지 곱셈식의 곱은 모두 30이에요.","「아닌 것」을 묻는지 다시 읽어요 — 같은 수도 여러 곱셈식으로 나타낼 수 있어요."],"variant_rule":{"mul":{"ask":"notx"}},"options":[{"t":"7 × 4","correct":true},{"t":"6 × 5","mis":"M2-1-u6-X15"},{"t":"5 × 6","mis":"M2-1-u6-X15"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_d#18','math',2,1,'u6','','g2_1_math_u6_review_d','unit_review','M2-1-u6-C3',3,'mc','auto','사탕 30개를 6개씩 묶으면 6의 5배예요. 같은 사탕을 5개씩 묶으면 5의 몇 배인가요?',ARRAY['M2-1-u6-X08','M2-1-u6-X05']::text[],true,'{"seq":18,"concept":"M2-1-u6-C3","difficulty":3,"kind":"mc","stem":"사탕 30개를 6개씩 묶으면 6의 5배예요. 같은 사탕을 5개씩 묶으면 5의 몇 배인가요?","explanation":["5개씩 묶으면 5, 10, 15, 20, 25, 30 — 6묶음이에요.","그래서 5의 6배예요.","같은 30개라도 묶는 수가 달라지면 몇 배인지도 달라져요."],"variant_rule":{"mul":{"ask":"regroup"}},"options":[{"t":"6배","correct":true},{"t":"5배","mis":"M2-1-u6-X08"},{"t":"30배","mis":"M2-1-u6-X05"}],"asset":{"type":"mul_groups","item":"🍬","look":"loose","total":30,"cols":8}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_d#19','math',2,1,'u6','','g2_1_math_u6_review_d','unit_review','M2-1-u6-C4',3,'mc','auto','보라 막대의 길이는 분홍 막대의 길이의 몇 배인가요?',ARRAY['M2-1-u6-X10','M2-1-u6-X09']::text[],true,'{"seq":19,"concept":"M2-1-u6-C4","difficulty":3,"kind":"mc","stem":"보라 막대의 길이는 분홍 막대의 길이의 몇 배인가요?","explanation":["분홍 막대는 3칸, 보라 막대는 12칸이에요.","3칸씩 묶으면 보라 막대는 4묶음이에요.","그래서 보라 막대는 분홍 막대의 4배예요 — 칸 수를 그대로 배로 말하면 안 돼요."],"variant_rule":{"mul":{"ask":"bars","grid":true}},"options":[{"t":"4배","correct":true},{"t":"5배","mis":"M2-1-u6-X10"},{"t":"12배","mis":"M2-1-u6-X09"}],"asset":{"type":"times_bars","base":3,"times":4,"a":"분홍","b":"보라","grid":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_d#20','math',2,1,'u6','','g2_1_math_u6_review_d','unit_review','M2-1-u6-C7',3,'mc','auto','곱셈 카드 「2 × 5」와 같은 뜻이 아닌 것은 어느 것인가요?',ARRAY['M2-1-u6-X15']::text[],false,'{"seq":20,"concept":"M2-1-u6-C7","difficulty":3,"kind":"mc","stem":"곱셈 카드 「2 × 5」와 같은 뜻이 아닌 것은 어느 것인가요?","options":[{"t":"2씩 2묶음","correct":true},{"t":"2 + 2 + 2 + 2 + 2","mis":"M2-1-u6-X15"},{"t":"2씩 5묶음","mis":"M2-1-u6-X15"},{"t":"2의 5배","mis":"M2-1-u6-X15"}],"explanation":["2 × 5는 2를 5번 더한 것이에요.","2 + 2 + 2 + 2 + 2, 2씩 5묶음, 2의 5배는 모두 같은 뜻이에요.","2씩 2묶음은 4라 달라요 — 「아닌 것」을 물었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_d#21','math',2,1,'u6','','g2_1_math_u6_review_d','unit_review','M2-1-u6-C6',3,'mc','auto','접시 한 개에 쿠키가 3개씩 있어요. 접시 6개의 쿠키 수를 구하는 곱셈식은 어느 것인가요?',ARRAY['M2-1-u6-X11','M2-1-u6-X14']::text[],true,'{"seq":21,"concept":"M2-1-u6-C6","difficulty":3,"kind":"mc","stem":"접시 한 개에 쿠키가 3개씩 있어요. 접시 6개의 쿠키 수를 구하는 곱셈식은 어느 것인가요?","explanation":["한 개에 3개씩 — 한 묶음은 3이에요.","접시가 6개이니 3씩 6묶음, 3의 6배예요.","곱셈식은 3 × 6 = 18이에요."],"variant_rule":{"mul":{"ask":"sexpr"}},"options":[{"t":"3 × 6","correct":true},{"t":"3 + 6","mis":"M2-1-u6-X11"},{"t":"3 × 3","mis":"M2-1-u6-X14"}]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_d#22','math',2,1,'u6','','g2_1_math_u6_review_d','unit_review','M2-1-u6-C5',3,'error','auto','친구들이 곱셈에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u6-X06','M2-1-u6-X15']::text[],false,'{"seq":22,"concept":"M2-1-u6-C5","difficulty":3,"kind":"error","stem":"친구들이 곱셈에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"아린 — 「8의 3배는 11이야.」","correct":true,"mis_target":"M2-1-u6-X06"},{"t":"태민 — 「8의 3배는 8 × 3이야.」","mis":"M2-1-u6-X15"},{"t":"지안 — 「8씩 뛰어 세면 8, 16, 24야.」","mis":"M2-1-u6-X15"}],"explanation":["8의 3배는 8, 16, 24로 24예요.","아린이는 8과 3을 더했어요.","태민이와 지안이는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_d#23','math',2,1,'u6','','g2_1_math_u6_review_d','unit_review','M2-1-u6-C7',4,'essay','teacher','그림을 보고 곱셈 카드를 만들려고 해요. 그림을 덧셈식, 「몇씩 몇 묶음」, 「몇의 몇 배」, 곱셈식으로 각각 나타내고 모두 몇인지 써 보세요.','{}'::text[],false,'{"seq":23,"concept":"M2-1-u6-C7","difficulty":4,"kind":"essay","stem":"그림을 보고 곱셈 카드를 만들려고 해요. 그림을 덧셈식, 「몇씩 몇 묶음」, 「몇의 몇 배」, 곱셈식으로 각각 나타내고 모두 몇인지 써 보세요.","answer_guide":{"answer":"예: 6 + 6 = 12, 6씩 2묶음, 6의 2배, 6 × 2 = 12. 무당벌레는 모두 12마리이다.","scoring_points":["덧셈식을 바르게 썼는가","「몇씩 몇 묶음」과 「몇의 몇 배」를 바르게 썼는가","곱셈식과 답을 바르게 썼는가"]},"explanation":["한 묶음의 수와 묶음의 수를 먼저 찾아요.","같은 그림을 여러 가지로 나타낼 수 있어요.","모두 같은 수를 나타내요."],"asset":{"type":"mul_groups","item":"🐞","k":6,"n":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_d#24','math',2,1,'u6','','g2_1_math_u6_review_d','unit_review','M2-1-u6-C6',4,'essay','teacher','그림의 풍선을 두 가지 곱셈식으로 나타내고, 두 곱셈식의 곱이 같은 까닭을 써 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-1-u6-C6","difficulty":4,"kind":"essay","stem":"그림의 풍선을 두 가지 곱셈식으로 나타내고, 두 곱셈식의 곱이 같은 까닭을 써 보세요.","answer_guide":{"answer":"예: 한 줄에 5개씩 3줄이므로 5 × 3 = 15, 세로로 3개씩 5줄이므로 3 × 5 = 15. 같은 풍선을 묶는 방법만 바꾸었으므로 곱이 같다.","scoring_points":["가로로 묶은 곱셈식과 곱을 썼는가","세로로 묶은 곱셈식과 곱을 썼는가","같은 물건을 다르게 묶었을 뿐이라 곱이 같다고 썼는가"]},"explanation":["가로로 한 줄씩 묶어 보아요.","세로로 한 줄씩 묶어 보아요.","묶는 방법만 다르고 물건의 수는 같아요."],"asset":{"type":"mul_groups","item":"🎈","k":5,"n":3,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u6_review_d#25','math',2,1,'u6','','g2_1_math_u6_review_d','unit_review','M2-1-u6-C4',4,'essay','teacher','하린이는 색종이를 3장, 지호는 색종이를 18장 가지고 있어요. 지호의 색종이 수는 하린이의 색종이 수의 몇 배인지 구하고, 어떻게 구했는지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-1-u6-C4","difficulty":4,"kind":"essay","stem":"하린이는 색종이를 3장, 지호는 색종이를 18장 가지고 있어요. 지호의 색종이 수는 하린이의 색종이 수의 몇 배인지 구하고, 어떻게 구했는지 설명해 보세요.","answer_guide":{"answer":"예: 기준은 하린이의 색종이 3장이다. 18을 3씩 묶으면 3, 6, 9, 12, 15, 18로 6묶음이므로 6배이다.","scoring_points":["기준이 무엇인지 바르게 찾았는가","기준만큼씩 묶거나 이어 붙인 횟수를 셌는가","몇 배인지 바르게 답했는가"]},"explanation":["견줄 때 바탕이 되는 기준을 먼저 찾아요.","기준만큼씩 묶거나 겹치지 않게 이어 붙여 세어요.","센 횟수가 몇 배예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
